# ---------------------------------------------------------------------------
# Sexual acts are used in the friend and enemy biographies only
# ---------------------------------------------------------------------------
# Three gates decide where a sex fact may appear (the fact data itself is unchanged): the
# `_timeline` gate keeps the sex modules out of `facts["timeline"]` (so the shared
# chronicle, the section highlights and the decade theme counts never show them), the
# `_character_profiles` gate drops sex lines from a profile's deeds, and the whitelist
# admits the three modules only for ("friend","mid") and ("enemy","mid"). All three consent
# classes are kept: consensual uses the spouse / non-spouse wording, dubcon and noncon
# follow `SEX_MEM_WORDING`.
MODULE_MARRIAGE = "婚配联姻"
MODULE_DUBIOUS = "情变私通"
MODULE_SEXUAL_HARM = "强暴凌辱"
# Sex-related module set (shared by the timeline gate and the whitelists)
MODULE_SEX_MODULES = frozenset({MODULE_MARRIAGE, MODULE_DUBIOUS,
                                MODULE_SEXUAL_HARM})


def is_sex_event(ev_type):
    """Is this timeline event type sexual (judged by drama module)?

    In `_timeline` the consensual keys are already folded into `had_sex` (spouses
    switched to `had_sex_spouse`), and both are in `MODULE_SEX_MODULES`, so one
    criterion covers all three consent classes."""
    return (_TYPE2MODULE.get(ev_type) or "") in MODULE_SEX_MODULES


# Section -> drama module whitelist (the slicing scheme). Key = (article key, section key);
# combinations not listed get no timeline. Purpose: the opening and the chronicle of one
# article receive **disjoint** material, which used to be near-identical fact blocks.
MODULE_SLICE = {
    # benji: opening = origins / education / faith; chronicle = power threads (rise, war,
    # prison, feuds). Marriage and love affairs stay out of the main chronicle (they belong
    # to the household biography) and sex lines never reach the timeline, so those modules
    # only put weddings next to power threads. `家格宗支` = house founding/renaming events
    # (`_house_founding_events`), which belong in the opening only, keeping it disjoint.
    ("benji", "lead"): {"教化求学", "科考功名", "人质质任",
                        "信仰皈依", "拥戴加冕", "丧亲之恸", "家格宗支"},
    ("benji", "mid"): {"起家发迹", "失位让土", "开战兴兵", "战和胜负",
                       "战死负伤", "囚禁入狱", "获释出狱", "刑虐残暴",
                       "受辱含冤", "拥戴加冕", "结仇结怨", "死敌之仇",
                       "化仇解怨",
                       # Coronation requests and conflicts (what guests gained and
                       # fought over at the coronation) and exile go in the main
                       # chronicle's second half alongside the same-layer modules
                       "加冕索求", "加冕对抗", "流放逐出", "宴饮失仪",
                       # Births are family and politics at once (heirs, alliances,
                       # bloodline); excluding them left the chronicle with a child list but
                       # no births, and the model read a mother's delivery as the protagonist
                       # having a child. This chronicle takes timeline facts, the household
                       # biography takes domestic detail and love affairs.
                       "添丁进口", "夭折"},
    # Household biography: opening = marriage / love affairs / widowhood; chronicle = births,
    # deaths, bereavement and imprisonment (imprisonment only there, because the opening's
    # consort profile lines already carry who held them), the two halves staying disjoint.
    # Marriage and love affairs stay for the **non-sexual** relation lines (wedding, falling
    # in love, break-up, widowhood), which are this article's business.
    ("jiashi", "lead"): {"婚配联姻", "情变私通", "丧偶之痛"},
    ("jiashi", "mid"): {"添丁进口", "夭折", "丧亲之恸", "婚配联姻",
                        "情变私通", "丧友之恸", "囚禁入狱", "获释出狱",
                        "越狱脱逃"},
    # Court affairs: opening = dynastic change; chronicle = war / prison / feuds
    ("chaoju", "lead"): {"起家发迹", "失位让土", "拥戴加冕"},
    ("chaoju", "mid"): {"开战兴兵", "战和胜负", "战死负伤", "囚禁入狱",
                        "获释出狱", "结仇结怨", "死敌之仇", "拥戴加冕",
                        # Coronation requests/conflicts, same rule as benji's chronicle
                        "加冕索求", "加冕对抗", "流放逐出",
                        "丧亲之恸"},
    # The all-figures chronicle: same rule as the court chronicle
    ("qunying", "mid"): {"起家发迹", "失位让土", "开战兴兵", "战和胜负",
                         "囚禁入狱", "获释出狱", "结仇结怨", "死敌之仇",
                         "拥戴加冕",
                         "加冕索求", "加冕对抗", "流放逐出"},
    # Sexual harm: forced and semi-forced acts, deterministic who-did-what-when facts in the
    # timeline, used in the friend and enemy biographies only - hence the empty sets for the
    # secrets article (hidden matters, leverage, informants) and the household article (whose
    # domestic thread is marriage/birth/bereavement). `疾病传播` (STD transmission, which has
    # no sex act to attach to) is removed with them: same source material, other name.
    ("secrets", "lead"): set(),
    ("secrets", "mid"): set(),
    # Biography: the opening gets the subject's profile and relation origins; the chronicle his deeds.
    ("friend", "lead"): set(),
    # The subject's own sexual acts (spousal, affair, forced) belong to his own
    # biography's chronicle - the only section in the project that uses them.
    # Love affairs were already here; this adds the other two classes.
    ("friend", "mid"): {"结友知交", "挚友血盟", "丧友之恸", "结仇结怨",
                        "情变私通", "婚配联姻", "强暴凌辱"},
    ("enemy", "lead"): set(),
    ("enemy", "mid"): {"结仇结怨", "死敌之仇", "化仇解怨", "仇人死亡",
                       "情变私通", "婚配联姻", "强暴凌辱", "结友知交"},
}

# Section exclusion modules: the main and court chronicles do not take homicide,
# which the assassin biography carries as a whole; the program adds an index line
# inside those sections instead.
MODULE_EXCLUDE = {
    ("benji", "mid"): {"谋害人命"},
    ("chaoju", "mid"): {"谋害人命"},
    ("qunying", "mid"): {"谋害人命"},
}


def slice_timeline(timeline, key, section_key, names=None, exclude=True):
    """Slice the timeline by the section whitelist -> list of event texts."""
    return [e["text"] for e in slice_events(timeline, key, section_key,
                                            names=names, exclude=exclude)]

def slice_events(timeline, key, section_key, names=None, exclude=True):
    """Slice the timeline by the section whitelist -> list of event dicts.

    Takes the whitelist ∪ events with **no module** (unlabelled events come from merged
    history records and are always kept, so nothing is lost); a combination absent from
    MODULE_SLICE yields nothing. exclude=False ignores MODULE_EXCLUDE, so homicide stays in
    the main/court chronicles when the script has no assassin biography to hold it."""
    mods = MODULE_SLICE.get((key, section_key))
    if mods is None:
        return []
    blocked = MODULE_EXCLUDE.get((key, section_key)) or set()
    # With exclude=False the excluded modules are merged back into the whitelist:
    # homicide has to stay in the main/court chronicles when no assassin biography
    # exists, otherwise those events have nowhere to go
    effective = set(mods) if exclude else (set(mods) | set(blocked))
    out = []
    for e in timeline or []:
        mod = e.get("module") or ""
        if mod and mod not in effective:
            continue
        if names and not any(n and n in e.get("text", "") for n in names):
            continue
        out.append(e)
    return out


def murder_module_count(timeline):
    """Number of homicide events in the timeline (for the section index line)."""
    return sum(1 for e in (timeline or [])
               if (e.get("module") or "") == "谋害人命")



def _related_ids(f):
    """Character ids related to the protagonist, by level (timeline filtering).

    level 1: the protagonist; level 2: direct relations (parents, wives and concubines
    including former ones, children, grandchildren, daughters- and sons-in-law, and a wife's
    parents). The rest of the dynasty and the in-laws are dropped outright, so that
    distant-relative trivia does not drown the protagonist's drama. Returns {cid: level}."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return {}
    out = {pid: 1}
    chars = cache.get("characters") or {}

    def add(ids, level):
        for x in ids or []:
            if isinstance(x, int):
                out[x] = level

    prec = chars.get(str(pid)) or {}
    fam = prec.get("family") or {}

    # level 2: parents / wives / former wives and concubines / children + a wife's parents
    add(fam.get("father"), 2)
    add(fam.get("mother"), 2)
    spouses = list(dict.fromkeys(
        (fam.get("primary_spouse") or []) + (fam.get("spouse") or [])
        + (fam.get("concubine") or [])
        + (fam.get("former_spouses") or [])
        + (fam.get("former_concubines") or [])))
    add(spouses, 2)
    cur_wives = list(dict.fromkeys(
        (fam.get("primary_spouse") or []) + (fam.get("spouse") or [])
        + (fam.get("concubine") or [])))
    for sid in cur_wives:
        srec = chars.get(str(sid)) or {}
        add((srec.get("family") or {}).get("father"), 2)
        add((srec.get("family") or {}).get("mother"), 2)
    add(fam.get("child"), 2)

    # level 2: grandchildren + daughters- and sons-in-law
    for cid in (fam.get("child") or []):
        cid = int(cid)
        crec = chars.get(str(cid)) or {}
        cfam = crec.get("family") or {}
        add(cfam.get("child"), 2)
        add(cfam.get("primary_spouse"), 2)
        add(cfam.get("spouse"), 2)
    # The protagonist's lovers (became_lovers/had_sex participants, break-ups included):
    # their marriages, births and bereavements are timeline context for the drama. The
    # Carnalitas `had_sex_*` family is included, so both parties of a forced act count as
    # related characters and their profiles and timeline rows reach the articles.
    for m in prec.get("memories") or []:
        _t = str(m.get("type") or "")
        if _t in ("became_lovers", "had_sex") or _t.startswith(_SEX_MEM_PREFIX):
            for v in (m.get("participants") or {}).values():
                if isinstance(v, int) and v != pid:
                    out.setdefault(v, 2)
    return out


# Module labelling for `death` records (type "death", rendered by _death_sentence), by the
# deceased's relation to the protagonist: rival -> rival death, friend -> friend's death,
# spouse -> widowhood, otherwise -> bereavement. The relation sets are computed once for the
# whole cache (`_death_rel_sets`); rescanning "all characters x all memories" per deceased
# multiplied the timeline build cost once the eight `*_died` types were folded into `deaths`.
def _death_rel_sets(f, pid):
    """The protagonist's rival/friend id sets (from memories shared with him) -> (rivals, friends)."""
    rivals, friends = set(), set()
    if pid is None:
        return rivals, friends
    for _cid, rec in (f.cache.get("characters") or {}).items():
        for m in rec.get("memories") or []:
            parts = m.get("participants") or {}
            if not any(isinstance(v, int) and v == pid for v in parts.values()):
                continue
            t = m.get("type")
            if t in ("became_rivals", "became_grudge", "became_nemesis"):
                rivals.update(v for v in parts.values() if isinstance(v, int))
            elif t in ("became_friends", "became_soulmates",
                       "became_blood_brother"):
                friends.update(v for v in parts.values() if isinstance(v, int))
    return rivals, friends


def _death_module(f, dead_cid, rivals=None, friends=None):
    """Drama module a death timeline event belongs to (by relation; a protagonist's victim -> homicide)."""
    pid = f.cache.get("player_id")
    if pid is None:
        return "丧亲之恸"
    d = ((f.cache.get("characters") or {}).get(str(dead_cid)) or {}).get("death") or {}
    if d.get("killer") == pid:
        return "谋害人命"
    rel = (f.cache.get("characters") or {}).get(str(pid)) or {}
    fam = rel.get("family") or {}
    if dead_cid in (fam.get("primary_spouse") or []) + (fam.get("spouse") or []):
        return "丧偶之痛"
    if rivals is None or friends is None:
        rivals, friends = _death_rel_sets(f, pid)
    if dead_cid in rivals:
        return "仇人死亡"
    if dead_cid in friends:
        return "丧友之恸"
    return "丧亲之恸"


# All "someone died" memory types: every one is folded into the deceased's single
# death record, instead of splitting four into dedup and four into a generic
# sentence. The list mirrors the `*_died` templates in style.MEMORY_TEMPLATES.
_DIED_TYPES = ("relative_died", "friend_died", "rival_died", "spouse_died",
               "lover_died", "soulmate_died", "best_friend_died", "nemesis_died")

# For these bereavement types the relation word is computed from the sentence
# subject (when the kinship is decidable); `spouse_died` uses the widowhood form
# instead and is not in this tuple.
_REL_DIED_TYPES = ("relative_died", "rival_died", "friend_died", "lover_died",
                   "soulmate_died", "best_friend_died", "nemesis_died")

# The peer-relation types, whose sentence names both parties and whose counterpart therefore gets
# its kin word written straight into the sentence (see `_mem_sentence`).
_REL_PEER_TYPES = ("became_friends", "became_soulmates", "became_blood_brother",
                   "became_rivals", "became_grudge", "became_nemesis")


def _count_zh(n):
    """Chinese object count: one/two/three ... ten/twelve (distinct from the lineage ordinals)."""
    digits = "零一二三四五六七八九"
    if n == 2:
        return "两"
    if n < 10:
        return digits[n]
    if n < 20:
        return "十" + (digits[n - 10] if n > 10 else "")
    if n < 100:
        t, r = divmod(n, 10)
        return digits[t] + "十" + (digits[r] if r else "")
    return str(n)


def _ordinal_zh(n):
    """Chinese lineage ordinal: 2-9 carry the "世" suffix, 10 and above do not
    (as in "Louis XI" / "Louis XIV"). Only called with n >= 2."""
    digits = "零一二三四五六七八九"
    if n < 10:
        return digits[n] + "世"
    if n < 20:
        return "十" + (digits[n - 10] if n > 10 else "")
    if n < 100:
        t, r = divmod(n, 10)
        return digits[t] + "十" + (digits[r] if r else "")
    return str(n)


# Roman numerals at the end of a name in the game envelope / title names are converted to the
# project's Chinese lineage form. Only "CJK characters + trailing Roman numeral" is folded, so
# western abbreviations are not read as ordinals, and the value cap is 99.
_ROMAN_RUN_RE = re.compile(r"([\u4e00-\u9fff])([IVXLCDM]+)$")
_ROMAN_VAL = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def _roman_value(s):
    """Roman numeral string -> int (0 when invalid)."""
    total, prev = 0, 0
    for ch in reversed(s or ""):
        v = _ROMAN_VAL.get(ch, 0)
        if not v:
            return 0
        total += -v if v < prev else v
        prev = max(prev, v)
    return total


def _roman_ordinal_zh(text):
    """Fold a trailing Roman numeral into the Chinese lineage form; returned unchanged
    when there is no trailing Roman numeral."""
    s = str(text or "")
    m = _ROMAN_RUN_RE.search(s)
    if not m:
        return s
    n = _roman_value(m.group(2))
    if not 1 <= n <= 99:
        return s
    return s[:m.start(2)] + _ordinal_zh(n)


def _decade_lower_bound(f):
    """Lower bound of the decade-biography window: January 1 of as_of year - 10,
    never earlier than the cache's first source year. Returns 'YYYY.1.1' or None."""
    if not f.as_of:
        return None
    try:
        y = int(str(f.as_of).split(".")[0])
    except Exception:
        return None
    start = None
    srcs = f.cache.get("sources") or []
    if srcs:
        try:
            start = int(str(srcs[0]).split(".")[0])
        except Exception:
            start = None
    lo = max(y - 10, start or (y - 10))
    return f"{lo}.1.1"


# ---------------------------------------------------------------------------
# Mirror-pair detection for two-sided memories
# ---------------------------------------------------------------------------
# One event is recorded by both sides with different texts and types (attacker declared
# war / defender was attacked, winner won / loser lost, torturer / tortured, new ruler
# acceded / old ruler lost the title), which the dedup key (type, date, participant set)
# misses, so the chronicle showed the pair twice. Pairing is always by **participant
# identity**: two unrelated battles can occur on one day, so date plus type would conflate
# them.

# Mirror type pairs -> keep priority (higher wins, i.e. the side that initiated)
_MIRROR_KEEP = {
    "offensive_war": 2, "defensive_war": 1,
    "war_won": 2, "war_lost": 1,
    "battle_won_memory": 2, "battle_lost_memory": 1,
    "torturer_memory": 2, "tortured_memory": 1,
    "ascended_throne_memory": 2, "lost_title_memory": 1,
    # Exile between kin comes as a same-day pair (the exile holds exiled_kin, the
    # exiled holds exiled_by_kin - 20 of 32 entries formed 10 pairs), so without
    # registering it the same event produces two lines.
    "exiled_kin_memory": 2, "exiled_by_kin_memory": 1,
    # Two lovers hold same-type memories pointing at each other, so without this one event gives two lines.
    "became_lovers": 2,
}
_MIRROR_TYPE_PAIRS = (
    frozenset({"offensive_war", "defensive_war"}),
    frozenset({"war_won", "war_lost"}),
    frozenset({"battle_won_memory", "battle_lost_memory"}),
    frozenset({"torturer_memory", "tortured_memory"}),
    frozenset({"ascended_throne_memory", "lost_title_memory"}),
    frozenset({"became_lovers"}),          # same-type mirror pair
    # exile between kin: a same-day pair (exiler and exiled each hold one, slots
    # pointing at each other)
    frozenset({"exiled_kin_memory", "exiled_by_kin_memory"}),
)
# Memory types that need identity slots (owner + participants) to be paired/merged
_IDENT_TYPES = frozenset(
    set(_MIRROR_KEEP)
    | {"imprisoned", "imprisoned_other", "released_from_prison_memory",
       "escaped_from_prison_memory",
       "child_born", "first_born", "twins_born", "child_premature",
       "child_stillborn",
       # Ally wars and white peaces need ident too: rebuilding a war (pairing declaration with
       # outcome, adding opponent/casus belli/battlefield) reads the slots from ident, and
       # without these three types an ally-war line stayed at "helped an ally".
       "joined_allys_war", "war_white_peace_attacker",
       "war_white_peace_defender",
       # The three hostage viewpoints need ident to merge into one event (`_pair_hostages`)
       "hostage_created_hostage", "hostage_created_warden",
       "hostage_created_home_court", "hostage_returned_hostage",
       "hostage_returned_warden", "hostage_returned_home_court",
       "hostage_died",
       # Coronation witnessing: one memory per **guest**, worded "<guest> witnessed the
       # coronation of <crowned>". Every guest at a coronation leaves one, so when the
       # protagonist is the crowned party all those sentences carry his name mid-sentence and
       # the "protagonist named mid-sentence" overview rule counted them as him witnessing N
       # coronations (180 guests -> 180 witnessed coronations). With the owner slot, direction
       # is decided by holder, as for imprisonment; see the overview counting in `_timeline`.
       "witnessed_a_coronation_memory"}
)

_DATE_PREFIX_RE = re.compile(r"^\d+年(?:\d+月\d+日)?，")


def _sex_mirror_partner(a, b):
    """Are a/b the two sides of one sexual act?

    Carnalitas writes **one memory per side** (the actor's `..._giving_player_...` against the
    victim's `..._receiving_player_...`), the two `sex_partner` slots pointing at each other
    with consent and creation date matching. The original type key stays in ident["type"],
    because the event's type is folded to the module class (noncon/dubcon as they are,
    consensual to had_sex)."""
    ia = sex_mem_info((a.get("ident") or {}).get("type") or a.get("type"))
    ib = sex_mem_info((b.get("ident") or {}).get("type") or b.get("type"))
    if not ia or not ib:
        return False
    if ia["consent"] != ib["consent"]:
        return False
    if ia["role"] == ib["role"]:
        return False          # same side (both actor or both victim): not a mirror pair
    pa = (a.get("ident") or {}).get("parts") or {}
    pb = (b.get("ident") or {}).get("parts") or {}
    oa = (a.get("ident") or {}).get("owner")
    ob = (b.get("ident") or {}).get("owner")
    va, vb = pa.get(_SEX_PARTNER_SLOT), pb.get(_SEX_PARTNER_SLOT)
    return isinstance(va, int) and isinstance(vb, int) \
        and va == ob and vb == oa


def _mirror_partner(a, b):
    """Are a/b the two opposed sides of one event (decided by participants pointing at each other)?"""
    ta, tb = a.get("type"), b.get("type")
    # Sex memory pair (one memory per side, actor / victim)
    if _sex_mirror_partner(a, b):
        return True
    if frozenset({ta, tb}) not in _MIRROR_TYPE_PAIRS:
        return False
    pa = (a.get("ident") or {}).get("parts") or {}
    pb = (b.get("ident") or {}).get("parts") or {}
    oa = (a.get("ident") or {}).get("owner")
    ob = (b.get("ident") or {}).get("owner")

    def p(x, k):
        v = x.get(k)
        return int(v) if isinstance(v, int) else None

    if ta == tb == "became_lovers":
        # Two memories of the same love affair (the holders are each other's relation slot)
        return p(pa, "new_relation") is not None \
            and p(pa, "new_relation") == ob and p(pb, "new_relation") == oa
    if {ta, tb} == {"offensive_war", "defensive_war"}:
        return p(pa, "other_party") is not None \
            and p(pa, "other_party") == ob and p(pb, "other_party") == oa
    if {ta, tb} == {"war_won", "war_lost"}:
        return p(pa, "winner") is not None and \
            p(pa, "winner") == p(pb, "winner") and \
            p(pa, "loser") == p(pb, "loser")
    if {ta, tb} == {"battle_won_memory", "battle_lost_memory"}:
        w, l = (a, b) if ta == "battle_won_memory" else (b, a)
        pw = (w.get("ident") or {}).get("parts") or {}
        pl = (l.get("ident") or {}).get("parts") or {}
        ow = (w.get("ident") or {}).get("owner")
        ol = (l.get("ident") or {}).get("owner")
        return p(pw, "loser") is not None and p(pw, "loser") == ol \
            and p(pl, "winner") == ow
    if {ta, tb} == {"torturer_memory", "tortured_memory"}:
        t, v = (a, b) if ta == "torturer_memory" else (b, a)
        pt = (t.get("ident") or {}).get("parts") or {}
        pv = (v.get("ident") or {}).get("parts") or {}
        ot = (t.get("ident") or {}).get("owner")
        ov = (v.get("ident") or {}).get("owner")
        return p(pv, "torturer") is not None and p(pv, "torturer") == ot \
            and p(pt, "victim") == ov
    if {ta, tb} == {"ascended_throne_memory", "lost_title_memory"}:
        g, l = (a, b) if ta == "ascended_throne_memory" else (b, a)
        pg = (g.get("ident") or {}).get("parts") or {}
        pl = (l.get("ident") or {}).get("parts") or {}
        og = (g.get("ident") or {}).get("owner")
        ol = (l.get("ident") or {}).get("owner")
        return p(pg, "flavor_character") is not None and \
            p(pg, "flavor_character") == ol and p(pl, "new_holder") == og
    return False


def _mirror_rank(e, pid, pname=""):
    """Keep priority: protagonist side +2, then the initiating side (offensive/won/torturer/accession)."""
    ident = e.get("ident") or {}
    hero = 0
    if pid is not None and ident.get("owner") == pid:
        hero = 2
    elif pname and _DATE_PREFIX_RE.sub("", e.get("text") or "").startswith(pname):
        hero = 2
    return hero * 10 + _MIRROR_KEEP.get(e.get("type"), 0)


def _drop_mirror_pairs(events, pid, pname=""):
    """Drop the redundant mirrored line of one event, keeping the protagonist's side / the initiator."""
    drop = set()
    idx_by_date = {}
    for i, e in enumerate(events):
        if e.get("ident"):
            idx_by_date.setdefault(e.get("date"), []).append(i)
    for _d, idxs in idx_by_date.items():
        for ii in range(len(idxs)):
            i = idxs[ii]
            if i in drop:
                continue
            for jj in range(ii + 1, len(idxs)):
                j = idxs[jj]
                if j in drop:
                    continue
                a, b = events[i], events[j]
                if not _mirror_partner(a, b):
                    continue
                drop.add(i if _mirror_rank(a, pid, pname)
                         < _mirror_rank(b, pid, pname) else j)
                if i in drop:
                    break
    return [e for i, e in enumerate(events) if i not in drop]


# ---------------------------------------------------------------------------
# War material rebuild: pair declaration with outcome into one passage, and fill in the
# opponent / casus belli / war goal / conquered titles; battle lines gain place and opponent.
# ---------------------------------------------------------------------------
# The seven single-slot templates in `style.MEMORY_TEMPLATES` ("declared war", "was
# attacked", "won the war", "was victorious", ...) discarded the `other_party`/`loser`/
# `winner`/`war_cb`/`war_title`/`battle_location` the memory carries, and a war's
# declaration and outcome were two lines that did not recognise each other
# (`_drop_mirror_pairs` pairs by **date** only). The policy is to pair and add detail while
# dropping no fact line at all.
_WAR_START_TYPES = ("offensive_war", "defensive_war", "joined_allys_war")
_WAR_END_TYPES = ("war_won", "war_lost",
                  "war_white_peace_attacker", "war_white_peace_defender")
_WAR_MEM_TYPES = frozenset(_WAR_START_TYPES + _WAR_END_TYPES)


def _war_mem_meta(mem):
    """Strategic slots of a war memory: casus belli / goal title / claimant / attacker / ally / battlefield.

    Captured while ident is built, because ident holds only owner/parts and drops
    vars, while both pairing and wording need these."""
    out = {}
    for v in mem.get("vars") or []:
        fl = v.get("flag")
        ident = v.get("identity")
        if fl == "war_cb":
            out["cb"] = str(v.get("value") or "")
        elif fl == "war_title" and isinstance(ident, int):
            out["title"] = ident
        elif fl == "war_claimant" and isinstance(ident, int):
            out["claimant"] = ident
        elif fl == "war_attacker" and isinstance(ident, int):
            out["attacker"] = ident
        elif fl == "war_ally" and isinstance(ident, int):
            out["ally"] = ident
        elif fl == "battle_location" and isinstance(ident, int):
            out["loc"] = ident
    return out


_WAR_CB_FALLBACK = "war_memory_cb_fallback"


def _war_cb_word(f, cb):
    """Casus belli -> Chinese war name; '' when unknown (rather than a bare key).

    Two input shapes: the memory's localization key `war_memory_cb_*`, or the real CB key
    recovered from `war_history` (e.g. `pam_challenge_hof_cb`) - the localization table may
    hold a war name under the CB key itself even when the game wrote no memory key, so the
    table is tried first (clean values only) and `style.WAR_CB_ZH` second. Values with
    dynamic parameters (`[xxx|E]`) and the generic `war_memory_cb_fallback` body are dropped."""
    cb = str(cb or "")
    if not cb:
        return ""
    try:
        w = L.loc(getattr(f, "table", None) or {}, cb)
    except Exception:
        w = ""
    # Value guard: template strings must not get through - some CB names carry dynamic
    # parameters (e.g. `[seize_peripheral_duchy|E]`, `挑战[head_of_faith|E]`) and emitting one
    # would put a bare template into the text (project convention: `$`/`[` values are dropped).
    if w and w != cb and w != "战争" and "[" not in w and "$" not in w:
        return w
    w2 = _style.WAR_CB_ZH.get(cb) or ""
    return "" if ("[" in w2 or "$" in w2) else w2


def _war_cb_from_history(f, atk, dfd, date):
    """When the memory's `war_cb` is fallback/empty, recover the **real CB key** from the cached `war_history`.

    The game writes a memory key only for the CBs in its hardcoded whitelist
    (`03_bp1_scripted_effects.txt:877-996`), and a war leaves the save as soon as it ends,
    so only the per-save latch in `cache_lib._latch_war_history` can supply the real CB from
    `wars.active_wars[].casus_belli.type`.

    Matching: the memory slots atk/dfd must hit the save's `attacker`/`defender` participant
    lists as a pair, direction-agnostic (the `joined_allys_war` slots are ally/enemy and may
    be reversed), within a 2-day date tolerance; the closest `start_date` wins, '' if none."""
    if not isinstance(atk, int) or not isinstance(dfd, int):
        return ""
    rows = f.cache.get("war_history") or []
    if not rows:
        return ""
    o1 = _day_ord(date)
    best, best_gap = "", None
    for row in rows:
        if not isinstance(row, dict) or not row.get("cb"):
            continue
        a_parts = row.get("atk_parts") or []
        d_parts = row.get("dfd_parts") or []
        if not ((atk in a_parts and dfd in d_parts)
                or (dfd in a_parts and atk in d_parts)):
            # The participant list may latch only the main belligerent, so fall back to the save's attacker/defender
            if not ((row.get("attacker") == atk and row.get("defender") == dfd)
                    or (row.get("attacker") == dfd and row.get("defender") == atk)):
                continue
        gap = None
        if o1 is not None:
            o2 = _day_ord(row.get("start_date"))
            if o2 is not None:
                gap = abs(o1 - o2)
                if gap > 2:
                    continue
        if best_gap is None or (gap is not None and gap < best_gap):
            best, best_gap = str(row["cb"]), gap
    return best


def _war_cb_resolved(f, cb, atk, dfd, date):
    """A slot's `war_cb` -> a usable key: a mapped value is returned as it is, fallback/empty is resolved from history."""
    cb = str(cb or "")
    if cb and cb != _WAR_CB_FALLBACK:
        return cb
    return _war_cb_from_history(f, atk, dfd, date) or cb


def _war_slots(f, ev):
    """War event -> {"sides", "atk", "dfd", "cb", ...} or None.

    `sides` is the set of belligerents (the first part of the pairing key) and `cb`
    the casus belli (the second part). The casus belli always passes through
    `_war_cb_resolved`, so when a memory's `war_cb` is `fallback` the real CB is
    recovered from `cache["war_history"]` via the belligerents and the date."""
    ident = ev.get("ident") or {}
    if not ident:
        return None
    parts = {k: v for k, v in (ident.get("parts") or {}).items()
             if isinstance(v, int)}
    owner = ident.get("owner")
    meta = ident.get("war") or {}
    t = ev.get("type")
    cb = str(meta.get("cb") or "")
    atk_v = meta.get("attacker")
    out = None
    if t == "offensive_war":
        opp = parts.get("other_party")
        if not isinstance(owner, int) or not isinstance(opp, int):
            return None
        out = {"sides": frozenset({owner, opp}), "atk": owner, "dfd": opp,
               "cb": cb, "title": meta.get("title"),
               "claimant": meta.get("claimant")}
    elif t == "defensive_war":
        opp = parts.get("other_party")
        if not isinstance(owner, int) or not isinstance(opp, int):
            return None
        atk = atk_v if isinstance(atk_v, int) else opp
        out = {"sides": frozenset({owner, opp}), "atk": atk, "dfd": owner,
               "cb": cb, "title": meta.get("title"),
               "claimant": meta.get("claimant")}
    elif t == "joined_allys_war":
        ally, enemy = parts.get("ally"), parts.get("enemy")
        if not isinstance(ally, int) or not isinstance(enemy, int):
            return None
        atk = atk_v if isinstance(atk_v, int) else enemy
        out = {"sides": frozenset({ally, enemy}), "ally": ally, "enemy": enemy,
               "atk": atk, "dfd": enemy if atk == ally else ally, "cb": cb,
               "title": meta.get("title")}
    elif t in ("war_won", "war_lost"):
        w, l = parts.get("winner"), parts.get("loser")
        if not isinstance(w, int):
            w = owner if t == "war_won" and isinstance(owner, int) else None
        if not isinstance(l, int):
            l = owner if t == "war_lost" and isinstance(owner, int) else None
        if not isinstance(w, int) or not isinstance(l, int):
            return None
        out = {"sides": frozenset({w, l}), "winner": w, "loser": l,
               "atk": atk_v if isinstance(atk_v, int) else w, "dfd": l, "cb": cb,
               "title": meta.get("title")}
    elif t in ("war_white_peace_attacker", "war_white_peace_defender"):
        a, d = parts.get("attacker"), parts.get("defender")
        if not isinstance(a, int):
            a = owner if t == "war_white_peace_attacker" else None
        if not isinstance(d, int):
            d = owner if t == "war_white_peace_defender" else None
        if not isinstance(a, int) or not isinstance(d, int):
            return None
        out = {"sides": frozenset({a, d}), "atk": a, "dfd": d, "white": True,
               "cb": cb, "title": meta.get("title")}
    if not isinstance(out, dict):
        return None
    out["cb"] = _war_cb_resolved(f, out.get("cb"), out.get("atk"),
                                 out.get("dfd"), ev.get("date"))
    return out


def _war_title_gain(f, winner, loser, d0, d1):
    """Title names the winner took from the loser: the loser's `lost_title_memory` whose
    `new_holder` is the winner and whose date falls in [d0, d1] (same criterion as the
    feud records' land-grab check)."""
    if not isinstance(winner, int) or not isinstance(loser, int):
        return []
    rec = (f.cache.get("characters") or {}).get(str(loser)) or {}
    out = []
    for m in rec.get("memories") or []:
        if (m.get("type") or "") != "lost_title_memory":
            continue
        if (m.get("participants") or {}).get("new_holder") != winner:
            continue
        d = str(m.get("creation_date") or "")
        if d0 and d and cl.date_key(d) < cl.date_key(d0):
            continue
        if d1 and d and cl.date_key(d) > cl.date_key(str(d1)):
            continue
        tid = next((v.get("identity") for v in (m.get("vars") or [])
                    if v.get("flag") == "landed_title" and v.get("identity")), None)
        nm = f.title(tid) if tid else ""
        if nm and nm not in out:
            out.append(nm)
    return out


def _war_start_clause(f, ev, sl):
    """War declaration clause (no date, no full stop): opponent / casus belli / goal / claimant from the slots.

    The defensive form reads "{attacker} mobilized over {cb}, {me} answered, the army turned
    towards {tname}", so the goal rides on a verb phrase and the place information is kept;
    an offensive war names the goal title once only, inside the claimant clause. The
    claimant's kinship attribute is computed here directly, because `_pair_war_events`
    rewrites this whole sentence and it never passes through the `name_index` registration."""
    t = ev.get("type")
    d = ev.get("date")
    owner = (ev.get("ident") or {}).get("owner")
    cb_key = str(sl.get("cb") or "")
    cb = _war_cb_word(f, cb_key)
    # Antipope war: say **why** it is fought, decided entirely on the program side. With CB
    # `pam_challenge_hof_cb` and an attacker who is not the antipope himself, the attacker is
    # that antipope's sponsor (the CB effect: if the sponsor wins he installs his antipope as
    # head of faith and vassalizes the sitting pope, `pam_antipope_effects.txt:434-497`).
    _manner = ""
    if cb_key == "pam_challenge_hof_cb":
        _atk = sl.get("atk")
        _mine = None
        try:
            _mine = f.antipope_office_at(_atk, d)
        except Exception:                                     # noqa: BLE001
            _mine = None
        cb = "挑战信仰领袖" if _mine is not None else "扶立对立教宗"
        _manner = "为名"
    me = f.event_name(owner, date=d) or ""
    tname = f.title(sl.get("title")) if sl.get("title") else ""

    def _cb_phrase(subject):
        """The "{subject} over {cb}..." clause; a "in the name of" casus belli closes with a comma."""
        if not cb:
            return subject
        return f"{subject}以{cb}为名，" if _manner else f"{subject}以{cb}"

    if t == "offensive_war":
        opp = f.event_name(sl["dfd"], date=d) or ""
        s = f"{_cb_phrase(me)}向{opp}开战" if cb else f"{me}向{opp}开战"
        cl = sl.get("claimant")
        if isinstance(cl, int) and cl != owner:
            cn = _claimant_name(f, cl, d, owner)
            if cn:
                # tname is named by the claim clause, so it is not repeated here
                s += f"，为{cn}索取{tname}的宣称" if tname else f"，为{cn}索取宣称"
            elif tname:
                s += f"，目标是{tname}"
        elif tname:
            s += f"，目标是{tname}"
        return s
    if t == "defensive_war":
        atk = f.event_name(sl["atk"], date=d) or ""
        s = f"{_cb_phrase(atk)}兴兵，{me}应战" if cb else f"{atk}兴兵，{me}应战"
        if tname:
            s += f"，兵锋向{tname}"
        return s
    # joined_allys_war
    ally = f.event_name(sl.get("ally"), date=d) or ""
    enemy = f.event_name(sl.get("enemy"), date=d) or ""
    s = f"{me}随{ally}出战，对抗{enemy}"
    if cb:
        s += f"，此役为{cb}"
    return s


def _claimant_name(f, cid, date, owner):
    """Claimant name with a **kinship attribute**.

    The war line is rewritten whole and never goes through `name_index`, so the kinship is
    computed here: a decidable blood relation to the line subject (the declaring side) gives
    a form such as "his nephew X", otherwise the plain name. Word forms come from
    `blood_kin_word_for` (the `NEPHEW` family, as in the household biography)."""
    nm = f.event_name(cid, date=date) or ""
    if not nm or owner is None:
        return nm
    try:
        kin = f.blood_kin_word_for(cid, owner) or ""
    except Exception:                                        # noqa: BLE001
        kin = ""
    if kin and kin not in nm:
        return f"{kin}{nm}"
    return nm



def _war_end_clause(f, ev, sl, d0):
    """War outcome clause (no date, no full stop)."""
    t = ev.get("type")
    d = ev.get("date")
    if t in ("war_won", "war_lost"):
        win = t == "war_won"
        me = f.event_name(sl["winner"] if win else sl["loser"], date=d) or ""
        foe = f.event_name(sl["loser"] if win else sl["winner"], date=d) or ""
        s = f"{me}战胜{foe}" if win else f"{me}败于{foe}"
        d1 = None
        try:
            _y, _m, _dd = (int(x) for x in str(d).split(".")[:3])
            d1 = f"{_y + 2}.{_m}.{_dd}"
        except Exception:
            d1 = None
        gains = _war_title_gain(f, sl["winner"], sl["loser"], d, d1)
        if gains:
            s += ("，夺取" if win else "，失") + "、".join(gains[:2])
            if len(gains) > 2:
                s += f"等{len(gains)}地"
        return s
    # White peace: each side holds a memory, so the holder is the subject
    owner = (ev.get("ident") or {}).get("owner")
    me = f.event_name(owner, date=d) or ""
    other = sl["dfd"] if owner == sl["atk"] else sl["atk"]
    onm = f.event_name(other, date=d) or ""
    return f"{me}与{onm}以无条件和平结束"


# ---------------------------------------------------------------------------
# Merging the hostage cycle (send out -> return / died in custody)
# ---------------------------------------------------------------------------
def _pair_hostages(events, f):
    """Merge hostage memories into one line per custody and deduplicate the three viewpoints.

    One hostage-taking writes **three** viewpoint memories in the same on_action (hostage /
    warden / home court), so they are merged by (triple, date) first. The hold key is
    `(hostage, home_court)`, because the warden can change while the home court is stable;
    repeated hostage-taking works by linear scan (a start after the previous return opens a
    new hold) and `hostage_died` ends its hold (warden viewpoint only). Closing a still-open
    hold requires positive proof - the hostage's current court is the warden's and the
    join-court date equals the start date - otherwise only the start sentence is written."""
    if not events:
        return events
    recs = []
    for i, e in enumerate(events):
        t = e.get("type")
        if t not in _HOSTAGE_MEM_TYPES:
            continue
        ident = e.get("ident") or {}
        owner = ident.get("owner")
        parts = ident.get("parts") or {}
        sl = _hostage_slots(f, owner, t, parts, e.get("date"))
        if sl is None:
            continue
        role, nms, ids = sl
        if not isinstance(ids.get("hostage"), int):
            continue
        recs.append({"i": i, "type": t, "role": role, "phase": _HOSTAGE_MEMS[t][1],
                     "date": str(e.get("date") or ""), "ids": ids, "nms": nms,
                     "owner": owner})
    if not recs:
        return events
    pid = f.cache.get("player_id")
    # Merge multiple viewpoints of one (triple, date, phase): protagonist first, then home court / hostage / warden
    _pref = {"home_court": 0, "hostage": 1, "warden": 2}
    groups = {}
    for r in recs:
        key = (r["date"], r["phase"], tuple(sorted(
            (k, v) for k, v in r["ids"].items() if isinstance(v, int))))
        groups.setdefault(key, []).append(r)
    kept, drop = [], set()
    for key, rows in groups.items():
        rows.sort(key=lambda r: (0 if (pid is not None and r["owner"] == pid) else 1,
                                 _pref.get(r["role"], 9)))
        kept.append(rows[0])
        for r in rows[1:]:
            drop.add(r["i"])
    # 2) linear pairing within each hostage
    kept.sort(key=lambda r: (r["ids"]["hostage"], cl.date_key(r["date"]),
                             0 if r["phase"] == "start" else 1))
    by_hostage = {}
    for r in kept:
        by_hostage.setdefault(r["ids"]["hostage"], []).append(r)
    for _hid, rows in by_hostage.items():
        open_holds = []
        for r in rows:
            if r["phase"] == "start":
                open_holds.append(r)
                continue
            cand = [h for h in open_holds if h["date"] <= r["date"]
                    and h["ids"] == r["ids"]]
            if not cand:
                cand = [h for h in open_holds if h["date"] <= r["date"]
                        and h["ids"].get("home_court") == r["ids"].get("home_court")]
            if not cand:
                cand = [h for h in open_holds if h["date"] <= r["date"]]
            if not cand:
                # The start memory was pruned from the cache: write the end sentence alone
                e = events[r["i"]]
                tail_tpl = (_HOSTAGE_RETURN_ONLY if r["phase"] == "end"
                            else _HOSTAGE_DIED).get(r["role"])
                nms = dict(r["nms"], owner=r["nms"].get(r["role"]) or "")
                if tail_tpl and nms["owner"]:
                    e["text"] = f"{f.date(r['date'])}，{tail_tpl.format(**nms)}"
                continue
            hold = max(cand, key=lambda h: cl.date_key(h["date"]))
            open_holds.remove(hold)
            a, z = events[hold["i"]], events[r["i"]]
            nms = dict(hold["nms"], owner=hold["nms"].get(hold["role"]) or "")
            head = (_HOSTAGE_START.get(hold["role"]) or "").format(**nms) if nms["owner"] else ""
            if not head:
                continue
            span = _prison_span(hold["date"], r["date"])
            if r["phase"] == "end":
                tail = (_HOSTAGE_RETURN.get(hold["role"]) or "").format(
                    span=span or f.date(r["date"]), **nms)
            else:
                exec_like = (str((((f.cache.get("characters") or {})
                                   .get(str(hold["ids"]["hostage"])) or {})
                                  .get("death") or {}).get("reason") or "")
                             == "death_hostage_execution")
                tpl = (_HOSTAGE_EXEC if exec_like else _HOSTAGE_DIED).get(hold["role"]) or ""
                tail = tpl.format(date=f.date(r["date"]), **nms)
            a["text"] = f"{f.date(hold['date'])}，{head.rstrip('。')}{tail.rstrip('。')}。"
            drop.add(r["i"])
        # Unpaired starts need court proof for the "still in custody" wording, else only the start sentence is written
        for hold in open_holds:
            a = events[hold["i"]]
            nms = dict(hold["nms"], owner=hold["nms"].get(hold["role"]) or "")
            if not nms["owner"]:
                continue
            head = (_HOSTAGE_START.get(hold["role"]) or "").format(**nms)
            body = head.rstrip("。")
            if _hostage_court_held(f, hold["ids"].get("hostage"),
                                   hold["ids"].get("warden"), hold["date"]):
                tpl = _HOSTAGE_HELD.get(hold["role"]) or ""
                body += tpl.format(bound=f._prison_bound(), **nms).rstrip("。")
            a["text"] = f"{f.date(hold['date'])}，{body}。"
    if not drop:
        return events
    return [e for i, e in enumerate(events) if i not in drop]


def _pair_war_events(events, f):
    """Pair declaration with outcome into one passage; battle lines gain place and opponent.

    Pairing key = (belligerent id set, casus belli), the outcome being the earliest one not
    before the declaration date. The combined line is anchored on the declaration date
    ("{date}, {start clause}; {outcome date}, {outcome clause}.", the date omitted when both
    fall on one day) and the outcome line is dropped; a war with no matching outcome gets
    only the start clause, never an "outcome unknown" phrase. Battle lines are rewritten with
    the province name from `battle_location`."""
    starts, ends = [], []
    for i, e in enumerate(events):
        t = e.get("type")
        if t in _WAR_START_TYPES:
            sl = _war_slots(f, e)
            if sl:
                starts.append((i, sl))
        elif t in _WAR_END_TYPES:
            sl = _war_slots(f, e)
            if sl:
                ends.append((i, sl))
    used, drop = set(), set()
    for i, st in starts:
        d0 = str(events[i].get("date") or "")
        best = None
        for j, en in ends:
            if j in used or en["sides"] != st["sides"]:
                continue
            dj = str(events[j].get("date") or "")
            if d0 and dj and cl.date_key(dj) < cl.date_key(d0):
                continue
            if st.get("cb") and en.get("cb") and st["cb"] != en["cb"]:
                continue
            if best is None or cl.date_key(dj) < cl.date_key(
                    str(events[best[0]].get("date") or "")):
                best = (j, en)
        if best is None:
            # No outcome found: fill in the start clause and write no "outcome unknown" phrase
            head = _war_start_clause(f, events[i], st)
            if head:
                events[i]["text"] = f"{f.date(d0)}，{head}。"
            continue
        j, en = best
        used.add(j)
        drop.add(j)
        head = _war_start_clause(f, events[i], st)
        tail = _war_end_clause(f, events[j], en, d0)
        dj = str(events[j].get("date") or "")
        if dj and dj != d0:
            body = f"{head}；{f.date(dj)}，{tail}"
        else:
            body = f"{head}；{tail}"
        events[i]["text"] = f"{f.date(d0)}，{body}。"
    # Unpaired outcome lines (mirror of a frozen declaration, or a pruned declaration memory) also get filled in
    for j, en in ends:
        if j in used:
            continue
        tail = _war_end_clause(f, events[j], en, None)
        dj = str(events[j].get("date") or "")
        if tail:
            events[j]["text"] = f"{f.date(dj)}，{tail}。"
    # Battle lines gain place and opponent
    for e in events:
        t = e.get("type")
        if t not in ("battle_won_memory", "battle_lost_memory"):
            continue
        sl = _war_slots(f, e)
        _ = sl
        ident = e.get("ident") or {}
        parts = ident.get("parts") or {}
        meta = ident.get("war") or {}
        owner = ident.get("owner")
        d = e.get("date")
        me = f.event_name(owner, date=d) or ""
        if not me:
            continue
        if t == "battle_won_memory":
            foe = f.event_name(parts.get("loser"), date=d) or ""
            verb = "战胜"
        else:
            foe = f.event_name(parts.get("winner"), date=d) or ""
            verb = "败于"
        loc = _province_label(f, meta.get("loc")) if meta.get("loc") else ""
        if loc and foe:
            e["text"] = f"{f.date(d)}，{me}在{loc}之战中{verb}{foe}。"
        elif foe:
            e["text"] = f"{f.date(d)}，{me}{verb}{foe}。"
        elif loc:
            e["text"] = f"{f.date(d)}，{me}在{loc}之战中{'取胜' if verb == '战胜' else '失利'}。"
    return [e for i, e in enumerate(events) if i not in drop]


# ---------------------------------------------------------------------------
# Merge imprisonment with release
# ---------------------------------------------------------------------------
# Pairing "imprisoned" with the next release of the same prisoner yields one line
# ("X imprisoned Y, released N days later") instead of two, and the two viewpoints of one
# imprisonment (the prisoner's `imprisoned` and the jailer's `imprisoned_other`) also
# collapse to a single line.

def _prison_span(d0, d1):
    """Duration word between two dates (same day / N days / N months / Y years M months);
    '' when invalid or reversed. Word forms live in style.FACT_WORDING prison_* entries."""
    W = _style.FACT_WORDING
    try:
        a = datetime.date(*(int(x) for x in str(d0).split(".")[:3]))
        b = datetime.date(*(int(x) for x in str(d1).split(".")[:3]))
    except Exception:
        return ""
    if b < a:
        return ""
    days = (b - a).days
    if days == 0:
        return W["prison_same_day"]
    if days < 31:
        return W["prison_days"].format(n=days)
    months = (b.year - a.year) * 12 + (b.month - a.month) \
        - (1 if b.day < a.day else 0)
    if months < 12:
        return W["prison_months"].format(n=months)
    y, m = divmod(months, 12)
    if m:
        return W["prison_years_months"].format(y=y, m=m)
    return W["prison_years"].format(y=y)


def _enslaved_in_span(f, victim, jailer, d0, d1=None):
    """Was `victim` enslaved during the imprisonment [d0, d1]?

    The owner is the jailer (defaulting to the protagonist), since Carnalitas' enslave
    interaction is only offered against a prisoner of the actor. The criterion is the
    per-save diff `cache["enslavements"]`, with one year of tolerance at both ends:
    snapshots are always dated January 1, so an enslavement can land in the next year's
    snapshot, and a relation start up to a year after the release (or end up to a year
    before the imprisonment) still counts.

    Returns the record on a hit (callers only test truthiness), None otherwise."""
    if victim is None:
        return None
    owner = jailer
    if owner is None:
        owner = f.cache.get("player_id")
    if owner is None:
        return None
    rec = (f.cache.get("enslavements") or {}).get(f"{owner}>{victim}")
    if not isinstance(rec, dict):
        return None
    lo = cl.date_key(str(d0)) if d0 else None
    hi = cl.date_key(str(d1)) if d1 else None
    fs, la = rec.get("first_seen"), rec.get("lost_at")
    fs_k = cl.date_key(str(fs)) if fs else None
    la_k = cl.date_key(str(la)) if la else None
    # Neither end known -> undecidable
    if fs_k is None and la_k is None:
        return None
    # Tolerance of one year (snapshots are dated January 1); comparison is at year level
    if la_k is not None and lo is not None and la_k[0] + 1 < lo[0]:
        return None                 # no longer a slave more than a year before the imprisonment
    if fs_k is not None and hi is not None and fs_k[0] > hi[0] + 1:
        return None                 # became a slave more than a year after the release
    return rec


# Torture kind -> release-reason key used when a torture is folded into the imprisonment
# sentence. Castration and blinding always happen on the release day (21 of 22 torture
# memories in one save, the exception being a plain `torture`), so they fold in only when
# the torture date == the release date; plain torture, maiming and disfigurement keep their
# own line.
_PUNISH_RELEASE_KEYS = {
    "castrated": "prison_punish_castrated",
    "castrated_beardless": "prison_punish_beardless",
    "blind": "prison_punish_blinded",
    "blinded": "prison_punish_blinded",
    "torture": "prison_punish_generic",
    "disfigured": "prison_punish_generic",
    "maim_arm": "prison_punish_generic",
    "maim_leg": "prison_punish_generic",
}

# Death causes counted as a judicial killing when a custody ends in death (others: dying in prison)
_PRISON_EXEC_REASONS = frozenset({
    "death_execution", "death_punishment", "death_imprisonment",
    "death_dungeon", "death_eradicated",
})


def _punishment_on(events, victim, date):
    """victim's torture event on this exact date -> (FACT_WORDING template key, event index); None if none.

    The criterion is only "same victim + same date", with no hardcoded torture names,
    so a plain torture on another day naturally fails to match and two events are
    never merged into one."""
    for i, e in enumerate(events):
        if e.get("type") not in ("torturer_memory", "tortured_memory"):
            continue
        if str(e.get("date") or "") != str(date or ""):
            continue
        ident = e.get("ident") or {}
        parts = ident.get("parts") or {}
        owner = ident.get("owner")
        v = parts.get("victim") if e.get("type") == "torturer_memory" \
            else owner
        if isinstance(v, int) and v == victim:
            kind = ident.get("torture_kind") or "torture"
            return (_PUNISH_RELEASE_KEYS.get(kind, "prison_punish_generic"), i)
    return None


def _war_end_with(events, victim, jailer, date):
    """Same-day "this prisoner's war ended" event -> (event index, winner id) or None.

    Criterion: the event date equals the release date and one side is the victim while the
    other the jailer - either a `war_won` (winner's viewpoint, parts.loser == victim) or a
    `war_lost` (loser's viewpoint, owner == victim and parts.winner == jailer). The two
    memories mirror each other and the timeline keeps one. With an unknown jailer only wars
    the victim lost count."""
    dk = cl.date_key(str(date)) if date else None
    for i, e in enumerate(events):
        t = e.get("type")
        if t not in ("war_won", "war_lost"):
            continue
        if dk is not None and cl.date_key(str(e.get("date"))) != dk:
            continue
        ident = e.get("ident") or {}
        parts = ident.get("parts") or {}
        owner = ident.get("owner")
        winner = parts.get("winner")
        loser = parts.get("loser")
        if t == "war_won":
            if loser == victim and (jailer is None or winner == jailer):
                return (i, winner)
        else:
            if owner == victim and (jailer is None or winner == jailer):
                return (i, winner)
    return None


def _pair_imprisonments(events, f, pid, pname=""):
    """Merge one prisoner's imprisonment and release into one line; one line per imprisonment across viewpoints."""
    ins, outs = [], []
    for i, e in enumerate(events):
        t = e.get("type")
        ident = e.get("ident") or {}
        parts = ident.get("parts") or {}
        owner = ident.get("owner")
        if t in ("imprisoned", "imprisoned_other"):
            victim = owner if t == "imprisoned" else parts.get("imprisoned")
            jailer = parts.get("imprisoner") if t == "imprisoned" else owner
            if isinstance(victim, int):
                ins.append({"idx": i, "victim": victim, "jailer": jailer,
                            "date": e.get("date"), "hero": owner == pid,
                            "actor": t == "imprisoned_other"})
        elif t in ("released_from_prison_memory", "escaped_from_prison_memory"):
            # Two release outcomes: freed or escaped, built mutually exclusively by the
            # engine (a released memory is written only when the escape flag is unset,
            # prison_on_actions.txt)
            if isinstance(owner, int):
                outs.append({"idx": i, "victim": owner,
                             "jailer": parts.get("imprisoner"),
                             "date": e.get("date"),
                             "escape": t == "escaped_from_prison_memory"})
    # Fallback when the release memory is missing: the per-save prison_data spans record from
    # which snapshot the character was no longer held, and that snapshot date is the release
    # date (the game writes a `released` memory only on an active release, so other exits often
    # lack it and an already-free character read as "still held").
    for r in ins:
        victim = r["victim"]
        if any(o["victim"] == victim for o in outs):
            continue
        srec = (f.cache.get("characters") or {}).get(str(victim)) or {}
        # The span's closing date is only an **observation boundary**: `Facts.prison_exit`
        # already classifies "died inside the span" as a judicial killing or a death in prison
        # (a death after the closing date does not count - that person left first and died
        # later). Such a case produces no release event and falls to the death sentence below,
        # because treating it as a release once reported a mass execution as a mass release.
        _exit = f.prison_exit(victim, r["jailer"], r["date"])
        if _exit["kind"] in ("executed", "died_in_prison", "devoured"):
            continue
        for iv in srec.get("prison_history") or []:
            if not iv.get("to"):
                continue
            if cl.date_key(str(iv["to"])) < cl.date_key(str(r["date"])):
                continue
            if cl.date_key(str(iv["to"])) > cl.date_key(str(r["date"])):
                outs.append({"idx": -1, "victim": victim,
                             "jailer": iv.get("imprisoner"),
                             "date": iv["to"], "escape": False,
                             "from_prison_data": True})
            break
    if not ins:
        return events
    # Number of people imprisoned by the same jailer on the same day (the mass-capture
    # criterion, see `Facts.capture_manner`), counted on the **event** side with both
    # viewpoints rather than by re-reading memories: of seven people captured on one day six
    # had died and their `imprisoned` memories were reclaimed, so a memory lookup found one.
    _cluster = {}
    for r in ins:
        _cluster[(str(r["date"]), r["jailer"])] = \
            _cluster.get((str(r["date"]), r["jailer"]), 0) + 1
    # Take the larger of that and the jailer-side `imprisoned_other` count: a prisoner's
    # `imprisoned` memory is reclaimed when he dies, so the event side undercounts while the
    # mass-capture criterion needs the full number.
    _side = {}
    try:
        _side = f.imprison_batch_sizes()
    except Exception:
        _side = {}
    for r in ins:
        _k = (str(r["date"]), r["jailer"])
        r["n"] = max(_cluster.get(_k, 1), _side.get(_k, 0))
    drop = set()
    by_victim = {}
    for r in ins:
        by_victim.setdefault(r["victim"], []).append(r)
    for victim, rows in by_victim.items():
        # 1) merge the two viewpoints of one imprisonment (protagonist first, then the jailer side)
        groups = {}
        for r in rows:
            groups.setdefault((r["date"], r["jailer"]), []).append(r)
        kept = []
        for _key, group in groups.items():
            group.sort(key=lambda r: (0 if r["hero"] else 1,
                                      0 if r["actor"] else 1))
            kept.append(group[0])
            for r in group[1:]:
                drop.add(r["idx"])
        # 2) imprisonment -> its nearest following release (stricter when both sides name a jailer)
        kept.sort(key=lambda r: cl.date_key(str(r["date"])))
        releases = sorted((o for o in outs if o["victim"] == victim),
                          key=lambda o: cl.date_key(str(o["date"])))
        used = set()
        for r in kept:
            out = None
            for o in releases:
                if o["idx"] in used:
                    continue
                if cl.date_key(str(o["date"])) < cl.date_key(str(r["date"])):
                    continue
                if r["jailer"] is not None and o["jailer"] is not None \
                        and r["jailer"] != o["jailer"]:
                    continue
                out = o
                break
            # Naming goes through event_name: the protagonist appears by name only, and
            # taking titles at the event date would give one person two title forms inside
            # a single article (an as_of title once dated a 1075 line to 1117)
            vn = f.event_name(victim, date=f.as_of)
            if not vn:
                continue
            jn = ""
            if r["jailer"] is not None:
                jn = f.event_name(r["jailer"], date=f.as_of)
            W = _style.FACT_WORDING
            # The capture manner (diarchy / battlefield / mass seizure) is written only on hard proof.
            _cm, _cm_note = ("unknown", "")
            try:
                _cm, _cm_note = f.capture_manner(victim, r["jailer"], r["date"],
                                                 cluster_n=r.get("n") or 1)
            except Exception:
                _cm, _cm_note = ("unknown", "")
            if _cm == "diarchy":
                body = W["prison_captured_diarch"].format(jailer=jn or "其监禁者",
                                                          victim=vn)
            elif _cm in ("battle", "battle_poi"):
                body = W["prison_captured_battle"].format(jailer=jn or "其监禁者",
                                                          victim=vn)
            elif _cm == "raid":
                body = W["prison_raid_captured"].format(jailer=jn or "其监禁者",
                                                        victim=vn)
            elif _cm == "not_battle" and jn:
                # Imprisoned as a minor, so not a battlefield capture: write "detained" plus the age then
                _age = f._age_at(victim, r["date"]) if hasattr(f, "_age_at") else None
                _nm = W["prison_note_age"].format(victim=vn, n=_age) \
                    if _age is not None else vn
                body = W["prison_batch_seized"].format(jailer=jn, victim=_nm)
            elif _cm == "batch" and jn:
                # A mass imprisonment is military or kin-purge action rather than a judicial
                # arrest, but a stormed city cannot be told from a lost battle, so the wording
                # stops here and names no manner (see the tier table in `capture_manner`).
                body = W["prison_batch_seized"].format(jailer=jn, victim=vn)
            else:
                body = W["prison_jailed"].format(jailer=jn, victim=vn) if jn \
                    else W["prison_held"].format(victim=vn)
            head = body          # sentence head "X imprisoned Y"; the tail is the outcome, folding groups by tail
            o_kind = "other"     # outcome **family** (consistency criterion for same-day folding)
            # Folded lines are counted by outcome family x duration, so this line must pass the
            # duration word out (custody is written as "after N years/months", never as an end date)
            _final_span = ""
            # Ask first whether this step was enslavement: Carnalitas' enslavement effect
            # releases from prison at the same moment, so that "released" memory often means
            # enslavement rather than a release.
            owned = _enslaved_in_span(f, victim, r["jailer"],
                                      r["date"], out["date"] if out else None)
            if out is not None:
                used.add(out["idx"])
                drop.add(out["idx"])
                span = _prison_span(r["date"], out["date"])
                same = span == W["prison_same_day"]
                _final_span = span
                # Same-day castration/blinding: the punishment is the release reason and folds into this line
                pun = (None if out.get("escape")
                       else _punishment_on(events, victim, out["date"]))
                # Same-day imprisonment + release with that prisoner's war ending the same day:
                # this is a capture at the end of a war, not a catch-and-release, so it becomes
                # the victory sentence and absorbs the same-day war_won line
                _war = (_war_end_with(events, victim, r["jailer"], out["date"])
                        if same and not out.get("escape") else None)
                if _war is not None:
                    drop.add(_war[0])
                    _wn = f.event_name(_war[1], date=f.as_of) \
                        if isinstance(_war[1], int) else ""
                    # A war-end capture uses the same battlefield-capture wording as the rest:
                    # a separate template gave two phrasings for one meaning
                    body = W["prison_captured_battle"].format(
                        jailer=_wn or jn or "其监禁者", victim=vn)
                    o_kind = "war_end"
                elif pun is not None:
                    # pun = (FACT_WORDING key, event index), see _punishment_on; the same day otherwise "N days later"
                    drop.add(pun[1])
                    body += W[pun[0]].format(
                        sp=W["prison_same_day"] if same else f"{span}后",
                        jailer=jn)
                    o_kind = "punished"
                elif owned is not None and not out.get("escape"):
                    body += W["prison_enslaved"]
                    o_kind = "enslaved"
                elif out.get("escape"):
                    # An escaped prisoner is not "released": the exit wording depends on the memory type
                    body += W["prison_escape_same_day"] if same else (
                        W["prison_escaped"].format(span=span) if span
                        else W["prison_escape_on"].format(date=f.date(out["date"])))
                    o_kind = "escape"
                else:
                    # Release reason (conversion / handing over leverage / renouncing a claim /
                    # ransom / banishment ...): a single-prisoner line carries the duration, a
                    # folded multi-person cluster does not (see `_fold_prison_clusters`)
                    _mk, _mw = f.release_manner(victim, r["jailer"], out["date"])
                    if _mw:
                        if same:
                            body += f"，{W['prison_same_day']}{_mw}"
                        elif span:
                            body += f"，{span}后{_mw}"
                        else:
                            body += f"，{f.date(out['date'])}{_mw}"
                        o_kind = _mk
                    elif same:
                        body += W["prison_released_same_day"]
                        o_kind = "released"
                    elif span:
                        body += W["prison_released"].format(span=span)
                        o_kind = "released"
                    else:
                        body += W["prison_release_on"].format(
                            date=f.date(out["date"]))
                        o_kind = "released"
            elif owned is not None:
                # No release memory, but enslaved while held: that is the release reason
                body += W["prison_enslaved"]
                o_kind = "enslaved"
            else:
                # The custody ends in **death**: with a death record (not earlier than the
                # imprisonment date) and no release/escape/prison history to say otherwise,
                # the death date and manner are written; without this, such cases read as "no
                # release ever seen" even when the prisoners had been executed months later
                # (their own memories reclaimed by the engine). `prison_death_clause` falls
                # back to the melt's `dead_data` for deaths after the cache's last save.
                dd = f.prison_death_clause(victim)
                d_date = dd.get("date")
                if d_date and cl.date_key(str(d_date)) >= cl.date_key(str(r["date"])):
                    # Same form as the release sentence: "the same day" for one day, "N months
                    # later" otherwise, and a fallback date phrase when the date is unparsable
                    # so that no slot is left empty
                    _sp = _prison_span(r["date"], d_date)
                    _final_span = _sp
                    sp = W["prison_same_day"] if _sp == W["prison_same_day"] \
                        else (f"{_sp}后" if _sp else f"至{f.date(d_date)}")
                    # Killer identical to the jailer -> judicial killing (`_death_int` is a
                    # Facts method and this is a module-level function, hence the `f.` call;
                    # the sentinel 4294967295 always counts as "no killer")
                    _killer_same = (f._death_int(dd.get("killer"))
                                    == f._death_int(r["jailer"]))
                    _exec_like = (dd.get("reason") in _PRISON_EXEC_REASONS
                                  or _killer_same)
                    # Hard evidence of cannibalism outranks a generic "executed": the mod's
                    # cannibalism feature writes an eating as `death_execution`, and the remains
                    # (`devoured_by`) are the only positive proof, so without this check the
                    # timeline said "executed" while the necrology said the man was eaten. Cause
                    # and evidence must agree, so the wording changes only for an existing
                    # judicial killing whose remains were left by this very jailer.
                    _devour = bool(_exec_like and r["jailer"] is not None
                                   and f.devoured_by(r["jailer"], victim))
                    if _devour:
                        key, o_kind = "prison_died_devoured", "devoured"
                    elif _exec_like:
                        key, o_kind = "prison_died_executed", "executed"
                    else:
                        key, o_kind = "prison_died_in_prison", "died_in_prison"
                    body += W[key].format(sp=sp)
                else:
                    # Record that the story stops here: with no release memory, no prison history
                    # and no death record, the program states what happened afterwards instead of
                    # leaving silence for the model to fill in. The bound is the article's cutoff
                    # (decade) or the last save, and a handover of the jailer is written too.
                    body += W["prison_still_held"].format(bound=f._prison_bound())
                    body += f.prison_handover_clause(victim)
                    o_kind = "held"
            e = events[r["idx"]]
            e["text"] = f"{f.date(r['date'])}，{body}。"
            e.pop("ident", None)
            if o_kind == "war_end":
                # A war-end capture is its own type: `_fold_prison_clusters` only accepts `imprisoned`.
                e["type"] = "war_capture"
                e["module"] = "战和胜负"
                continue
            e["type"] = "imprisoned"
            e["module"] = "囚禁入狱"
            # For the same-day cluster folding: prisoner id / name / outcome family / outcome text; popped later
            e["_pm"] = {"v": victim, "vn": vn, "jn": jn,
                        "h": head, "t": body[len(head):], "o": o_kind,
                        "cm": _cm, "sp": _final_span,
                        # Whether this line is the **protagonist himself** jailing someone:
                        # after folding, "imprisoned others" is recounted as one per line or
                        # cluster
                        "jp": bool(pid is not None and r["jailer"] == pid)}
    # Release/escape memories not consumed by any imprisonment line are dropped rather than
    # turned into their own line: a release is always written **inside** the imprisonment
    # line, so a bare "X was released." is a leftover, which happens when a character was
    # imprisoned twice while the engine kept only one imprisonment memory.
    for o in outs:
        if o["idx"] >= 0 and o["idx"] not in used:
            drop.add(o["idx"])
    return [e for i, e in enumerate(events) if i not in drop]


# ---------------------------------------------------------------------------
# STD (lover's pox / great pox) transmission, one fact line each
# ---------------------------------------------------------------------------
# Source: `cache["disease_edges"]` (cache_lib._diff_disease_edges). Transmission is not a
# sexual act by itself, so it gets its own line under the `疾病传播` module (the note that
# used to be appended to sex sentences has no carrier left, since sex acts never reach the
# public timeline). Fallback names when the localization table has no key (lover's pox /
# syphilis; the early stage displays as pox)
_STD_ZH_FALLBACK = {"lovers_pox": "情人的疱疹", "great_pox": "梅毒",
                    "early_great_pox": "情人的疱疹"}


def _std_disease_zh(f, key):
    """Disease key -> game display name (localization table first, fallback table second)."""
    for cand in (f"trait_{key}", f"disease_{key}"):
        v = L.loc(f.table, cand)
        if v and not v.startswith(("$", "[")):
            return v.rstrip("。")
    return _STD_ZH_FALLBACK.get(key, key)


def _date_obj(s):
    """'1071.2.7' -> datetime.date; None for invalid input."""
    try:
        return datetime.date(*(int(x) for x in str(s).split(".")[:3]))
    except Exception:
        return None


def _std_index(f):
    """cache["disease_edges"] -> [(date, text, source, target)] (lazy, computed once).

    Dedup: one line per (patient, disease). The `health.1200/1201` re-examination reorders
    itself and can leave several edges for one infection with different dates, and a cured
    patient can be infected again, so the edge closest to the re-examination date (i.e. to
    the infection moment) is kept."""
    if getattr(f, "_std_idx", None) is not None:
        return f._std_idx
    edges = f.cache.get("disease_edges") or {}
    chars = f.cache.get("characters") or {}
    W = _style.FACT_WORDING
    buckets = {}   # (disease, patient) -> [(sort date, payload)]
    for rec in edges.values():
        if not isinstance(rec, dict):
            continue
        key = str(rec.get("disease") or "")
        zh = _std_disease_zh(f, key)
        tgt, src = rec.get("target"), rec.get("source")
        fire = _date_obj(rec.get("fire_date"))
        if not zh or not isinstance(tgt, int) or fire is None:
            continue
        if str(tgt) not in chars:
            # Patient outside the cached related set: this edge reaches no article, skip it (saves index work)
            continue
        # An infection already visible at the data's first save (first=True) has no date
        # that can be asserted, so it gets no line (the patient is still visible via his
        # profile and traits)
        if rec.get("first"):
            continue
        # Timeline fact line: the protagonist appears by name only (see Facts.event_name)
        tname = f.event_name(tgt, date=f.as_of)
        if not tname:
            continue
        sname = ""
        if isinstance(src, int) and src != tgt and str(src) in chars:
            sname = f.event_name(src, date=f.as_of)
        when = str(rec.get("first_seen") or rec.get("fire_date") or "")
        wd = _date_obj(when) or fire
        if sname:
            text = W["std_line"].format(src=sname, tgt=tname, disease=zh)
            payload = ("line", when, text, src, tgt)
        else:
            text = W["std_line_anon"].format(tgt=tname, disease=zh)
            payload = ("line", when, text, None, tgt)
        buckets.setdefault((key, tgt), []).append((wd, payload))
    out = []
    for _bk, items in buckets.items():
        items.sort(key=lambda x: x[0])
        payload = items[-1][1]
        out.append((payload[1], payload[2], payload[3], payload[4]))
    f._std_idx = out
    return f._std_idx


# ---------------------------------------------------------------------------
# Same-day imprisonment cluster folding
# ---------------------------------------------------------------------------
_PRISON_CLUSTER_MIN = 5   # same-day imprisonment lines needed before folding (one or two stay as they are)
_PRISON_FOLD_TOP = 5      # names listed at the front of a folded line, the rest become "and N others"
# Foldable outcome families: all of them, because the closing clause counts by outcome
# family x duration (see `_prison_fold_tail`), keeping each person's manner of death and
# custody duration; mass executions must fold or one day explodes into dozens of lines.
_PRISON_FOLD_KINDS = frozenset({
    "released", "converted", "hook", "claim", "ransomed", "banished",
    "recruit", "vows", "escape", "punished", "enslaved",
    "executed", "died_in_prison", "devoured", "held",
})

# Ordering of the outcome words in a folded closing clause: grave outcomes first (devoured /
# executed / died in prison), then the release reasons, and "still held" last (it carries its
# own "still held as of {save}" phrase). Ties only; different counts put the larger group first.
_PRISON_KIND_ORDER = (
    "devoured", "executed", "died_in_prison", "enslaved", "banished",
    "punished", "escape", "converted", "hook", "claim", "ransomed", "recruit",
    "vows", "released", "held", "other",
)


def _prison_fold_tail(rows, f):
    """Closing clause of a same-day imprisonment cluster (leading comma included).

    Durations are written as "after N years/months" (see `_prison_span`), never as an end
    date, and each (outcome, duration) pair forms its own group; a single group reads as one
    bulk phrase, several as "among them A, B, the rest C". The "still held" group has no
    duration, its wording already saying as of when.
    `rows` = [{"o": outcome family, "sp": duration word}] (sp optional)."""
    if not rows:
        return ""
    words = getattr(f, "_PRISON_KIND_WORD", {}) or {}

    def _word(kind):
        w = words.get(kind, "获释")
        return w.format(bound=f._prison_bound()) if "{bound}" in w else w

    cnt = {}
    for r in rows:
        k = r.get("o") or "released"
        sp = "" if k == "held" else str(r.get("sp") or "")
        cnt[(k, sp)] = cnt.get((k, sp), 0) + 1
    # Groups of one outcome family stay adjacent, and rows keep their original order inside a group
    tot = {}
    for (k, _sp), n in cnt.items():
        tot[k] = tot.get(k, 0) + n

    def _rank(item):
        (k, _sp), n = item
        # Order: family total (larger first) -> family order -> this group's count (larger
        # first); ties keep the original row order, which is already sorted by title tier
        # and reign start, so "the rest" lands on the smallest group
        return (-tot.get(k, 0),
                _PRISON_KIND_ORDER.index(k) if k in _PRISON_KIND_ORDER else 99,
                -n)

    items = sorted(cnt.items(), key=_rank)

    def _seg(n, kind, sp):
        if sp:
            return f"{n}人{sp}后{_word(kind)}"
        return f"{n}人{_word(kind)}"

    if len(items) == 1:
        (k, sp), _n = items[0]
        return "，尽数" + (f"{sp}后{_word(k)}" if sp else _word(k))
    seg = [_seg(n, k, sp) for (k, sp), n in items[:-1]]
    (lk, lsp), ln = items[-1]
    seg.append("余" + _seg(ln, lk, lsp))
    return "，其中" + "、".join(seg)



def _fold_prison_clusters(events, f):
    """Fold same-day imprisonment clusters.

    Three conditions: the same day, at least `_PRISON_CLUSTER_MIN` people, and foldable
    outcome families (from `_pm["o"]`, see `_PRISON_FOLD_KINDS`). Within the day, people
    are sorted by title tier descending then reign start ascending, the first
    `_PRISON_FOLD_TOP` are named and the rest become "and N others", with the outcomes
    written as a distribution over the original rows. Every `_pm` key is popped, so this
    private key never reaches the final facts.

    Returns `(out, saved, jp_kept)`; `jp_kept` counts surviving "protagonist as jailer"
    lines (one per folded cluster) and `_timeline` recounts "imprisoned others" from it."""
    groups, order = {}, []
    for i, e in enumerate(events):
        pm = e.get("_pm")
        if e.get("type") != "imprisoned" or not pm:
            continue
        d = e.get("date")
        if d not in groups:
            groups[d] = []
            order.append(d)
        groups[d].append(i)
    drop, added = set(), []
    saved = 0
    jp_kept = 0
    for d in order:
        idxs = groups[d]
        if len(idxs) < _PRISON_CLUSTER_MIN:
            continue
        kinds = {events[i]["_pm"].get("o") for i in idxs}
        # Folding used to require one outcome family for the whole day, which sent people
        # released for different reasons back to a bare list; counting by "outcome family x
        # duration" lets executions, deaths in prison and still-held prisoners fold too, with
        # each person's manner and duration preserved.
        if not kinds or not kinds <= _PRISON_FOLD_KINDS:
            continue
        rows = []
        for i in idxs:
            pm = events[i]["_pm"]
            rank, since = f.title_rank_since_at(pm.get("v"), d)
            rows.append({"i": i, "rank": rank, "since": since,
                         "cid": pm.get("v") or 0, "vn": pm.get("vn") or "",
                         "jn": pm.get("jn") or "", "tail": pm.get("t") or "",
                         "o": pm.get("o") or "released",
                         "sp": pm.get("sp") or "",
                         "jp": bool(pm.get("jp")),
                         "cm": pm.get("cm") or "unknown"})
        rows.sort(key=lambda r: (-r["rank"],
                                 cl.date_key(r["since"]) if r["since"] else _DATE_KEY_MAX,
                                 r["cid"]))
        named = [r for r in rows if r["vn"]]
        if not named:
            continue
        shown = "、".join(r["vn"] for r in named[:_PRISON_FOLD_TOP])
        if len(named) > _PRISON_FOLD_TOP:
            shown += f"等{len(named)}人"
        jn = named[0]["jn"]
        body = f"{jn}囚禁{shown}" if jn else f"{shown}被囚"
        # If the cluster has battlefield evidence, the whole cluster becomes a battlefield
        # capture; otherwise the bare "imprisoned" stands, because a stormed city cannot be
        # told from a lost battle and no manner word may be invented for the cluster
        if any((r.get("cm") or "") in ("battle", "battle_poi") for r in named):
            body = (f"{jn}于战阵俘获{shown}" if jn else f"{shown}于战阵被俘")
        # Raid evidence inside the cluster (the family-relation log records the jailer raiding
        # one of the cluster or his kin that day) makes the whole cluster a capture during a
        # raid; without it the bare "imprisoned" wording invited the model to invent a scene.
        elif jn and any((r.get("cm") or "") == "raid" for r in named):
            body = _style.FACT_WORDING["prison_raid_captured"].format(
                jailer=jn, victim=shown)
        # Closing clause counted by outcome family x duration, with durations as "after N
        # years/months" and no end date: the older wording carried no duration for
        # multi-person clusters and just listed the reasons.
        body += _prison_fold_tail(named, f)
        drop.update(idxs)
        saved += len(named) - 1
        if any(r.get("jp") for r in named):
            jp_kept += 1
        added.append({"date": d, "type": "imprisoned", "module": "囚禁入狱",
                      "text": f"{f.date(d)}，{body}。"})
    for i, e in enumerate(events):
        pm = e.get("_pm")
        # Lines left unfolded with the protagonist as jailer count once each (overview counting)
        if pm is not None and i not in drop and pm.get("jp"):
            jp_kept += 1
        e.pop("_pm", None)
    if not drop:
        return events, 0, jp_kept
    out = []
    for i, e in enumerate(events):
        if i in drop:
            continue
        out.append(e)
    out.extend(added)
    out.sort(key=lambda e: cl.date_key(e.get("date") or ""))
    return out, saved, jp_kept


# `_std_note_for` / `_std_suffix` were deleted together with the "sex acts stay out of
# the public timeline" rule: the carrier of that note (a timeline sex line) no longer
# exists, so STD transmission always goes through the separate `_std_index` line.


# Imprisonment memory types; the participant value is always the prisoner id (used by house-purge folding)
_PRISON_MEM_TYPES = frozenset({
    "imprisoned", "imprisoned_other",
    "released_from_prison_memory", "escaped_from_prison_memory"})


def _prison_jailer(owner_id, mem):
    """The **jailer** id of an imprisonment memory: for `imprisoned_other` the holder is
    the jailer, otherwise the `imprisoner` slot of the prisoner/release/escape side."""
    t = mem.get("type")
    if t not in _PRISON_MEM_TYPES:
        return None
    if t == "imprisoned_other":
        return int(owner_id) if isinstance(owner_id, int) else None
    j = (mem.get("participants") or {}).get("imprisoner")
    return int(j) if isinstance(j, int) else None


def _prison_victim(owner_id, mem):
    """The **prisoner** id of an imprisonment memory: for `imprisoned_other` it comes from
    the `imprisoned` slot (see PARTICIPANT_SLOTS), otherwise the holder is the prisoner.
    None for non-imprisonment memories."""
    t = mem.get("type")
    if t not in _PRISON_MEM_TYPES:
        return None
    if t == "imprisoned_other":
        v = (mem.get("participants") or {}).get("imprisoned")
        return int(v) if isinstance(v, int) else None
    return int(owner_id) if isinstance(owner_id, int) else None


def _title_mem_skip(f, owner_id, mem, pid):
    """Should this title memory be kept out of the timeline? True means drop.

    The timeline carries the protagonist's own career, and title memories bring four
    kinds of noise: enfeoffment of others (the owner is someone else and
    `flavor_character` is the protagonist, so he is the granting side - court material);
    landless offices that are created and filled at once (secretariats, censoriate,
    privy council, `e_minister_*`), giving a zero-day tenure; titles created and granted
    the same day; and the administrative appointment feed under celestial or
    administrative government, where anything below the protagonist's primary title is
    decided by election (see `Facts.admin_title_noise`)."""
    if mem.get("type") not in TITLE_VAR_TYPES:
        return False
    tid = None
    for v in mem.get("vars") or []:
        if v.get("flag") == "landed_title" and v.get("identity"):
            tid = v.get("identity")
            break
    if tid is None:
        return False
    parts = mem.get("participants") or {}
    if f.admin_title_noise(tid, f.mem_date(owner_id, mem) or mem.get("creation_date"),
                           pid):
        return True
    if owner_id != pid:
        # 1) enfeoffment where the protagonist is only the granting side (owner is someone else)
        return parts.get("flavor_character") == pid
    # 2) landless office
    if f.is_landless_office_title(tid):
        return True
    # 3) zero-day tenure
    return f.title_tenure_zero_day(pid, tid, f.mem_date(owner_id, mem))


# The protagonist's close kin (parents, wives/concubines, children): their births and deaths
# are part of his life story (a mother dying when he was 36, a daughter dying young), so such
# events stay in his chronicle even before his reign began. In-laws should not.
def _immediate_ids(f, pid):
    """Close-kin id set (parents, wives/concubines, children; excludes the protagonist)."""
    if pid is None:
        return set()
    rec = (f.cache.get("characters") or {}).get(str(pid)) or {}
    fam = rec.get("family") or {}
    out = set()
    for key in ("father", "mother", "primary_spouse", "spouse", "concubine",
                "former_spouses", "former_concubines", "child"):
        for x in fam.get(key) or []:
            if isinstance(x, int) and x != int(pid):
                out.add(x)
    return out


def _timeline(f):
    """Timeline of events related to the protagonist (kin set per `_related_ids`), deduplicated
    per person and per event, sorted by date. Each entry = {"date", "type", "text"} (text is
    the clean Chinese sentence; only text reaches the prompt). Outsiders are dropped (memory
    holder and all participants outside the related set); one record per deceased (death record
    > died memory > widowhood) and one per birth (protagonist/family viewpoint first); paired
    events are deduplicated by (type, date, participant set); mirror pairs and imprisonment
    pairs fold as described above."""
    cache = f.cache
    pid = cache.get("player_id")
    related = _related_ids(f)
    # "Protagonist era" gate: a successor's save still carries the whole previous reign (the
    # predecessor's memories persist and he is the successor's father/brother, hence inside
    # `related`), which once filled the new chronicle with the predecessor's deeds. An event
    # that is neither the current protagonist's own (his memory, or he among the participants)
    # nor after he became protagonist belongs to that earlier reign and was told there. The
    # first protagonist (no predecessor) has no gate.
    _era_start, _era_gate = f.protagonist_era()
    _era_key = cl.date_key(_era_start) if (_era_gate and _era_start) else None
    _close_ids = _immediate_ids(f, pid) if _era_key else set()

    def _pre_era(date, own):
        """Does this event belong to the previous reign and not concern this protagonist (so it stays out)?"""
        return bool(_era_key and not own and date
                    and cl.date_key(str(date)) < _era_key)

    # People involved in a house purge: their imprisonment memories stay out of the
    # timeline, because a single house-level line carries the whole affair. The criterion
    # is per person, following `purged_houses` ({date: purged house}).
    purge_victims = f.family_purge_victims(pid) if pid is not None else set()
    purge_houses = f.purged_houses(pid) if pid is not None else {}
    events = []        # (date, type, text)
    idents = {}        # (date, type, text) -> {"owner", "parts"}: mirror/imprisonment pairing
    seen_keys = set()  # paired-event dedup: (type, creation_date, participant set)
    deaths = {}        # deceased id -> (priority, date, type, text)
    births = {}        # (date, birth key) -> (priority, date, type, text)
    for cid, rec in (cache.get("characters") or {}).items():
        cid = int(cid)
        # This character's "death notice + inheritance" pairs (memoised per cid, read-only)
        _ipairs = f.inherit_pairs(cid)
        _consumed = f.inherit_consumed(cid)
        # The character's own death record (most complete, highest priority)
        if cid in related:
            # annotated=True: a killing by the protagonist also writes the victim's birth year,
            # culture and faith, the same note the `*_died` branch uses. Deaths from the previous
            # protagonist's era are dropped (that was his doing), except for close kin, whose
            # deaths stay even before the reign began.
            if not _pre_era((rec.get("death") or {}).get("date"),
                            cid == pid or cid in _close_ids):
                ds = _death_sentence(f, cid, annotated=True)
                if ds:
                    # Written by priority: an inheritance-merged sentence (4) must not be
                    # overridden by a death record
                    _old = deaths.get(cid)
                    if _old is None or 3 > _old[0]:
                        deaths[cid] = (3, (rec.get("death") or {}).get("date"),
                                       "death", ds)
        for mem in rec.get("memories") or []:
            parts = mem.get("participants") or {}
            owner_rel = cid in related
            part_rel = any(isinstance(v, int) and int(v) in related
                           for v in parts.values())
            if not owner_rel and not part_rel:
                continue  # outsider memory: dropped
            # "Protagonist era" gate: an event unrelated to this protagonist and earlier than
            # his accession belongs to the previous reign, while events he took part in are
            # always kept. The gate itself is documented above.
            mtype = mem.get("type")
            if mtype in _DIED_TYPES:
                # For a death notice the party that matters is the **deceased** (the holder is
                # only one party): it counts as this protagonist's business only when the
                # deceased is the protagonist or his close kin.
                _keep = (parts.get("dead_relation") == pid
                         or parts.get("dead_relation") in _close_ids)
            else:
                _keep = (cid == pid or pid in parts.values()
                         or parts.get("child") == pid)
            if _pre_era(mem.get("creation_date"), _keep):
                continue
            # Inheritance-merged sentence: a paired death notice uses the merged wording and
            # the accession memory no longer gets its own line
            _ip = _ipairs.get(id(mem)) if _ipairs else None
            # Consensual keys of the sex family fold together (noncon/dubcon keep their own
            # class) and the marital branch becomes the "spousal" wording (see ev_type below).
            # None of the classes reaches the timeline, but the folding still happens because
            # profiles and the friend/enemy biographies word them from `had_sex*`.
            _sxinfo = sex_mem_info(mtype) \
                if isinstance(mtype, str) and mtype.startswith(_SEX_MEM_PREFIX) \
                else None
            norm_type = mtype
            if _sxinfo is not None:
                norm_type = mtype if _sxinfo["kept"] else "had_sex"
            # Death-type memories: deduplicated by the deceased's id, and all eight `*_died`
            # types are collected. The deceased's real death record (reason/killer/manner) is
            # taken **first**, falling back to the memory sentence only when there is none, so
            # that a rival's cause of death (house eradication included) is not reduced to a
            # bare "the rival died".
            if mtype in _DIED_TYPES:
                dead = parts.get("dead_relation")
                if isinstance(dead, int):
                    if _ip is not None:
                        # The death notice and the new holder's accession fall on one day ->
                        # merge into a single sentence
                        _txt = f"{f.date(_ip[2])}，{_ip[0]}"
                        _old = deaths.get(dead)
                        # One deceased with several same-day heirs: merge their accessions
                        # into the same sentence
                        _head, _sep, _tail = _ip[0].partition("去世，")
                        if (_old is not None and _old[0] == 4 and _sep and _tail
                                and _ip[2] == _old[1]
                                and (_head + "去世，") in _old[3]
                                and _tail.rstrip("。") not in _old[3]):
                            _txt = _old[3].rstrip("。") + "，" + _tail
                        deaths[dead] = (4, _ip[2], "death", _txt)
                        continue
                    ds = _death_sentence(f, dead, annotated=True)
                    if ds:
                        _dd = ((cache.get("characters") or {}).get(str(dead)) or {})
                        # Written by priority (an inheritance-merged sentence, prio 4, must not be overridden)
                        _old = deaths.get(dead)
                        if _old is None or 3 > _old[0]:
                            deaths[dead] = (3, (_dd.get("death") or {}).get("date"),
                                            "death", ds)
                    else:
                        s = _mem_sentence(f, cid, mem)
                        if s:
                            prio = 2 if mtype != "spouse_died" else 1
                            old = deaths.get(dead)
                            if old is None or prio > old[0]:
                                deaths[dead] = (prio, mem.get("creation_date"),
                                                mtype, s)
                continue
            # The protagonist's own successful-murder memories: deduplicated by victim
            # (the victim's death record wins, the murder memory is the fallback) and only
            # the protagonist's plots are rendered, never an outsider's
            if mtype == "successful_murder" and cid == pid:
                dead = parts.get("victim")
                if isinstance(dead, int):
                    s = _mem_sentence(f, cid, mem)
                    if s:
                        # The victim's birth year disambiguates near-identical names, and culture
                        # and faith are added too (the save keeps `dead_unprunable` permanently, so
                        # the game can always read them). The note comes from `_victim_marks`,
                        # shared with the death-record sentence.
                        note = _victim_marks(f, dead)
                        if note:
                            s = s.rstrip("。") + note + "。"
                        # The victim's last known whereabouts before death (a barony name, omitted
                        # when the data has none): a killing has no scene, so the victim's position
                        # is the anchor rather than the protagonist's seat.
                        vp = f.victim_place(dead)
                        if vp:
                            s = s.rstrip("。") + f"，死于{vp}。"
                        old = deaths.get(dead)
                        if old is None or 2 > old[0]:
                            deaths[dead] = (2, mem.get("creation_date"),
                                            "successful_murder", s)
                continue
            # Birth-type memories: deduplicated by (date, birth key), protagonist/family
            # viewpoint first. The birth key is the **child id** whatever the memory type,
            # falling back to the mother's id when the child slot is absent, which stops the
            # same birth (or a child's death) being written twice, once per parent.
            if mtype in ("child_born", "first_born", "child_premature",
                         "child_stillborn", "twins_born"):
                child = parts.get("child")
                if isinstance(child, int):
                    child_key = ("生", child)
                else:
                    mother = parts.get("mother")
                    child_key = ("生", int(mother)) if isinstance(mother, int) \
                        else ("生", cid)
                bkey = (mem.get("creation_date"), child_key)
                prio = 2 if cid == pid else (1 if owner_rel else 0)
                s = _mem_sentence(f, cid, mem)
                if s:
                    old = births.get(bkey)
                    if old is None or prio > old[0]:
                        # Also record the child id, for the "is this the protagonist's blood" classification
                        births[bkey] = (prio, mem.get("creation_date"),
                                        mtype, s,
                                        child if isinstance(child, int) else None)
                continue
            # All other memories: paired deduplication.
            # Title memories pass a gate first: enfeoffing others / landless offices /
            # zero-day tenure stay out of the timeline
            if _title_mem_skip(f, cid, mem, pid):
                continue
            # A memory already consumed by an inheritance-merged sentence (death notice +
            # accession) gets no line of its own
            if _consumed and id(mem) in _consumed:
                continue
            # The "imprison first, expel after" side of a house purge: those people rendered one
            # by one flood the timeline (85 lines on one day in one save), so a single
            # house-level fact line carries the affair. Two criteria together: the victim is on
            # the purge list (the executed and their kin), or the day is the purge day and the
            # jailer is the protagonist - the expelled remnant holds no land and is not on the
            # execution list, so the first criterion alone would miss most of them.
            if purge_houses and norm_type in _PRISON_MEM_TYPES:
                _pd = f.mem_date(cid, mem) or mem.get("creation_date")
                _pv = _prison_victim(cid, mem)
                if _pv in purge_victims \
                        or (_prison_jailer(cid, mem) == pid
                            and f.is_purge_prisoner(_pv, pid, _pd)):
                    continue
            s = _mem_sentence(f, cid, mem)
            if not s:
                continue
            pset = frozenset(v for v in parts.values() if isinstance(v, int)) \
                | {cid}
            # Title gain/loss events use the title-history event date (the memory date lags
            # by a day), so the dedup key, the event date and the sentence date share one source
            _md = f.mem_date(cid, mem)
            key = (norm_type, _md, pset)
            if key in seen_keys:
                continue
            seen_keys.add(key)
            # Mirror/imprisonment pairing works on participant identity, registered with the
            # event (see _drop_mirror_pairs); torture memories also record the torture kind so
            # that _pair_imprisonments can fold "castrated/blinded => released the same day"
            # into the imprisonment line (see _punishment_on)
            if norm_type in _IDENT_TYPES or _sxinfo is not None:
                _ident = {"owner": cid, "parts": dict(parts), "type": mtype}
                if norm_type in ("torturer_memory", "tortured_memory"):
                    _ident["torture_kind"] = _torture_kind(f, mem) or "torture"
                # War memories carry their strategic slots (casus belli / goal title /
                # claimant / attacker / battlefield) for `_pair_war_events`, since ident
                # itself holds only owner and parts
                if norm_type in _WAR_MEM_TYPES or norm_type in (
                        "battle_won_memory", "battle_lost_memory"):
                    _ident["war"] = _war_mem_meta(mem)
                idents[(_md, norm_type, s)] = _ident
            # Sex between spouses switches class: the overview says "spousal relations" and
            # the module becomes marriage. Forced and semi-forced acts do not switch -
            # "a wife forced by her husband" is still a forced act, not marital affection.
            ev_type = norm_type
            if norm_type in ("had_sex", "became_lovers") \
                    and not (_sxinfo is not None and _sxinfo["kept"]):
                _oth = (parts or {}).get("sex_partner" if norm_type == "had_sex"
                                          else PARTICIPANT_SLOTS.get(norm_type) or "")
                if isinstance(_oth, int) and _oth != cid \
                        and f.is_spouse_pair(cid, _oth):
                    ev_type = norm_type + "_spouse"
            # Sexual acts (spousal, affair, forced, semi-forced) never enter the **public
            # timeline**: the three modules' wordings stay in character profiles and the
            # friend/enemy biographies, so here they are dropped.
            if is_sex_event(ev_type):
                continue
            # The game's own reason for a feud/nemesis
            # (`opinions.active_opinions.scripted_relations.reason`, localized) is merged
            # into the feud line rather than given its own, because the timeline has a line
            # cap: previously the timeline said only "X and Y became rivals" and the model
            # wrote that the cause was unknown, although the save held it all along. With the
            # sentence rewritten, the same-month aggregation for this type no longer matches
            # these rows (the reasons differ, so they should not merge). Both sides hold a
            # mirrored memory, so the clause is always rendered for (non-protagonist,
            # protagonist) and the (date, sentence) dedup folds the pair into one line.
            _text = s
            if ev_type in _FEUD_MEM_TYPES and pid is not None and pid in pset:
                _others = [v for v in sorted(pset) if v not in (pid, cid)]
                if cid != pid:
                    _others.append(cid)
                for _o in _others[:1]:
                    try:
                        _rs = f.relation_reason_for_pair(
                            _o, pid, _FEUD_RIVAL_KINDS, styled=True)
                    except Exception:                       # noqa: BLE001
                        _rs = []
                    if _rs:
                        _text = _rs[0].rstrip("。") + "，二人由此结仇。"
                        break
            events.append((_md, ev_type, _text,
                           _TYPE2MODULE.get(ev_type, "")))
    # STD transmission: edges with no sex act to attach to get their own line (the disease
    # spreads between lovers/consorts over time, through prostitution, or congenitally).
    # Only edges touching the related set are kept.
    for _when, _text, _src, _tgt in _std_index(f):
        if not _when:
            continue
        if not (_tgt in related or (isinstance(_src, int) and _src in related)):
            continue
        # Under the same "protagonist era" gate (a transmission in the previous reign with
        # this protagonist uninvolved is dropped)
        if _pre_era(_when, pid in (_src, _tgt)):
            continue
        events.append((_when, "std_transmission", _text, "疾病传播"))
    # Merge death records + died memories + births.
    # death records are module-tagged by relation to the deceased, and the relation sets
    # are computed once for all the deceased (see _death_rel_sets)
    _rivals, _friends = _death_rel_sets(f, pid)
    for cid, (_prio, _d, t, s) in deaths.items():
        events.append((_d, t, s, _death_module(f, cid, _rivals, _friends)))
    # The main chronicle takes every child whose **legal father** is the protagonist,
    # illegitimate ones included, naming no biological father (the chronicle tells of his
    # house); a child whose legal father is another man belongs to the household biography.
    own_birth_kids, _has_fam = (
        f.legal_children_ex(pid) if pid is not None else (set(), False))
    for _prio, _d, t, s, _kid in births.values():
        events.append((_d, t, s, "添丁进口" if t in ("child_born", "first_born", "twins_born") else "夭折",
                       {"own_birth": (_kid is None or _kid in own_birth_kids)}))
    # Faith changes (from the per-save faith diff), related characters only; there is no
    # event before the first change point, so output starts at the second entry. Goes
    # through `f.faith_rite_history`, the **same source** as the profile's faith history
    # (cache diff plus the game's own converted-faith/rite memories with exact dates), so
    # profile and timeline cannot contradict each other over one change. Only **religion**
    # changes are recorded (rite changes belong to the rites record), hence the test on the
    # faith id actually changing, with religion and rite both named in the sentence.
    for _cid_s in list(cache.get("characters") or {}):
        cid = int(_cid_s)
        if cid not in related:
            continue
        _pts = f.faith_rite_history(cid)
        for _i, (_d, _fid, _rid) in enumerate(_pts):
            if _i == 0 or _fid == _pts[_i - 1][1] or not _d:
                continue      # first point is not a change; an unchanged faith (rite only) is not "converting"
            # Under the same "protagonist era" gate (someone else's conversion in the previous reign stays out)
            if _pre_era(_d, cid == pid):
                continue
            nm = f.event_name(cid, date=_d)
            fn = f._faith_rite_label(_fid, _rid)
            if nm and fn:
                events.append((_d, "faith_changed", f"{nm}改信{fn}。", "信仰皈依"))
    # A house-level fact line for a house purge: one line for the whole affair (the
    # expelled are not named), replacing the individually dropped imprisonment lines. The
    # date prefix is added later by the `out` assembly, like every other event.
    for _pe in (f.family_purge_events(pid) if pid is not None else []):
        events.append((_pe["date"], "family_purge", _pe["text"], "诛灭世族"))
    # as_of truncation (a decade biography ends with the decade)
    if f.as_of:
        ao = cl.date_key(f.as_of)
        events = [e for e in events if e[0] and cl.date_key(e[0]) <= ao]
    # Decade window: a decade biography takes only this decade ((as_of - 10 years, as_of]), and
    # with it everything derived from the timeline - summary, chronicle, overview counts, drama
    # themes, court dynamics. Drama villain chains keep their own span and stay full-period.
    if f.decade and f.as_of:
        lo = _decade_lower_bound(f)
        if lo:
            lok = cl.date_key(lo)
            events = [e for e in events if e[0] and cl.date_key(e[0]) >= lok]
    events.sort(key=lambda x: cl.date_key(x[0]))
    # Decade/lifetime overview counts, computed before aggregation straight from the program
    # (they feed the overview block); only events naming the protagonist in the text count,
    # so family and outsider births and feuds stay out
    pname0 = f.name_with_regnal(pid)  # same form as the timeline text (the protagonist can carry a lineage numeral)
    stats = {}
    _jail_pre = 0      # pre-folding per-line "imprisoned others" count, recomputed after folding
    for _ev in events:
        _d, t, s, mod = _ev[0], _ev[1], _ev[2], _ev[3]
        # A house purge is already folded into one house-level line: count one "imprisoned
        # others" for it. That line does not contain the protagonist's name, so this branch
        # must come before the "name appears in the sentence" test.
        if t == "family_purge":
            stats["囚禁他人"] = stats.get("囚禁他人", 0) + 1
            continue
        if pname0 and pname0 not in s:
            continue
        # The imprisonment count covers only the **protagonist** being imprisoned: a victim's
        # sentence now names the jailer, so when the protagonist is that jailer his name is in
        # the sentence too and "name in sentence" no longer means imprisoned (jailing four
        # people was counted as five imprisonments). Direction follows the memory holder.
        if t == "imprisoned" and pid is not None:
            if (idents.get((_d, t, s)) or {}).get("owner") != pid:
                continue
        # Coronation witnessing is judged the same way: the sentence subject is always the
        # **guest**, the crowned party appearing only as a possessive. Counting by "the
        # protagonist's name is in the sentence" turned the 180 guests at his own coronation
        # into "witnessed 180 coronations"; his own coronation is counted from
        # held_a_coronation_memory instead.
        if t == "witnessed_a_coronation_memory" and pid is not None:
            if (idents.get((_d, t, s)) or {}).get("owner") != pid:
                continue
        if t == "imprisoned_other":
            # "Imprisoned others" is counted later, after the viewpoint merge and the same-day
            # cluster folding: counting before folding and then subtracting the saved lines
            # wholesale would now subtract a mass imprisonment down to zero, so here it only
            # reserves the key to keep the overview's word order stable.
            stats["囚禁他人"] = stats.get("囚禁他人", 0) + 1
            _jail_pre += 1
            continue
        label = _DEATH_STAT_LABEL.get(mod) if t == "death" else _STATS_LABEL.get(t)
        if label:
            stats[label] = stats.get(label, 0) + 1
    f._timeline_stats = stats
    seen = set()
    out = []
    for _ev in events:
        d, t, s, mod = _ev[0], _ev[1], _ev[2], _ev[3]
        extra = _ev[4] if len(_ev) > 4 else {}
        # The final sentence dedup includes the **date**: deduplicating by text alone would
        # silently drop a second imprisonment of one person, whose wording is word-for-word
        # identical, and a later event (a same-day castration) would then find no line to fold
        # into. Repeats on the same day with the same sentence still merge.
        if (d, s) in seen:
            continue
        seen.add((d, s))
        rec = {
            "date": d,
            "type": t,
            # Drama module tag (pure data layer; used by the decade theme extraction and the
            # article slicing)
            "module": mod or _TYPE2MODULE.get(t, ""),
            # A death sentence already contains its own date, so no date is repeated at the
            # front of the line
            "text": (s if (t == "death" or not d) else f"{f.date(d)}，{s}"),
        }
        # Blood marker for birth events: the main chronicle takes only the protagonist's own children
        if "own_birth" in extra:
            rec["own_birth"] = bool(extra["own_birth"])
        ident = idents.get((d, t, s))
        if ident:
            rec["ident"] = ident
        out.append(rec)
    # Mirror-pair dedup: only one side of each two-sided memory survives
    out = _drop_mirror_pairs(out, pid, pname0)
    # Merge imprisonment with release: this settles both the two viewpoints and the separate
    # in/out lines
    out = _pair_imprisonments(out, f, pid, pname0)
    # Same-day imprisonment cluster folding (at least 5 people, foldable outcome families),
    # named by title tier and reign seniority. The triple's third item is the number of
    # surviving "protagonist as jailer" lines (one per folded cluster), from which the
    # overview's "imprisoned others" is recomputed (see `_fold_prison_clusters`).
    out, _fold_saved, _jp_kept = _fold_prison_clusters(out, f)
    # Overview "imprisoned others" = house-purge lines (already counted as a placeholder) +
    # one for each surviving line or folded cluster
    stats["囚禁他人"] = max(0, stats.get("囚禁他人", 0) - _jail_pre) + _jp_kept
    # Hostage three-viewpoint merge and send -> return/died pairing (see `_pair_hostages`)
    out = _pair_hostages(out, f)
    # Pair war declarations with outcomes into one passage and fill in opponent / casus belli /
    # war goal / captured titles; battle lines gain place and opponent. This must run **after**
    # the imprisonment passes, because the "capture at the end of a war" test
    # (`_war_end_with`) reads the same-day war_won line, whose type an earlier merge would change.
    out = _pair_war_events(out, f)
    # Merge one activity spanning several days (cross-day witness memories of one coronation)
    out = _merge_activity_windows(out, f)
    # Merge same-day same-type collective events (witnessing a coronation, attending a grand
    # wedding, being imprisoned, jailing)
    out = _merge_same_day_events(out, f)
    # Aggregate same-month same-type routine events (feuds, grudges, allied wars, ...), then cap
    out = _merge_same_month_events(out, f)
    # Add house founding / house renaming as timeline events (see `_house_founding_events`)
    out.extend(_house_founding_events(f))
    # Final stable sort and timeline cap (criteria and order: `_cap_timeline`)
    return _cap_timeline(out, f)


# House founding / renaming as a timeline event.
#
# The fact otherwise lives only in the house-status field, which has no event slot (the
# game keeps a single `found_date` in the cache's house_history, not a memory), so the
# opening, the chronicle slice and the appendix chronicle could not share one source.
# Conventions: module "起家发迹" (enters the main chronicle's opening slice); type
# house_founded (absent from `_TYPE2MODULE`/`_STATS_LABEL`, so overview counts are
# untouched); ident.owner = the protagonist (so `_cap_timeline` ranks it level 1).
def _house_founding_events(f):
    """Timeline events for house founding / house rename / dynasty rename.

    Returns [] when there is no such history."""
    pid = f.cache.get("player_id")
    if pid is None:
        return []
    rec = (f.cache.get("characters") or {}).get(str(pid)) or {}
    hist = [h for h in (rec.get("house_history") or []) if h.get("from")]
    if f.as_of:
        ao = cl.date_key(f.as_of)
        hist = [h for h in hist if cl.date_key(str(h["from"])) <= ao]
    if len(hist) < 2:
        return []
    out = []
    for i in range(1, len(hist)):
        cur, prev = hist[i], hist[i - 1]
        d = str(cur["from"])
        hn = _house_shi(house_display(cur.get("house_name") or ""))
        dn_raw = house_display(cur.get("dynasty_name") or "")
        dn = _house_shi(dn_raw)
        p_hn = _house_shi(house_display(prev.get("house_name") or ""))
        p_dn = _house_shi(house_display(prev.get("dynasty_name") or ""))
        nm = f.event_name(pid, d) or f.name_or(pid)
        if not nm:
            continue
        new_house = cur.get("house_id") != prev.get("house_id")
        house_changed = hn != p_hn
        dyn_changed = dn != p_dn
        # The clan is named as in the house-rank sentence ("属X宗族", without "氏"). The suffix is
        # skipped when the house name already contains the clan name (Eastern name-order composite),
        # the same rule as `house_history_lines` / `clan_line`, so one relation is not stated twice.
        _east = f.name_order(pid) in cl.EASTERN_NAME_ORDERS
        clan = f"，属{dn_raw}宗族" if dn_raw and hn and dn != hn and not _east else ""
        if new_house:
            body = f"{nm}别立{hn or dn}{clan}。"
        elif house_changed and dyn_changed:
            body = f"{nm}家族与宗族并称{hn or dn}。"
        elif house_changed:
            body = f"{nm}家族改称{hn}{clan}。"
        elif dyn_changed:
            body = f"{nm}宗族改称{dn}。"
        else:
            continue
        out.append({
            "date": d,
            "type": "house_founded",
            # Dedicated module, admitted only to the 本纪 opening whitelist: semantically "rise of the
            # house", a tier that otherwise lands in the 纪事 / 朝局 opening.
            "module": "家格宗支",
            "text": f"{f.date(d)}，{body}",
            "ident": {"owner": pid, "parts": {"owner": pid},
                      "type": "house_founded"},
        })
    return out


# Decade drama themes: timeline events counted per module with the protagonist weighted x3 and the
# rest x1 (the timeline already holds only the direct line, so the x2 tier collapses); keep the top 5
# modules with all ties at 5th, after merging topic modules (bloodline enthronement etc.) in.
def _cap_timeline(out, f):
    """Cap the timeline (level 3 is already gone at the source, level 2 is what truncation removes).
    Level 1 comes from each event's `ident` rather than the text name, because after a rename his
    current name differs from the event-day name and text matching would delete his own rows
    (`ident.owner` = his own memory, a protagonist in `ident.parts` = a party to it). Events with no
    `ident` fall back to text matching. Rows are sorted stably by date and truncation keeps the
    original order, or the capped timeline would not be chronological."""
    out.sort(key=lambda _e: cl.date_key(_e.get("date") or ""))
    cap = 80 if f.as_of else 150   # decade biography (with as_of) <= 80, final / living <= 150
    if len(out) <= cap:
        return out
    pid_cap = f.cache.get("player_id")
    pname = (f.cache.get("characters") or {}).get(str(pid_cap), {}).get("name_full") or ""

    def _is_lvl1(_e):
        _ident = _e.get("ident") or {}
        if _ident:
            if _ident.get("owner") == pid_cap:
                return True
            return pid_cap in [v for v in (_ident.get("parts") or {}).values()
                               if isinstance(v, int)]
        return bool(pname) and pname in (_e.get("text") or "")

    _lvl1 = [_e for _e in out if _is_lvl1(_e)]
    _room = max(0, cap - len(_lvl1))
    _keep = {id(_e) for _e in _lvl1}
    for _e in out:                      # original order: fill the rest of the slots with level 2
        if _room <= 0:
            break
        if id(_e) not in _keep:
            _keep.add(id(_e))
            _room -= 1
    return [_e for _e in out if id(_e) in _keep]


def decade_module_top(timeline, protagonist, top_n=5):
    """Decade drama themes: [(module, score)] in descending score order, with all
    modules tied at 5th kept (may exceed 5). Returns [] with no timeline or no
    module events."""
    pname = (protagonist or {}).get("name") or ""
    score = {}
    for e in timeline or []:
        m = e.get("module") or ""
        if not m:
            continue
        w = 3 if (pname and pname in e.get("text", "")) else 1
        score[m] = score.get(m, 0) + w
    if not score:
        return []
    ranked = sorted(score.items(), key=lambda x: -x[1])
    if len(ranked) <= top_n:
        return ranked
    # top_n plus every module tied with the last kept rank
    cutoff = ranked[top_n - 1][1]
    return [r for r in ranked if r[1] >= cutoff]


def _cut_module_top(dm, top_n=5):
    """Re-sort a (module, score) list and cut it to the top `top_n` (plus ties at
    that rank); the single final cut after topic modules are merged in."""
    if not dm:
        return []
    ranked = sorted(dm, key=lambda x: -x[1])
    if len(ranked) <= top_n:
        return ranked
    cutoff = ranked[top_n - 1][1]
    return [r for r in ranked if r[1] >= cutoff]


# Same-day same-type mergeable events: type -> (regex for the variable slots, combiner). Both
# imprisonment merges are deliberately absent: their patterns are stale, and prison rows carry each
# person's release reason (获释 / 越狱 / 没为奴隶 / 处决 / 死于狱中), so one "等N人" row would erase
# every individual fate.
_MERGE_SLOT_RES = {
    # Coronation rows merge only when the host matches (the same ceremony). Fields: pat = regex for the
    # variable slots (group 0 always a name); key = absent merges the group, present splits by
    # key(groups) and never across keys; comb = merged body (argument gs, a list of m.groups() tuples);
    # cap_verb = tail after "...等N人" past _MERGE_CAP.
    "witnessed_a_coronation_memory": {
        "pat": r"^(?P<name>.+?)见证(?P<host>.+?)的加冕。$",
        "key": lambda g: g[1],
        "comb": lambda gs: "、".join(g[0] for g in gs)
                           + "见证" + gs[0][1] + "的加冕。",
        "cap_verb": lambda gs: "见证" + gs[0][1] + "的加冕。",
    },
    "grand_wedding_completed_guest": {
        "pat": r"^(?P<name>.+?)出席大婚。$",
        "comb": lambda gs: "、".join(g[0] for g in gs) + "出席大婚。",
        "cap_verb": lambda gs: "出席大婚。",
    },
}
_MERGE_CAP = 10  # max merged names; beyond this they collapse to "…等N人"


# Cross-day merge of one activity: the game writes two `witnessed_a_coronation_memory` rows for a
# single coronation (the activity finale `common/activities/activity_types/coronation.txt:3043` plus
# the guest farewell event `coronation_events.0312` at
# `events/activities/coronation_activity/coronation_events.txt:5137`, non-AI guests only), so they land
# on adjacent days and the ceremony would otherwise appear twice. Rule: same type + same host within
# `_ACTIVITY_MERGE_DAYS` -> one row, first day, witnesses unioned.
_ACTIVITY_WINDOW_TYPES = ("witnessed_a_coronation_memory",
                          "grand_wedding_completed_guest")
_ACTIVITY_MERGE_DAYS = 7


def _merge_activity_windows(events, f=None):
    """Cross-day merge of one activity. Applies only to `_ACTIVITY_WINDOW_TYPES`."""
    if not events:
        return events
    by_type = {}
    for e in events:
        t = e.get("type")
        if t in _ACTIVITY_WINDOW_TYPES:
            by_type.setdefault(t, []).append(e)
    if not by_type:
        return events
    drop = set()
    merged = {}

    for typ, entries in by_type.items():
        spec = _MERGE_SLOT_RES.get(typ)
        if not spec:
            continue
        pat = spec["pat"]

        def _body(e):
            b = e.get("text") or ""
            d = e.get("date")
            pre = f.date(d) + "，" if (d and f) else ""
            return b[len(pre):] if (pre and b.startswith(pre)) else b

        ordered = sorted(entries, key=lambda e: cl.date_key(e.get("date") or ""))
        groups = []            # [(group key, [entry…])]
        for e in ordered:
            m = re.match(pat, _body(e))
            if not m:
                continue
            gkey = spec["key"](m.groups()) if spec.get("key") else "_"
            dk = cl.date_key(e.get("date") or "")
            placed = False
            for g in groups:
                if g[0] == gkey and _daynum(e.get("date")) - _daynum(g[1][0].get("date")) \
                        <= _ACTIVITY_MERGE_DAYS:
                    g[1].append(e)
                    placed = True
                    break
            if not placed:
                groups.append((gkey, [e]))
        for gkey, g in groups:
            if len(g) < 2:
                continue
            # One person may leave a row on each of the two days, and a name slot may itself be an
            # "A、B" string -> split and dedupe so each name is listed once; fixed slots (host etc.)
            # come from the first row.
            _base = re.match(pat, _body(g[0])).groups()
            _names, _seen = [], set()
            for e in g:
                for _nm in str(re.match(pat, _body(e)).groups()[0]).split("、"):
                    _nm = _nm.strip()
                    if not _nm or _nm in _seen:
                        continue
                    _seen.add(_nm)
                    _names.append(_nm)
            gs = [tuple([_nm] + list(_base[1:])) for _nm in _names]
            if len(gs) > _MERGE_CAP:
                body = "、".join(x[0] for x in gs[:_MERGE_CAP]) + \
                    f"等{len(gs)}人" + spec["cap_verb"](gs)
            else:
                body = spec["comb"](gs)
            first = g[0]
            d = first.get("date")
            txt = f"{f.date(d)}，{body}" if (d and f) else body
            merged[id(first)] = dict(first, text=txt, activity_window=True)
            for e in g:
                if e is not first:
                    drop.add(id(e))
    if not drop and not merged:
        return events
    out = []
    for e in events:
        if id(e) in drop:
            continue
        out.append(merged.get(id(e), e))
    return out



def _merge_same_day_events(events, f=None):
    """Same-day same-type merge: collective events (many people witnessing a coronation,
    attending a wedding or imprisoned on one day, or one person imprisoning several) would
    waste model attention as many rows. Rows merge only when structurally identical apart
    from one name slot; two-slot events such as marriages are unaffected."""
    groups = {}
    order = []
    for e in events:
        key = (e.get("date"), e.get("type"))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(e)
    out = []
    for key in order:
        entries = groups[key]
        d, typ = key
        spec = _MERGE_SLOT_RES.get(typ)
        if not (spec and len(entries) > 1):
            out.extend(entries)
            continue
        pat = spec["pat"]

        def _body(e):
            b = e["text"]
            if d and f and b.startswith(f.date(d) + "，"):
                b = b[len(f.date(d)) + 1:]
            return b

        # One (date, type) group may hold several distinct events (several
        # coronations on the same day) -- split by key, so different keys stay on
        # their own rows instead of being folded into one sentence.
        if spec.get("key"):
            buckets = {}
            for e in entries:
                m = re.match(pat, _body(e))
                gk = spec["key"](m.groups()) if m else ("_nomatch", id(e))
                buckets.setdefault(gk, []).append(e)
            chunks = list(buckets.values())
        else:
            chunks = [entries]
        for chunk in chunks:
            slots, ok = [], True
            for e in chunk:
                m = re.match(pat, _body(e))
                if not m:
                    ok = False
                    break
                slots.append(m.groups())
            merged = None
            if ok and len(chunk) > 1:
                prefix = f"{f.date(d)}，" if d else ""
                names = [s[0] for s in slots]
                if len(names) > _MERGE_CAP:
                    merged = (prefix + "、".join(names[:_MERGE_CAP])
                              + f"等{len(names)}人" + spec["cap_verb"](slots))
                else:
                    merged = prefix + spec["comb"](slots)
            if merged:
                # A merged row must carry `module`, or module slicing drops the collective events
                # entirely (imprisonment etc.). The own_birth flag survives merging, judged as "all
                # of them are own children".
                _rec = {"date": d, "type": typ, "text": merged,
                        "module": chunk[0].get("module", "")}
                if any("own_birth" in e for e in chunk):
                    _rec["own_birth"] = all(e.get("own_birth") is not False
                                            for e in chunk)
                out.append(_rec)
            else:
                out.extend(chunk)
    return out





# Feud / grudge / nemesis memory types mapped to the game relation types; the timeline uses this to
# add a "结仇之由" row from the `scripted_relations.reason` localization instead of leaving the cause
# of the feud unrecorded.
_FEUD_MEM_TYPES = ("became_rivals", "became_grudge", "became_nemesis")
_FEUD_RIVAL_KINDS = ("rival", "grudge", "nemesis")

# Same-month same-type aggregation of routine events: only rows structurally identical apart from
# one variable name slot (feuds, allies' wars joined, ...).
# style: duo = "A与B结怨。" two slots; solo = "A助盟友作战。" one slot.
_AGG_SPEC = {
    "became_grudge":    {"pat": r"^(.+?)与(.+?)结怨。$",     "verb": "结怨",     "style": "duo"},
    "became_rivals":    {"pat": r"^(.+?)与(.+?)结仇。$",     "verb": "结仇",     "style": "duo"},
    "became_nemesis":   {"pat": r"^(.+?)与(.+?)结为死敌。$", "verb": "结为死敌", "style": "duo"},
    "became_friends":   {"pat": r"^(.+?)与(.+?)结为好友。$", "verb": "结为好友", "style": "duo"},
    # After the war reconstruction, ally-war rows read "{名}随{盟友}出战，对抗{敌手}[，此役为{战名}]", so the
    # old `^…助盟友作战。$` form no longer matches and aggregation is re-hung on the rich sentence: a
    # batch of call-ups in the same month for the same ally, opponent and war name becomes one row.
    "joined_allys_war": {"pat": r"^(.+?)随(.+?)出战，对抗(.+?)(，此役为(.+?))?。$",
                         "verb": "",  "style": "allies"},
}

# Pair "had_sex + became_lovers" for the same month and target. Spouses use a separate "同房" sentence
# form and merge into "夫妻情笃" (non-spouses keep "私通相恋").
_PAIR_MERGE = {
    "had_sex":            r"^(.+?)与(.+?)有私情。$",
    "had_sex_spouse":     r"^(.+?)与(.+?)同房。$",
    "became_lovers":      r"^(.+?)与(.+?)相恋。$",
    "became_lovers_spouse": r"^(.+?)与(.+?)相恋。$",
}


def _agg_line(ym, names, verb, tail):
    """One aggregate row: "870年4月，甲、乙、丙三人先后与丁结怨。"

    Up to 3 names are listed, followed by a count word (二人/三人); more than 3
    keeps the first three plus "等N人"."""
    if not names:
        return None
    y, _, m = ym.partition(".")
    cnt = ""
    if len(names) == 2:
        cnt = "二人"
    elif len(names) == 3:
        cnt = "三人"
    elif len(names) > 3:
        cnt = f"等{len(names)}人"
        names = names[:3]
    joined = "、".join(names) + cnt
    return f"{y}年{int(m)}月，{joined}{tail}{verb}。"


def _merge_same_month_events(events, f=None):
    """Same-month same-type aggregation into one row ("870年4月，甲、乙、丙三人先后与丁结怨。")
    for routine events identical apart from one name slot: saves tokens and keeps the model
    from counting dates one by one. Key events (marriage / death / child / feud / war) keep
    their exact dates."""
    groups = {}
    order = []
    for e in events:
        d = e.get("date") or ""
        ym = ".".join(str(d).split(".")[:2]) if d else ""   # YYYY.MM
        if not ym:
            continue
        key = (e.get("type"), ym)
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(e)
    out = []
    for key in order:
        entries = groups[key]
        typ, ym = key
        spec = _AGG_SPEC.get(typ)
        if spec and len(entries) >= 2:
            pat = spec["pat"]
            slots = []
            ok = True
            for e in entries:
                body = e["text"]
                d0 = e.get("date")
                if d0 and f:
                    prefix = f"{f.date(d0)}，"
                    if body.startswith(prefix):
                        body = body[len(prefix):]
                m = re.match(pat, body)
                if not m:
                    ok = False
                    break
                slots.append(m.groups())
            if ok:
                merged = None
                if spec["style"] == "solo":
                    merged = _agg_line(ym, [s[0] for s in slots],
                                       spec["verb"], "")
                elif spec["style"] == "allies":
                    # same month + ally + opponent + war name: the call-ups for
                    # one war become a single row
                    who = [s[0] for s in slots]
                    allies = {s[1] for s in slots}
                    foes = {s[2] for s in slots}
                    cbs = {(s[4] or "") for s in slots}
                    if len(allies) == 1 and len(foes) == 1:
                        tail = f"随{next(iter(allies))}出战，对抗{next(iter(foes))}"
                        if len(cbs) == 1 and next(iter(cbs)):
                            tail += f"，此役为{next(iter(cbs))}"
                        merged = _agg_line(ym, who, "", tail)
                else:
                    s0 = [s[0] for s in slots]
                    s1 = [s[1] for s in slots]
                    if len(set(s1)) == 1:
                        merged = _agg_line(ym, s0, spec["verb"], "先后与" + s1[0])
                    elif len(set(s0)) == 1:
                        merged = _agg_line(ym, s1, spec["verb"], "先后与" + s0[0])
                if merged:
                    _rec = {"date": ym, "type": typ, "text": merged,
                            "module": entries[0].get("module", "")}
                    if any("own_birth" in e for e in entries):
                        _rec["own_birth"] = all(e.get("own_birth") is not False
                                                for e in entries)
                    out.append(_rec)
                    continue
        out.extend(entries)
    return _merge_affair_pairs(out, f)


def _merge_affair_pairs(events, f=None):
    """Pair "had_sex + became_lovers" for the same pair in one month into a single
    "869年1月，甲与乙私通相恋。": two rows waste model attention and their dates differ by a
    day. Spouse pairs (recognised by the `_spouse` sentence forms) merge into "夫妻情笃" and
    switch to the `_spouse` event type, so the overview and module tiers follow."""
    slots = {}   # (ym, unordered pair) -> {type: (body sans date prefix, full text,
                 #                                      is_spouse)}
    for e in events:
        typ = e.get("type")
        pat = _PAIR_MERGE.get(typ)
        if not pat:
            continue
        d = e.get("date") or ""
        ym = ".".join(str(d).split(".")[:2]) if d else ""
        full = e["text"]
        body = full
        if d and f:
            prefix = f"{f.date(d)}，"
            if body.startswith(prefix):
                body = body[len(prefix):]
        m = re.match(pat, body)
        if not m:
            continue
        base = typ[:-len("_spouse")] if typ.endswith("_spouse") else typ
        key = (ym, frozenset((m.group(1), m.group(2))))
        slots.setdefault(key, {})[base] = (body, full, typ.endswith("_spouse"))
    drop = set()
    merged = []   # (ym, text, type)
    for (ym, _pair), got in slots.items():
        hx = got.get("had_sex")
        lv = got.get("became_lovers")
        if not hx or not lv:
            continue
        hx_body, hx_full, hx_spouse = hx
        lv_body, lv_full, lv_spouse = lv
        spouse = hx_spouse and lv_spouse
        pat = _PAIR_MERGE["had_sex_spouse" if spouse else "had_sex"]
        m = re.match(pat, hx_body)
        if not m:
            continue
        y, _, mm = ym.partition(".")
        if spouse:
            text = _FACT_WORDING["affair_pair_spouse"].format(
                y=y, m=int(mm), a=m.group(1), b=m.group(2))
            typ_out = "became_lovers_spouse"
        else:
            text = f"{y}年{int(mm)}月，{m.group(1)}与{m.group(2)}私通相恋。"
            typ_out = "became_lovers"
        merged.append((ym, text, typ_out))
        drop.add(hx_full)
        drop.add(lv_full)
    if not merged:
        return events
    out = [e for e in events if e["text"] not in drop]
    for ym, text, typ_out in merged:
        out.append({"date": ym, "type": typ_out, "text": text,
                    "module": _TYPE2MODULE.get(typ_out, "情变私通")})
    out.sort(key=lambda e: cl.date_key(e.get("date") or ""))
    return out


def _asof_ids(f, ids):
    """Filter a family member id list by `as_of` (members born after it are not listed, a
    decade biography not showing the unborn); the list is returned unchanged when `as_of` is
    empty."""
    if not f.as_of or not ids:
        return ids or []
    ao = cl.date_key(f.as_of)
    out = []
    for x in ids:
        if not isinstance(x, int):
            continue
        rec = (f.cache.get("characters") or {}).get(str(x)) or {}
        b = rec.get("birth")
        if b and cl.date_key(b) > ao:
            continue
        out.append(x)
    return out


def _protagonist(f):
    """The protagonist's profile facts (clean Chinese)."""
    cache = f.cache
    pid = cache.get("player_id")
    rec = (cache.get("characters") or {}).get(str(pid)) or {}
    melt = f.melt
    pobj = (melt.get("living") or {}).get(str(pid)) or {}
    ad = pobj.get("alive_data") or {}
    # The house name is read from the lineage as of this chapter's cut-off date:
    # after the protagonist founds or renames a house, the 【家族】 row, the title
    # sentence and the house-rank sentence must all read the same value.
    _dn, _hn = f._house_names_at(pid, f.as_of)
    p = {
        "name": f.name_with_regnal(pid, f.as_of),  # regnal numbering, at the cut-off date
        "name_zh": rec.get("name_zh") or "",
        # clan name (the surname under Eastern name order) + house/branch, given
        # only when it differs from the clan
        "house": _dynasty_display(_dn, _hn),
        "house_branch": _house_branch(_dn, _hn),
        # the single house wording used throughout, assembled from culture and name order
        "house_label": house_label(_dn, _hn, f.name_order(pid),
                                   (f._culture_entry(pid, f.as_of) or {})
                                   .get("culture_template")),
        "birth": f.date(rec.get("birth")),
        "culture": f.culture(pid, f.as_of),
        "faith": f.faith(pid),
        # "为人" split into sentences by category (disposition / ability /
        # experience ...) instead of one comma-separated list
        "traits": f.traits_sentence(pid, public=True),
        "government": f.government(pid),
    }
    langs = f.languages(pid)
    if langs:
        p["languages"] = "、".join(langs)
    # Language flavour: native tongue / also spoken, plus the language (dis)similarity
    # with wives and children. The native tongue is read at the chapter cut-off date
    # so an early chapter's ethnicity and native tongue agree.
    p["language_line"] = f.language_sentence(pid, f.as_of)
    p["language_bridge"] = f.language_bridge_line(pid)
    # per-person language relation rows with wives and children (the program states
    # the "相通 / 须通译" verdict itself)
    _lrel = f.language_relation_lines(pid)
    if _lrel:
        p["language_relations"] = _lrel
    # protagonist's office title, truncated at as_of
    poff = f.official_title(pid)
    if poff:
        p["office"] = poff
    # label unified: the profile label sentence is assembled here once, so
    # biography does not have to join office + name
    p["label"] = f.person_label(pid, date=f.as_of, style="brief") or p["name"]
    # patronymic; absent when the ancestry is unknown
    pptn = f.patronym(pid)
    if pptn:
        p["patronym"] = pptn
    thl = f.trait_history_lines(pid)
    if thl:
        p["trait_history"] = "；".join(thl)
    # faith history (the conversion process): the game keeps no memory of it, so it
    # is derived by diffing `faith` across save snapshots
    fhl = f.faith_history_lines(pid)
    if fhl:
        p["faith_history"] = "；".join(fhl)
    # A ruler who took a regnal (papal) name gets his birth name on its own row: the label runs on the
    # regnal name (the game's convention) and the birth name is given here once.
    _rbn = f.regnal_birth_name(pid, f.as_of)
    if _rbn:
        p["birth_name"] = _rbn
    # The protagonist profile deliberately omits personal tenets: 礼仪志 already carries the same fact
    # twice (礼仪档案 "个人教义：当前所奉" and 纪事 "个人教义沿革"). Other characters' rows keep it via
    # `_profile_facts`, since without a 礼仪志 it is their only source.
    # Culture history: the game writes no memory for a conversion, so it is derived by
    # diffing `culture` across save snapshots.
    chl = f.culture_history_lines(pid)
    if chl:
        p["culture_history"] = "；".join(chl)
    hhl = f.house_history_lines(pid)
    if hhl:
        p["house_history"] = hhl
    # chain of biographees (previous / next biographee and the succession date)
    scl = f.succession_lines()
    if scl:
        p["succession"] = scl
    mot = f.motto()
    if mot:
        p["motto"] = mot
    cpl, _cpch = f.court_positions_lines()
    if cpl:
        # the subject is the office holder ("仲宣任丑角…"), groups separated by "；"
        p["court_positions"] = "；".join(cpl)
    # Court offices granted to the protagonist (太师 etc.): only offices he himself received
    # (employee = protagonist), kept apart from the retainer roster, and shared with the realm
    # facts side (朝局风云录 reads the same source).
    col, coch = f.court_office_lines()
    if col:
        p["court_office"] = "；".join(col)
    if coch:
        p["court_office_changes"] = "；".join(coch)
    # When as_of predates the last snapshot, details such as domain, vassals and camp laws are
    # late-snapshot data and must not enter the prompt; only the title dimension is date-aware
    # (per-period detail would need yearly snapshots, too costly for now).
    skip_detail = bool(f.as_of) and cl.date_key(f.as_of) < cl.date_key(
        cache.get("last_date") or f.as_of or "9999.9.9")
    ld = rec.get("landed") or {}
    gov = ld.get("government")
    # the landless / landed branch is decided from the primary title as of as_of
    # (the cached landed data is the last snapshot)
    ptier, ptid = f._primary_title_at(pid)
    # `ld` is last-snapshot cache data, so a government read from it is wrong for the early
    # years of a decade biography: read the government as of as_of (per-snapshot history) and
    # fall back to the last snapshot only when nothing is found.
    gov_asof = f._character_government(pid, f.as_of) or gov or ""
    # raw government key, used by the prompt side to vary the wording
    # (天朝制 / 行政制 = office rotation)
    p["government_key"] = gov_asof
    # Only a true landless-adventurer camp (x_d_laamp_ / mercenary company / holy order) takes
    # the camp branch; family estates (x_nf_) and nomadic yurts (x_c_nomad_) are a seat of
    # power, not a camp.
    if f.title_kind(ptid) == "camp" or gov_asof == "landless_adventurer_government":
        # ---- landless adventurer: camp ----
        p["landless"] = True
        camp_tid = ptid if f.title_kind(ptid) == "camp" \
            else (ld.get("domain") or [None])[0]
        if camp_tid is not None:
            p["camp_name"] = f._title_name_at(camp_tid, f.as_of) or "冒险者营地"
        else:
            p["camp_name"] = "冒险者营地"
        # camp details are rendered only when the cached landed data really is a
        # camp (i.e. no as_of time travel)
        if gov_asof == "landless_adventurer_government" and not skip_detail:
            laws = ld.get("laws") or []
            if laws:
                names = []
                for law in laws:
                    v = L.loc(f.table, law) or law
                    if v and v != law:
                        names.append(v)
                if names:
                    p["camp_laws"] = "、".join(names)
            if ld.get("strength") is not None:
                p["camp_strength"] = str(ld.get("strength"))
            prov = f.character_location_province(pid)
            county_tid = f.county_at_province(prov)
            if county_tid is None and camp_tid:
                # fallback: the camp title's capital counts as the county
                t = (f.melt.get("landed_titles") or {}).get("landed_titles") or {}
                cap = (t.get(str(camp_tid)) or {}).get("capital")
                county_tid = cap
            chain = f.liege_chain(county_tid) if county_tid else []
            if county_tid and chain:
                cname = f.title(county_tid)
                p["camp_county"] = cname
                holder = chain[0][1]
                if holder is not None:
                    p["camp_county_holder"] = f.name_or(holder)
                mids = chain[1:-1]
                if mids:
                    parts = []
                    for tid, hid in mids:
                        tn = f.title(tid)
                        hn = f.name_or(hid, "") if hid is not None else ""
                        # title joined straight to its holder ("幽蓟路李黯"), with no
                        # parenthetical appositive
                        parts.append(f"{tn}{hn}" if hn else tn)
                    p["camp_liege_chain"] = "、".join(parts)
                top_tid, top_holder = chain[-1]
                p["camp_top_liege"] = f"{f.title(top_tid)}{f.name_or(top_holder)}" \
                    if top_holder is not None else f.title(top_tid)
    else:
        # ---- landed ruler / family estate ----
        # Family estates (x_nf_ / c_nf_) are an estate identity kept apart from the adventurer camp and
        # read at as_of. With a landed primary title (c_ and above) the estate sentence is omitted: the
        # main line is carried by the government / tenure rows, and an undated estate sentence would be
        # read as the birthplace and standing of a whole life.
        if ptier is None:
            for _etid, _ivs in (f._hold_intervals(pid) or {}).items():
                if _ivs and _ivs[-1][1] is None and f._is_estate_title(_etid):
                    p["estate_name"] = f._title_name_at(_etid, f.as_of) or "家族庄园"
                    p["estate_word"] = f.estate_kind_word(_etid, pid)
                    p["estate_holder"] = f._estate_holder_word(pid)
                    # seat county of the estate (the estate and an office seat are two
                    # different places)
                    _ep = f.estate_place_name(pid)
                    if _ep:
                        p["estate_place"] = _ep
                    # founding date, written only when later than the birth: an estate
                    # founded after birth is not the birthplace
                    _eg = _ivs[-1][0]
                    _bd = rec.get("birth")
                    if _eg and _bd and cl.date_key(_eg) > cl.date_key(_bd):
                        p["estate_since"] = f.date(_eg)
                    break
        if ld and not skip_detail:
            p["ruler_since"] = f.date(ld.get("became_ruler_date"))
            # The capital barony is implied by its county, so the folded list is what produces
            # "直辖N地": domain = the highest-tier titles (all of that tier) + the counties actually
            # held, secondary duchies and kingdoms not listed alongside (`domain_titles`).
            keep, _folded = f.domain_titles(ld.get("domain") or [])
            dom = []
            for tid in keep:
                t = f.title(tid)
                if t:
                    dom.append(t)
            p["domain"] = "、".join(dom)
            p["domain_count"] = len(keep)
            cap = f.title(ld.get("realm_capital"))
            if cap:
                p["capital"] = cap
            # Zero values are not emitted: "封臣0人" would draw the model's attention
            # to the non-event of having no vassals; with no vassals the clause is
            # simply absent.
            _vcount = int(ld.get("vassal_count") or 0)
            if _vcount:
                p["vassal_count"] = _vcount
            # council seats use the dynamic office name + the councillor's name; no
            # clause is emitted when it cannot be parsed
            cl_line = f.council_line()
            if cl_line:
                p["council"] = cl_line
        # Nomadic herd / camp provisions: current value only, read from the melt at as_of rather than
        # the last snapshot (which would leak later values). Herd only in a yurt, provisions only in a
        # landless camp, neither in an estate or landed realm; zero values are omitted.
        if not p.get("landless"):
            _pc = f._chars.get(str(pid)) or {}
            _pld = _pc.get("landed_data") or {}
            _dom = cl.player_domicile(f.melt, _pld.get("domain") or [], pid)
            if _dom is None:
                _dom = ld if ld.get("herd") is not None else None
            _dtype = (_dom or {}).get("domicile_type") or ld.get("domicile_type") or ""
            _is_nomad = _dtype == "yurt" or any(
                f._is_nomad_camp(_t) for _t in (ld.get("domain") or []))
            _is_camp = (not _is_nomad) and (
                _dtype == "camp" or gov_asof == "landless_adventurer_government")

            # the herd (nomadic currency) value is not emitted; provisions (camp
            # supply) become a game band word
            if _dom and _is_camp and _dom.get("provisions") is not None:
                w = provisions_band(_dom.get("provisions"))
                if w:
                    p["provisions_word"] = w
    # current status, only while alive and not abdicated; an abdicated ruler gets the
    # "位已终" closing sentence instead and no current status.
    if not cache.get("player_death") and not cache.get("reign_end"):
        def num(v, nd=1):
            try:
                return f"{float(v):.{nd}f}".rstrip("0").rstrip(".")
            except Exception:
                return None
        bits = []
        age = None
        try:
            by = int((rec.get("birth") or "0.0.0").split(".")[0])
            # a decade biography computes the age at as_of, not at the last snapshot,
            # so a later age cannot leak into an earlier year
            cy_src = (f.as_of or melt.get("date") or "0.0.0")
            cy = int(str(cy_src).split(".")[0])
            age = cy - by
        except Exception:
            pass
        if age is not None:
            bits.append(f"年{age}岁")
        # health / stress are given only as game band words (plain modern Chinese),
        # never as raw numbers such as 5.5 or 69
        hs = health_state_zh(ad.get("health"))
        if hs:
            bits.append(hs)
        ss = stress_state_zh(ad.get("stress"))
        if ss:
            bits.append(ss)
        # Money and faith values are always banded: treasury gold, monthly income and the herd are
        # omitted entirely, while piety / prestige / influence / merit become game band words (defines
        # LEVELS_* plus the localization key <kind>_level_N, e.g. 戴罪之人 / 崭露头角 / 七品).
        for kind, label in (("piety", "虔诚"), ("prestige", "威望"),
                            ("influence", "影响力"), ("merit", "功勋")):
            v = (ad.get(kind) or {}).get("currency")
            w = L.level_word(f.table, f._bands, kind, v)
            if w:
                # when the band word already contains the label, emit the band word
                # alone: piety_level_2 is "虔诚信者", and prefixing the label would
                # give "虔诚虔诚信者"
                bits.append(w if label in w else f"{label}{w}")
        if bits:
            p["status"] = "，".join(bits) + "。"
    # death (final biography); an as_of earlier than the death date counts as alive, so a decade
    # biography does not leak "死于…". Abdication (`reign_end`) takes precedence: it ends this chapter,
    # and a later death only enters the cache for later chapters' family information.
    re_end = cache.get("reign_end")
    if re_end and f.as_of \
            and cl.date_key(f.as_of) < cl.date_key(re_end.get("date") or "9999.9.9"):
        re_end = None                      # decade chapter ending earlier: abdication untold
    pd = cache.get("player_death")
    if pd and re_end and cl.date_key(pd.get("date") or "0.0.0") \
            > cl.date_key(re_end.get("date") or "9999.9.9"):
        pd = None                          # a death after the abdication stays out of this chapter
    if pd and f.as_of and cl.date_key(f.as_of) < cl.date_key(pd.get("date") or "9999.9.9"):
        pd = None
    if re_end:
        p["reign_end"] = f"{f.reign_end_clause(pid, re_end)}。"
    elif pd:
        p["death"] = (
            f"死于{f.date(pd.get('date'))}，"
            f"{f.death_clause(pid, date=pd.get('date'), reason=pd.get('reason'), killer=pd.get('killer'))}。"
        )
        # Death place (a barony), the same output `victim_place` uses in 刺客列传; omitted when
        # unavailable. It must share the gate of `p["death"]`: the protagonist's own death record is
        # empty, and `victim_place`'s third source `last_location` is not bounded by as_of, so an
        # unconditional computation would leak a future death place.
        _dp = f.death_place(pid)
        if _dp:
            p["death_place"] = _dp
        # A traveller still on the road in the snapshot before death: departure date + "自X启程" +
        # destination and purpose + (途中 / 返程途中) merge into the death sentence, with no separate row,
        # station count or estimated arrival. With no departure date or destination the clause returns ''
        # and the sentence is unchanged (`Facts.transit_facts`).
        _tr = f.transit_facts(pid)
        if _tr:
            p["transit"] = _tr
            _tc = f.transit_death_clause(_tr)
            if _tc:
                p["death"] = _tc + p["death"]
    # Birth and death places (baronies): the death place shares the gate of
    # `p["death"]`, and the birth place comes from the person's first-seen snapshot
    # (see the criteria in `birth_place`); each is omitted when unavailable.
    _bp = f.birth_place(pid)
    if _bp:
        p["birth_place"] = _bp
    # family (truncated at as_of: members born later are not listed)
    fam = rec.get("family") or {}
    # Merge in the spouse latch first: the protagonist's own family_data is cleared in the death
    # snapshot while spouses' and concubines' reverse pointers stay in every snapshot; without it the
    # facts would go blank and the model would invent spouses.
    fam = f.merge_spouse_latch(fam, f.as_of)
    rec["family"] = fam
    # cross-annotation of wives/concubines against the father's marriage history: the
    # "first the father's wife/concubine, then the son's" relation
    father_id = (fam.get("father") or [None])[0]
    fd_fam = {}
    if father_id is not None:
        fd_fam = ((cache.get("characters") or {}).get(str(father_id)) or {}).get("family") or {}

    def _annotate(ids, lineality=False):
        out = []
        noted = False
        for sid in ids:
            nm = f.kin_label(sid, f.as_of)
            if not nm:
                continue
            note = ""
            # A wife or concubine who is also a blood relative (niece / nephew / cousin ...)
            # gets the blood kinship term first: given only the marital position the model
            # would invent the relation.
            _bk = f.blood_kin_word_for(sid, pid)
            if _bk:
                note = f"，本为其{_bk}"
            if father_id is not None and sid != father_id:
                for k, label in (("primary_spouse", "妻"), ("spouse", "妻"),
                                 ("concubine", "妾"), ("former_spouses", "前妻"),
                                 ("former_concubines", "前妾")):
                    if sid in (fd_fam.get(k) or []):
                        # no parentheses: the note is a clause of the same sentence,
                        # hence the "；" separator
                        note += (f"，原为父{f.kin_label(father_id, f.as_of)}"
                                 f"之{label}")
                        break
            # matrilineal marriage: the spouse row adds the lineality and the
            # children's affiliation
            if lineality:
                note += f.marriage_lineality_note(pid, sid, before=f.as_of)
            if note:
                noted = True
            out.append(nm + note)
        # use "；" as the separator when any entry carries a note, so it cannot be
        # confused with the "，" inside the note
        return ("；" if noted else "、").join(out)

    spouse_ids = list(dict.fromkeys(
        _asof_ids(f, (fam.get("primary_spouse") or []) + (fam.get("spouse") or []))))
    # spouses married after this chapter's cut-off date are not listed (the last
    # snapshot's marital state would leak)
    spouse_ids = f._spouses_asof(pid, spouse_ids)
    # Then cut everyone who was no longer a wife or concubine within this chapter's window (a decade
    # chapter's window runs from the previous decade's cut-off date to as_of; a final or living
    # biography starts at the campaign start, so nothing is ever cut).
    spouse_ids = f.spouses_in_window(spouse_ids)
    p["spouses"] = _annotate(spouse_ids, lineality=True)
    # One person enters only one marital category: the save's `family_data` lists the current spouse
    # again in `former_spouses` / `former_concubines`, so all four categories formed independently
    # would print "妻室X、前妻X". Priority = print order: wives > former wives > concubines > former.
    _sp_set = set(spouse_ids)
    _former_sp = [x for x in _asof_ids(f, fam.get("former_spouses") or [])
                  if x not in _sp_set]
    _former_sp = f.spouses_in_window(_former_sp)          # same window rule
    p["former_spouses"] = _annotate(_former_sp)
    # concubines (forward `concubine` + reverse `concubinist`, merged and deduped in
    # the cache)
    _seen_mar = _sp_set | set(_former_sp)
    _conc = [x for x in _asof_ids(f, fam.get("concubine") or [])
             if x not in _seen_mar]
    _conc = f.spouses_in_window(_conc)                    # same window rule
    p["concubines"] = _annotate(_conc)
    _seen_mar |= set(_conc)
    _fconc = [x for x in _asof_ids(f, fam.get("former_concubines") or [])
              if x not in _seen_mar]
    _fconc = f.spouses_in_window(_fconc)                  # same window rule
    p["former_concubines"] = _annotate(_fconc)
    child_ids = [c for c in _asof_ids(f, fam.get("child") or []) if f.name(c)]
    # The household list holds every child whose legal father is the protagonist (illegitimate ones
    # included); children of another legal father stay out of the 本纪 list (家室列传 covers them as
    # "妻子的子女"). With no genealogy data the original list is kept, so "no data" != "no children".
    _legal, _has_fam = f.legal_children_ex(pid)
    if _has_fam:
        child_ids = [c for c in child_ids if c in _legal]
    _wife_other = f.wife_other_children(pid)
    _wo_line = f.wife_other_children_line(pid, _wife_other) if _wife_other else ""
    if _wo_line:
        p["wife_other_children"] = _wo_line
    p["children"] = "、".join(f.kin_label(c) for c in child_ids)
    # children split by sex ("子A、B，女C、D"), the same rule as `_character_profiles`
    p["children_sons"] = "、".join(
        f.kin_label(c) for c in child_ids if not f._is_female(c))
    p["children_daughters"] = "、".join(
        f.kin_label(c) for c in child_ids if f._is_female(c))
    # the subject's sex, which selects the spouse label "妻室/夫婿" (see
    # `biography._profile_lines`)
    p["female"] = f._is_female(pid)
    p["father"] = "、".join(
        f.kin_label(x) for x in (fam.get("father") or []) if f.name(x))
    p["mother"] = "、".join(
        f.kin_label(x) for x in (fam.get("mother") or []) if f.name(x))
    p["siblings"] = "、".join(
        f.kin_label(x) for x in (fam.get("siblings") or []) if f.name(x))
    # ids of the relatives already named in this profile's kinship rows: the section stage
    # (KinScope.seed) reads this to know a kinship is stated and stops repeating the modifier.
    p["kin_ids"] = sorted({int(x) for x in (
        list(spouse_ids) + list(_former_sp) + list(_conc) + list(_fconc)
        + list(child_ids) + list(_wife_other or ())
        + list(fam.get("father") or []) + list(fam.get("mother") or [])
        + list(fam.get("siblings") or [])) if isinstance(x, int)})
    # custom character (no genealogy): the generic kinship text is overridden
    if f.is_custom_start(pid):
        p["custom_start"] = True
    # Real father (bastard scenario), decided by comparing ids with the legal father: a publicly
    # acknowledged bastard has `real_father == father` (the game's
    # `on_action/child_birth_on_actions.txt:781-817` sets `set_father = scope:real_father` in the same
    # `is_bastard = yes` branch), so only a true cuckoo case emits the row.
    _father_ids = {int(x) for x in (fam.get("father") or [])
                   if isinstance(x, int)}
    rf = (fam.get("real_father") or [None])[0]
    if rf is not None and int(rf) not in _father_ids:
        rfname = f.kin_label(rf)
        if rfname:
            p["real_father"] = rfname
            if isinstance(rf, int):
                p["kin_ids"] = sorted(set(p["kin_ids"]) | {rf})
    ht = f.held_titles(pid)
    if ht:
        p["titles_held"] = "；".join(ht)
    # government change sentence (a switch to administrative government etc.),
    # emitted only when something actually changed
    gc = f.government_changes(pid)
    if gc:
        p["government_change"] = gc
    # clan branch sentence (when the branch name differs from the clan name)
    cl_ = f.clan_line(pid)
    if cl_:
        p["clan_line"] = cl_
    # co-ruler note, e.g. "（共治巴西琉斯）"
    cor = f.co_ruler_note(pid, date=f.as_of)
    if cor:
        p["co_ruler"] = cor
    dc = f.dynastic_cycle_line(f.as_of)
    if dc:
        p["dynastic_cycle"] = dc
    # dramatic facts (emperor for a day etc.), placed at the end of the profile for
    # emphasis
    df = f.dramatic_facts(pid)
    if df:
        p["dramatic_facts"] = df
    return p


def _profile_needed_ids(f):
    """Ids of the characters whose profile is built -- only these enter the prompt: the related set
    (protagonist / clan / parents, wives, children, in-laws) ∪ friends and foes ∪ court office
    holders. Computing only what is visible (cf. Paradox dev diary #187) cuts 41k profiles to a few
    hundred and greatly speeds up build_facts."""
    out = _related_ids(f)
    pid = f.cache.get("player_id")
    if pid is None:
        return out
    REL = {"became_friends", "became_soulmates", "became_blood_brother",
           "became_rivals", "became_grudge", "became_nemesis"}
    for cid, rec in (f.cache.get("characters") or {}).items():
        for m in rec.get("memories") or []:
            if m.get("type") in REL:
                parts = m.get("participants") or {}
                if any(isinstance(v, int) and v == pid for v in parts.values()):
                    out.setdefault(int(cid), 2)
                    break
    prec = (f.cache.get("characters") or {}).get(str(pid)) or {}
    for m in prec.get("memories") or []:
        if m.get("type") in REL:
            for v in (m.get("participants") or {}).values():
                if isinstance(v, int):
                    out.setdefault(v, 2)
    for h in f.cache.get("court_positions") or []:
        for p in h.get("positions") or []:
            if isinstance(p.get("employee"), int):
                out.setdefault(p["employee"], 2)
    # Lovers and soulmates of the protagonist's spouses: source material for the
    # wives' affairs and for the lovers' own profiles.
    prec = (f.cache.get("characters") or {}).get(str(pid)) or {}
    pfam = prec.get("family") or {}
    for sid in dict.fromkeys(
            [x for x in (pfam.get("primary_spouse") or [])
             + (pfam.get("spouse") or [])
             + (pfam.get("former_spouses") or [])
             + (pfam.get("concubine") or [])
             + (pfam.get("former_concubines") or []) if isinstance(x, int)]):
        srec = (f.cache.get("characters") or {}).get(str(sid)) or {}
        for m in srec.get("memories") or []:
            slot = _AFFAIR_SLOTS.get(m.get("type"))
            if not slot:
                continue
            other = (m.get("participants") or {}).get(slot)
            if isinstance(other, int) and other not in (pid, sid):
                out.setdefault(other, 2)
    # The protagonist's murder targets and victims (successful_murder memories ∪ cached deaths with
    # killer == protagonist): their culture and faith stay readable in the save (dead_unprunable keeps
    # the object fields), and they used to reach 刺客列传 only, which needs more than 5 kills.
    prec = (f.cache.get("characters") or {}).get(str(pid)) or {}
    for m in prec.get("memories") or []:
        if m.get("type") == "successful_murder":
            v = (m.get("participants") or {}).get("victim")
            if isinstance(v, int) and v != pid:
                out.setdefault(v, 2)
    for _cid, _rec in (f.cache.get("characters") or {}).items():
        if int(_cid) == pid:
            continue
        if (_rec.get("death") or {}).get("killer") == pid:
            out.setdefault(int(_cid), 2)
    return out


def _character_profiles(f):
    """Per cached character: clean profile + memories + death + kin + tenures. Built only for
    the characters that enter the prompt (see `_profile_needed_ids`), computed on demand."""
    out = {}
    for cid in _profile_needed_ids(f):
        rec = (f.cache.get("characters") or {}).get(str(cid)) or {}
        if not rec:
            continue
        name = f.name_with_regnal(cid)  # profile name carries the regnal number, as in timeline text
        prof = {
            "name": name,
            "name_zh": rec.get("name_zh") or "",
            # clan name (the surname under Eastern name order) + house/branch (flavour)
            "house": _dynasty_display(rec.get("dynasty_name"),
                                      rec.get("house_name")),
            "house_branch": _house_branch(rec.get("dynasty_name"),
                                          rec.get("house_name")),
            # the single house wording used throughout, from culture and name order
            "house_label": house_label(rec.get("dynasty_name"),
                                       rec.get("house_name"),
                                       f.name_order(cid),
                                       (f._culture_entry(cid, f.as_of) or {})
                                       .get("culture_template")),
            "birth": f.date(rec.get("birth")),
            "culture": f.culture(cid),
            "faith": f.faith(cid),
            # split into sentences by category, the same rule as the protagonist's profile
            "traits": f.traits_sentence(cid, public=True),
        }
        # Court standing under the protagonist (knight / courtier) + the date of entering
        # court. The player's own kin skip the sentence: kin rows need no "廷臣" tag.
        _pid0 = f.cache.get("player_id")
        _is_kin = False
        if _pid0 is not None and int(cid) != int(_pid0):
            _prec0 = (f.cache.get("characters") or {}).get(str(_pid0)) or {}
            _pfam0 = _prec0.get("family") or {}
            _kin = set()
            for _k in ("primary_spouse", "spouse", "former_spouses", "child",
                       "concubine", "former_concubines", "father", "mother",
                       "siblings", "ever_spouses"):
                _kin.update(x for x in (_pfam0.get(_k) or []) if isinstance(x, int))
            _is_kin = int(cid) in _kin
            if not _is_kin:
                _csp = f.court_service_phrase(cid)
                if _csp:
                    prof["court_service"] = _csp
        langs = f.languages(cid)
        if langs:
            prof["languages"] = "、".join(langs)
        # The language fact sentence (native tongue / also spoken) goes to the protagonist alone:
        # describing everyone's native tongue is excessive and intelligibility in a family is common
        # knowledge; others reach the prompt only via `language_relation` (the "相通 / 须借通译" verdict).
        _pid = f.cache.get("player_id")
        if _pid is not None and int(cid) != int(_pid):
            _ln = f.language_relation_line(_pid, cid)
            if _ln:
                prof["language_relation"] = _ln
        # office name (primary title + office word) / prince title (children of a kingdom, empire or
        # hegemony who hold no title)
        off = f.official_title(cid)
        if off:
            prof["office"] = off
        pt = f.prince_title(cid)
        if pt:
            prof["prince"] = pt
        # label unified: the profile label sentence is assembled here once
        prof["label"] = f.person_label(cid, date=f.as_of, style="brief") or name
        # clan branch sentence (spelled out when the branch name differs, to mark the
        # same clan)
        _cl = f.clan_line(cid)
        if _cl:
            prof["clan_line"] = _cl
        _cor = f.co_ruler_note(cid, date=f.as_of)
        if _cor:
            prof["co_ruler"] = _cor
        # patronymic byname (patronymic cultures, e.g. Norse "Xson" / "Xdottir" forms)
        ptn = f.patronym(cid)
        if ptn:
            prof["patronym"] = ptn
        thl = f.trait_history_lines(cid)
        if thl:
            prof["trait_history"] = "；".join(thl)
        fhl = f.faith_history_lines(cid)
        if fhl:
            prof["faith_history"] = "；".join(fhl)
        # A ruler who took a regnal (papal) name gets his birth name on his own row:
        # the label runs on the regnal name and the birth name is given once here.
        _rbn = f.regnal_birth_name(cid, f.as_of)
        if _rbn:
            prof["birth_name"] = _rbn
        # Personal tenets go into every profile, not only the biographee's; only landed
        # rulers carry `playable_data.tenets`, so only they get this row.
        ptl = f.personal_tenet_lines(cid, f.as_of)
        if ptl:
            prof["personal_tenets"] = f._join_sentences(ptl)
        chl = f.culture_history_lines(cid)
        if chl:
            prof["culture_history"] = "；".join(chl)
        # this character's office in the player's court or camp (latest snapshot,
        # scanning backwards for the last year); the display name follows the player's
        # court government variant (私人医生 -> 医学博士)
        for h in reversed(f.cache.get("court_positions") or []):
            for p in h.get("positions") or []:
                if p.get("employee") == cid:
                    zh = f.court_position_word(p.get("type")) or ""
                    if zh and zh != p.get("type"):
                        prof["court_position"] = zh
                    break
            if prof.get("court_position"):
                break
        fam = rec.get("family") or {}
        spouse_ids = list(dict.fromkeys(
            _asof_ids(f, (fam.get("primary_spouse") or []) + (fam.get("spouse") or []))))
        # spouses married after this chapter's cut-off date are not listed (same rule
        # as `_protagonist_facts`)
        spouse_ids = f._spouses_asof(cid, spouse_ids)
        # Kin are always "title + name" (`kin_label`), never the bare name; a
        # matrilineal marriage adds the lineality and the children's affiliation per
        # spouse.
        prof["spouses"] = "、".join(
            f.kin_label(s) + (f.marriage_lineality_note(cid, s, before=f.as_of) or "")
            for s in spouse_ids if f.name(s))
        prof["concubines"] = "、".join(
            f.kin_label(s) for s in _asof_ids(f, fam.get("concubine") or []) if f.name(s))
        # Consort / blood-kin row: the program supplies whom she was taken by when her own profile cannot
        # show it (otherwise the protagonist's profile lists her as a concubine while her own says
        # "终生未嫁"). It goes into the label sentence (`biography._profile_lines`), the first line the
        # model reads, since names sharing a generational prefix are easily misread as siblings.
        _co = f.consort_of_line(cid)
        if _co:
            prof["consort_rel"] = _co
        _conc_ids = list(_asof_ids(f, fam.get("concubine") or []))
        child_ids = [c for c in _asof_ids(f, fam.get("child") or []) if f.name(c)]
        prof["children"] = "、".join(f.kin_label(c) for c in child_ids)
        # children split by sex ("子A、B，女C、D"); without it the list is an ungendered
        # mix and the model can only guess from the names
        prof["children_sons"] = "、".join(
            f.kin_label(c) for c in child_ids if not f._is_female(c))
        prof["children_daughters"] = "、".join(
            f.kin_label(c) for c in child_ids if f._is_female(c))
        # the subject's sex, which selects the spouse label (a female character's
        # husband is no longer labelled "妻室")
        prof["female"] = f._is_female(cid)
        # A protagonist's child gets no repeated kinship list: his "兄弟姊妹" is exactly the
        # protagonist's other children, listed in full already, and repeating it per household profile
        # prints it eight times. The "父" row is also dropped; "母" is kept to identify the birth mother.
        _pid = f.cache.get("player_id")
        _prec = (f.cache.get("characters") or {}).get(str(_pid)) or {}
        _pchildren = {int(x) for x in ((_prec.get("family") or {}).get("child") or [])}
        _is_pchild = int(cid) in _pchildren
        _fathers = [x for x in (fam.get("father") or []) if f.name(x)]
        _fids = {int(x) for x in (fam.get("father") or []) if isinstance(x, int)}
        if not (_is_pchild and _pid in _fathers):
            prof["father"] = "、".join(f.kin_label(x) for x in _fathers)
        prof["mother"] = "、".join(
            f.kin_label(x) for x in (fam.get("mother") or []) if f.name(x))
        # Only the birth mother's marital status at the child's birth is recorded (not illegitimacy):
        # with another spouse then (not the child's father) one sentence gives her marital identity,
        # taking the highest-ranked spouse; `biography._profile_lines` appends it to the "母" row only in
        # the inner-household chapter. "Still married at the birth", from cache fields and memories: with
        # a `married` memory the wedding date is <= the birth date, without one the spouse was still alive.
        _mom = (fam.get("mother") or [None])[0]
        _birth = str(rec.get("birth") or "")
        if _is_pchild and isinstance(_mom, int) and _birth:
            _chars = f.cache.get("characters") or {}
            _mrec = _chars.get(str(_mom)) or {}
            _mfam = _mrec.get("family") or {}
            _cand = []
            for _s in dict.fromkeys(
                    list(_mfam.get("spouse") or [])
                    + list(_mfam.get("former_spouses") or [])
                    + list(_mfam.get("primary_spouse") or [])):
                if not isinstance(_s, int) or _s in _fids or not f.name(_s):
                    continue
                _wd = f.wedding_date(_mom, _s)
                if _wd and cl.date_key(_wd) > cl.date_key(_birth):
                    continue
                _sd = ((_chars.get(str(_s)) or {}).get("death") or {}).get("date")
                if _sd and cl.date_key(_sd) < cl.date_key(_birth):
                    continue
                _cand.append(_s)
            if _cand:
                def _rank_(sid):
                    _t, _tid = f._primary_title_at(sid, as_of=f.as_of)
                    return f._eff_rank(_tid) if _tid is not None else -1
                _best = max(_cand, key=_rank_)
                _rel = f._consort_word(_best, _mom)
                _bl = f.kin_label(_best)
                if _rel and _bl:
                    # no parentheses: the facts use no appositive "noun（noun）" form (a
                    # project rule). `biography._profile_lines` emits it as a sentence of
                    # its own.
                    prof["mother_note"] = f"生母为{_bl}之{_rel}。"
        if not _is_pchild:
            prof["siblings"] = "、".join(
                f.kin_label(x) for x in (fam.get("siblings") or []) if f.name(x))
        if f.is_custom_start(cid):
            prof["custom_start"] = True
        # same as `_protagonist_facts`: the real father is emitted only for a true
        # cuckoo case (`father != real_father`); a publicly acknowledged bastard has
        # `real_father == father` and gets no such row.
        rf = (fam.get("real_father") or [None])[0]
        if rf is not None and int(rf) not in _fids:
            rfname = f.kin_label(rf)
            if rfname:
                prof["real_father"] = rfname
        # ids of the relatives this profile's kinship rows already named (see the
        # same-named field in `_protagonist_facts`)
        prof["kin_ids"] = sorted({int(x) for x in (
            list(spouse_ids) + list(_conc_ids) + list(child_ids)
            + list(fam.get("father") or []) + list(fam.get("mother") or [])
            + list(fam.get("siblings") or [])
            + ([rf] if isinstance(rf, int) else [])) if isinstance(x, int)})
        ht = f.held_titles(cid)
        if ht:
            prof["titles_held"] = "；".join(ht)
        # Seat sentence for a protagonist's child: among the predecessors of his current title, the run
        # of those who died at the protagonist's hand ("those killed so that my child could take the
        # seat"), emitted with the child's profile only (household biography / secret records).
        if _is_pchild:
            _sn = f.seat_note(cid)
            if _sn:
                prof["seat_note"] = _sn
        mems = []
        # read the memories from the cache (the old code read `prof.get("memories")`, a key that never
        # existed, so every "传主行迹" said "（无行迹记录）")
        # pair up inheritance sentences first: memories consumed by a pair no longer become rows
        _ipairs = f.inherit_pairs(cid)
        _iconsumed = set()
        for _line, _ids, _dd in _ipairs.values():
            _iconsumed |= _ids
        for mem in rec.get("memories") or []:
            if id(mem) in _iconsumed:
                continue
            # Sexual memories (同房 / 私通 / forced or half-willing) stay out of a character's "行迹":
            # profiles are public data shared by every chapter, so sex appears only in the 【相关年表】
            # of the friend and foe biographies (via `facts["timeline"]`, see `_timeline`).
            if is_sex_memory(mem.get("type")):
                continue
            s = _mem_sentence(f, cid, mem)
            if not s:
                continue
            # truncated at as_of: a decade chapter lists only events up to that period;
            # the date is the factual date (title gains and losses use the title-history
            # event date)
            _md = f.mem_date(cid, mem)
            if f.as_of and _md and cl.date_key(_md) > cl.date_key(f.as_of):
                continue
            mems.append(f"{f.date(_md)}，{s}")
        for _line, _ids, _dd in _ipairs.values():
            mems.append(f"{f.date(_dd)}，{_line}")
        mems.sort()
        prof["events"] = mems
        # "传主行迹" uses the subject-omitted form (the block's subject is always the biographee). Strip
        # keys are the profile label plus a same-shaped key without the accolade prefix: an accolade
        # changes over time, so keying on the label alone lets a bare subject name reappear.
        _subj = prof.get("label") or name
        _alts = []
        _acc = f.accolade_word_at(cid, f.as_of)
        if _acc and _acc in _subj:
            _alts.append(_subj.replace(_acc, "", 1))
        # Fall back to the person's own name: when the sentence opens with the office
        # title of the day, the name itself is the only common anchor.
        _own = [name]
        _raw = f.name(cid)
        if _raw and _raw != name:
            _own.append(_raw)
        _subs, _aliases = [], []
        for x in mems:
            y = _strip_subject_prefix(x, _subj, _alts, own_names=_own)
            _subs.append(y)
            # After subject omission the sentence body changes, so the three registries
            # keyed by sentence body (name_index / line_owner / line_stated) need an
            # alias copy, or the kinship modifier cannot be inserted into this row.
            if y != x:
                _m2 = _SUBJ_DATE_RE.match(x)
                _hd = _m2.group(0) if _m2 else ""
                _ob, _nb = x[len(_hd):], y[len(_hd):]
                if _ob and _nb != _ob:
                    _aliases.append((_ob, _nb))
        prof["events_subjectless"] = _subs
        for _ob, _nb in _aliases:
            f.alias_line(_ob, _nb)
        # The death sentence is truncated at as_of: a decade biography does not write a
        # death after the decade's end (the timeline already truncated; only the
        # profiles leaked it)
        _dd = (rec.get("death") or {}).get("date")
        if not (f.as_of and _dd and cl.date_key(_dd) > cl.date_key(f.as_of)):
            ds = _death_sentence(f, cid)
            if ds:
                prof["death"] = ds
            # A death place is written for the protagonist's kin only: other people's
            # death places are already carried by `victim_place` in 刺客列传, so the
            # profile rows need not repeat them.
            if _is_kin:
                _dp = f.death_place(cid)
                if _dp:
                    prof["death_place"] = _dp
        # the birth place is also written for kin only, taken from the person's
        # first-seen snapshot (see `birth_place`)
        if _is_kin:
            _bp = f.birth_place(cid)
            if _bp:
                prof["birth_place"] = _bp
        # a victim's profile carries the publicity flag for naming the killer (used by
        # the section stage and for snapshot cross-checking)
        prof["killer_public"] = f.killer_is_public(cid)
        out[str(cid)] = prof
    return out


def _campaign_start(f):
    """Campaign start (opening date): the minimum first snapshot across this campaign's biographee
    caches. This cache alone would clamp the lower bound of 朝局风云录 to "its first snapshot - 30
    years" and drop whole dynasty segments. None without sources; the caller falls back."""
    best = None
    for src in list((f.campaign or {}).values()) + [f.cache]:
        srcs = (src or {}).get("sources") or []
        if not srcs:
            continue
        d = str(srcs[0])
        try:
            if best is None or cl.date_key(d) < cl.date_key(best):
                best = d
        except Exception:
            continue
    return best


# Accession reason for each person in 《XX历代记》, read from the `type` of every event in the save's
# `landed_titles.<tid>.history` -- the game's own succession method (of the 20 values that occur, all
# except `destroyed` are "acquire" events). Wording from the game localization: succession_laws
# "任命继承制" and the ascended_throne reasons in memories_l_simp_chinese.yml:630-731. A bare holder
# with no `type` means regular inheritance (32234 entries in total).
_SUCC_WORD = {
    "appointment_succession": "受任命继位",
    "appointment": "受任命",
    "abdication": "受禅继位",
    "faction_demand": "被派系拥立",
    "election": "被选举继位",
    "granted": "受封头衔",
    "conquest": "征服夺取",
    "conquest_claim": "凭宣称夺取",
    "conquest_holy_war": "借圣战夺取",
    "conquest_populist": "借民粹叛乱夺取",
    "usurped": "篡夺继位",
    "migration": "率部迁徙入主",
    "stepped_down": "因前任下台而继位",
    "revoked": "收回头衔",
    "leased_out": "承租头衔",
    "lease_revoked": "收回租约",
    "independency": "自立",
    "returned": "收回",
    "swear_fealty": "宣誓效忠",
    # Five methods of taking a title that exist in the memory record
    # (`ascended_throne_memory.vars.reason`) but never reach the title history; the wording follows
    # `ascended_throne_memory_desc_intro_*` (memories_l_simp_chinese.yml:633-640).
    "inheritance": "继承",
    "purchased": "买得头衔",
    "seized_pastureland": "夺取牧场",
    "negotiated": "议得头衔",
    "created": "创建",
}
# these reasons read "从某某处…": the predecessor is the previous holder of the same
# title, so the inheritance chain stays readable
_SUCC_FROM_PREV = (None, "appointment_succession", "abdication")


def _title_hist_events(f, tid, end=None):
    """Event sequence of a title's history: [(date, holder|None, type|None)] up to `end`.

    `type` is the game's recorded succession method (absent = regular inheritance);
    `holder` None means the title had no holder that day (destroyed / awaiting a
    grant). Several events on one day (list form) are expanded in save order."""
    t = f._lt.get(str(tid)) or {}
    hist = t.get("history") or {}
    out = []
    if not isinstance(hist, dict):
        return out
    for d, ev in sorted(hist.items(), key=lambda x: cl.date_key(x[0])):
        if end and cl.date_key(d) > cl.date_key(end):
            break
        for e in (ev if isinstance(ev, list) else [ev]):
            if isinstance(e, dict):
                out.append((d, e.get("holder"), e.get("type")))
            else:
                out.append((d, e, None))
    return out


def _title_holder_seq(f, tid, end=None):
    """Holder sequence of a title's history: [(date, holder|None)] up to `end`.

    A `holder` of None means the title had no holder that day (destroyed / awaiting a
    grant), which lets the caller close the previous holder's term."""
    return [(d, h) for d, h, _ty in _title_hist_events(f, tid, end=end)]


def _realm_holder_seq(f, tid, end=None):
    """Holder sequence of a title in the `realm_history` snapshots of every biographee's cache:
    [(date, holder)]. Fallback for `_title_holder_seq`, since the melt's title history is often empty
    for landless titles (yurt / camp / newly created); observations are deduped by date."""
    seen = {}
    for src in list((f.campaign or {}).values()) + [f.cache]:
        for h in (src or {}).get("realm_history") or []:
            d = h.get("date")
            if not d:
                continue
            if end and cl.date_key(d) > cl.date_key(end):
                continue
            hs = h.get("holders") or {}
            if not isinstance(hs, dict):
                continue
            if str(tid) in hs and hs[str(tid)] is not None:
                seen[str(d)] = hs[str(tid)]
    out = []
    for d in sorted(seen, key=cl.date_key):
        if out and out[-1][1] == seen[d]:
            continue
        out.append((d, seen[d]))
    return out


def _estate_court_tid(f, pid):
    """The "court" title of an estate holder (with an estate, the top liege's title history is
    written): walk `de_facto_liege` of the estate title to the top (a Chinese family estate hangs
    under h_china), else take the top of the liege chain of the protagonist's location; None when
    neither works."""
    for t in (f._hold_intervals(pid) or {}):
        if not f._is_estate_title(t):
            continue
        l = (f._lt.get(str(t)) or {}).get("de_facto_liege")
        if not isinstance(l, int):
            continue
        top, seen = l, set()
        while top is not None and top not in seen:
            seen.add(top)
            nxt = (f._lt.get(str(top)) or {}).get("de_facto_liege")
            if not isinstance(nxt, int):
                break
            top = nxt
        if top is not None:
            return top
    try:
        prov = f.character_location_province(pid)
        ctid = f.county_at_province(prov)
        chain = f.liege_chain(ctid) if ctid is not None else []
        if chain:
            return chain[-1][0]
    except Exception:
        pass
    return None


# ---------------------------------------------------------------------------
# 《XX历代记》 expansion material
# ---------------------------------------------------------------------------
# Design rules: the material was too thin, not the prompt (the old draft sent only dynasty name +
# period + name + reason while the cache holds each person's birth and death, age, reign length, loss
# reason and the wars of the reign); one person per row; the program writes every sentence, the prompt
# only saying which passage to write and what goes in it (prompt-last rule).

_CHRONICLE_ANCESTOR_MAX = 12     # max generations traced back in the family chronicle
_CHRONICLE_WAR_MAX = 40          # max war rows per part (each section halves it again)
CHRONICLE_MID_MAX = 4            # max parts, the same form as JIASHI_GROUP_MAX
CHRONICLE_ROWS_PER_SECTION = 4   # one reign with more people -> further sections (_chrono_row_chunks)
# Wording for the reason a celestial empire (`h_`) creates the Mandate of Heaven: a
# preceding vacancy (contending warlords) -> 建立天命; displacing a sitting holder
# directly -> 取代. For other titles `created` still uses the three
# `created_verb_kind` bands (创建 / 重建 / 开创).
_CELLESTIAL_CREATE_VERB = {"vacant": "建立天命", "takeover": "取代"}
# Chinese words for the three `created` bands (the same table as
# style.TITLE_GAIN_CREATED_VERBS, repeated here to avoid a facts -> style dependency).
_TITLE_GAIN_CREATED_VERBS_ZH = {"first": "创建", "restored": "重建", "founded": "开创"}


def _war_word(f, reason):
    """War reason word, the localized name of the memory's `war_cb`; returns "" when it
    cannot be resolved, and the caller then omits that clause."""
    if not reason:
        return ""
    try:
        v = L.loc(f.table, str(reason)) or ""
    except Exception:
        v = ""
    return v if v and not re.search(r"[A-Za-z_]", v) else ""


def _chrono_rec(f, cid):
    """Character record: the most complete copy across this campaign's caches.

    Each cache is a real observation of the same game at a different snapshot, so the
    copy with the most memories wins. Read-only -- nothing is merged back."""
    key = str(cid)
    best, best_n = None, -1
    for src in ([f.cache] + list((f.campaign or {}).values())):
        rec = ((src or {}).get("characters") or {}).get(key)
        if not isinstance(rec, dict):
            continue
        n = len(rec.get("memories") or [])
        if n > best_n:
            best, best_n = rec, n
    return best or {}


def _chrono_year_age(birth, date):
    """Birth date and event date -> whole years of age (None when either is missing)."""
    if not birth or not date:
        return None
    try:
        by, bm, bd = (int(x) for x in str(birth).split(".")[:3])
        dy, dm, dd = (int(x) for x in str(date).split(".")[:3])
    except Exception:
        return None
    age = dy - by - (1 if (dm, dd) < (bm, bd) else 0)
    return age if age >= 0 else None


def _chrono_span(gain, loss):
    """Reign span text: "在位10年" or "在位未满一年"; "" when a date is missing."""
    if not gain or not loss:
        return ""
    try:
        gy = int(str(gain).split(".")[0])
        ly = int(str(loss).split(".")[0])
    except Exception:
        return ""
    n = ly - gy
    return "在位未满一年" if n <= 0 else "在位%d年" % n


def _chrono_seqs(f):
    """{(cid, tid): [(date, reason, type)]} -- accession / loss memory index, built in one scan of
    the cache. `ascended_throne_memory.vars.reason` is the game's own record of how the title was
    taken (every row carries a reason), `lost_title_memory` has the same shape, and `landed_title`
    is the title the memory refers to."""
    if getattr(f, "_chrono_idx", None) is not None:
        return f._chrono_idx
    idx = {}
    for _cid, _rec in (f.cache.get("characters") or {}).items():
        try:
            cid = int(_cid)
        except (TypeError, ValueError):
            continue
        for m in (_rec.get("memories") or []):
            ty = m.get("type")
            if ty not in ("ascended_throne_memory", "lost_title_memory"):
                continue
            reason, lt = "", None
            for v in (m.get("vars") or []):
                if v.get("flag") == "reason" and not reason:
                    reason = str(v.get("value") or "")
                elif v.get("flag") == "landed_title" and v.get("identity") is not None:
                    try:
                        lt = int(v.get("identity"))
                    except (TypeError, ValueError):
                        lt = None
            if lt is None:
                continue
            idx.setdefault((cid, lt), []).append(
                (str(m.get("creation_date") or ""), reason, ty))
    for k in idx:
        idx[k].sort(key=lambda x: cl.date_key(x[0]))
    f._chrono_idx = idx
    return idx


def _chrono_accession_reason(f, cid, tid, hist_type, date):
    """The reason for acceding on that day: the memory record first, the title history
    as a fallback.

    For a celestial empire's (`h_`) `created` the caller rewrites the wording (after a
    vacancy = 建立天命, displacing a sitting holder = 取代), so "" is returned here.
    Otherwise the memory record wins, its word list being fuller (it adds the five bands
    inheritance / election / purchased / seized_pastureland / negotiated), and the title
    history's `type` is the fallback when the memory record has no such title. When
    neither exists, "" is returned and the whole clause is omitted."""
    if hist_type == "created":
        return ""
    for (d, reason, _ty) in reversed(_chrono_seqs(f).get((int(cid), int(tid)), [])):
        if not reason:
            continue
        if not date or cl.date_key(d) <= cl.date_key(date):
            return _SUCC_WORD.get(reason, "")
    return _SUCC_WORD.get(hist_type or "", "")


def _chrono_rel_word(f, cid, other):
    """Kinship word between the two (子 / 女 / 父 / 母 / 兄 / 姊 / 配偶); "" when unrelated."""
    if cid is None or other is None:
        return ""
    fam = (_chrono_rec(f, cid).get("family") or {})
    if other in (fam.get("father") or []):
        return "父"
    if other in (fam.get("mother") or []):
        return "母"
    if other in ((fam.get("spouse") or []) + (fam.get("primary_spouse") or [])
                 + (fam.get("concubine") or []) + (fam.get("former_spouses") or [])):
        return "配偶"
    if other in (fam.get("siblings") or []):
        return "姊" if bool((_chrono_rec(f, other) or {}).get("female")) else "兄"
    ofam = (_chrono_rec(f, other).get("family") or {})
    if cid in (ofam.get("child") or []):
        return "女" if bool((_chrono_rec(f, cid) or {}).get("female")) else "子"
    return ""


def _chrono_nm(f, cid, date=None):
    """The event person's name: the name-in-office form first -- the display name built
    from the melt's `first_name` and the local name order -- then the cache profile's
    `name_full`.

    When a record is taken from another biographee's cache, `name_full` may be a
    patronymic or house name computed at that other snapshot, so the name-in-office form
    wins and the chronicle rows keep one vocabulary."""
    cc = f._chars.get(str(cid)) or {}
    if isinstance(cc, dict) and cc:
        try:
            nm = f.name(cid, date=date)
        except Exception:
            nm = ""
        if nm:
            return nm
    return _chrono_rec(f, cid).get("name_full") or f.name_or(cid, "") or ""


def _chrono_acc_text(f, cid, date, word, prev, from_prev=False,
                       prev_date=None):
    """Accession clause: "953年6月6日从甲处被派系拥立" / "874年7月7日自立建国".

    `from_prev` is set only for inheritance-type reasons (the same rule as
    `_SUCC_FROM_PREV`): "从X处建立天命" and "从X处被派系拥立" are not idiomatic."""
    d = f.date(date) if date else ""
    if not word:
        return d
    if from_prev and prev is not None and isinstance(prev, int):
        pn = _chrono_nm(f, prev, prev_date or date)
        if pn:
            rel = _chrono_rel_word(f, cid, prev)
            return "%s从%s%s处%s" % (d, rel, pn, word) if rel                 else "%s从%s处%s" % (d, pn, word)
    return d + word


def _chrono_loss_date(f, cid, tid, next_date):
    """The real loss date of this tenure. When two rulers follow one another, the next event date in
    `history` is only the succession date; it counts as a loss date only when the save records a
    `lost_title_memory` or the next event is `destroyed`, else None."""
    if not next_date:
        return None
    for (d, _reason, ty) in _chrono_seqs(f).get((int(cid), int(tid)), []):
        if ty != "lost_title_memory":
            continue
        if cl.date_key(d) <= cl.date_key(next_date):
            return d
    return None


def _chrono_reign_end(f, cid):
    """The ruler's abdication record: the `reign_end` written into the cache in which he was the
    biographee (via `pipeline._cross_check_reign_ends`, with the kind and the heir). Needed because
    some abdications appear only there, not in `lost_title_memory`, which would leave the ruler
    written as dying in office."""
    key = int(cid)
    if f.cache.get("player_id") == key:
        return f.cache.get("reign_end") or {}
    for c in (f.campaign or {}).values():
        if (c or {}).get("player_id") == key:
            return (c or {}).get("reign_end") or {}
    return {}


def _chrono_office(f, cid, date):
    """The office title of the holder on that day: the Japanese top title uses the bare
    word from `japan_top_office` (关白 / 太政大臣 / 幕府将军 / 上皇 / 天皇), other titles
    use `official_title`; "" when unavailable."""
    if not date:
        return ""
    try:
        w = f.japan_top_office(cid, date) or f.official_title(cid, date=date) or ""
    except Exception:
        w = ""
    return w


def _chrono_joko_clause(f, cid, date):
    """The "上皇" clause: "关白之序及身，乃退天皇位，称上皇". Event 9120 fires when a new holder takes
    `e_japan` (关白) while the title in `e_japan.var:administrative_ui_special_title` (the
    Chrysanthemum Throne, `k_chrysanthemum_throne`) is still his
    (`common/on_action/title_on_actions.txt:1461-1487`); it makes him leave the throne (to
    `player_heir`, ending his holding interval the day after his accession) and adds `joko_flag` and
    `former_emperor` (`events/dlc/tgp/tgp_japan_general_events.txt:733-767`), so the title begins on
    the accession day and the clause follows the accession clause. Without evidence he still held the
    throne that day, only "，称上皇" is written."""
    tid = f.title_by_key("k_chrysanthemum_throne")
    date_key = cl.date_key(date) if date else None
    if isinstance(tid, int) and date_key:
        ivs = f._hold_intervals(cid).get(tid)
        if ivs is None:
            ivs = (f._hold_intervals(cid) or {}).get(str(tid))
        for iv in (ivs or []):
            try:
                gain, loss = iv[0], iv[1]
            except (IndexError, TypeError):
                continue
            if gain and loss and cl.date_key(gain) <= date_key < cl.date_key(loss):
                return "，关白之序及身，乃退天皇位，称上皇"
    return "，称上皇"


def _chrono_ruler_line(f, tid, date, cid, hist_type, prev, loss_date,
                       vacant=False, is_h=False, family=False, nm=None,
                       prev_date=None, dtor=False):
    """One ruler per row, e.g. "关白{名}，卒930年4月9日，享年55岁，死于心脏病发作；…；在位3年，922年7月7日
    剃发退位，传位于{继承人}" or "西山阴道一族{名}，995年7月25日受封西山阴道栋梁" (family row).

    Shape: no birth item; the death item reads "卒{date}，享年{N}岁，{cause}" from the existing
    `death_clause`, using the most complete record across caches; the title is glued to the name with
    no "｜" column and is the **last** title of the reign, a later change being added inside the row
    ("，开府，改称幕府将军") so the final word is not read as held from the start; abdication
    (`reign_end`) outranks `lost_title_memory` for the loss, and the 上皇 clause follows the accession
    clause (see `_chrono_joko_clause`); no "卒于位" at the row end. "" means the row has nothing to
    write and the caller drops it."""

    nm = nm or _chrono_nm(f, cid, date)
    if not nm:
        return "", False
    rec = _chrono_rec(f, cid)
    if family:
        word = _SUCC_WORD.get(hist_type or "", "") or ""
        acq = _chrono_acc_text(f, cid, date, word, None)
        tname = f.title(tid, date=date) if tid is not None else ""
        # The family row likewise has no "｜" column: the title name is glued to the
        # person's name and followed by the accession clause.
        head = f"{tname}{nm}" if tname else nm
        row = f"{head}，{acq}" if acq else head
        # Report whether the row has everything (title / accession clause) so the chronicle block can
        # drop a row with no material; the old "｜" counting no longer works.
        return row, bool(tname) and bool(acq)
    birth = rec.get("birth") or ""
    # The death comes from the fullest record first, then from `_char_death_date`'s fallback chain.
    # The chain matters most for the biographee: `pipeline._backfill_tail_deaths` skips the player, so
    # his death lives only in `cache["player_death"]` and never in `characters[]`.
    _d0 = rec.get("death") or {}
    death = _d0.get("date") or f._char_death_date(cid) or ""
    # death item = date + age at death + cause (the cause from the existing
    # `death_clause`, the record being the most complete across caches)
    dead_bits = []
    if death:
        dead_bits.append("卒" + f.date(death))
        _age = _chrono_year_age(birth, death)
        if _age is not None:
            dead_bits.append("享年%d岁" % _age)
        _reason = _d0.get("reason") or ""
        _killer = _d0.get("killer")
        if str(cid) == str(f.cache.get("player_id")):
            # `death_clause` reads the cause and the killer from `characters[]` too, so the player's
            # own death has to hand them over explicitly.
            _pd = f.cache.get("player_death") or {}
            _reason = _reason or _pd.get("reason") or ""
            if _killer is None:
                _killer = _pd.get("killer")
        try:
            # The killer's title is read as of the day before the event (the same rule as `_anchor_date`:
            # on the death day the title has already passed to the heir), else the killer would be named
            # by an office he had just acquired.
            _clause = f.death_clause(cid, date=death, reason=_reason,
                                     killer=_killer,
                                     killer_date=_day_before(death))
        except Exception:
            _clause = ""
        if _clause:
            dead_bits.append(_clause)
    word = _chrono_accession_reason(f, cid, tid, hist_type, date)
    if hist_type == "created":
        if is_h:
            word = _CELLESTIAL_CREATE_VERB["takeover" if not vacant else "vacant"]
        else:
            word = _TITLE_GAIN_CREATED_VERBS_ZH.get(
                f.created_verb_kind(tid, cid, date)) or "创建"
    acq = _chrono_acc_text(f, cid, date, word, prev,
                           from_prev=(hist_type in (None, "", "appointment_succession",
                                                    "abdication", "inheritance")),
                           prev_date=prev_date)
    if not word and prev is not None and isinstance(prev, int):
        # No clue in either source (no `type` in the title history, nothing in the memory record) ->
        # write the regular "继位" from the predecessor's succession ("no type = regular inheritance");
        # the first ruler gets the accession date alone rather than a guessed reason.
        _pn = _chrono_nm(f, prev, prev_date or date)
        if _pn:
            _rel = _chrono_rel_word(f, cid, prev)
            acq = ("%s从%s%s处继位" % (f.date(date), _rel, _pn) if _rel
                   else "%s从%s处继位" % (f.date(date), _pn))
    age = _chrono_year_age(birth, date)
    if age is not None:
        acq += "，时年%d岁" % age
    _real_loss = _chrono_loss_date(f, cid, tid, loss_date)
    if _real_loss is None and dtor:
        _real_loss = loss_date          # the next event destroys the title (holder = loser)
    _end = _real_loss or loss_date or death
    span = _chrono_span(date, _end)
    # The title is the last title of the reign: one title word per row, glued to the name. Listing two
    # side by side ("X，后为Y") made the model keep only the first, losing the final title.
    office = _chrono_office(f, cid, date)
    _o2 = ""
    if _end:
        _a2 = f._anchor_date(cid, _end)
        _t2, _tid2 = f._primary_title_at(cid, as_of=_a2)
        if isinstance(_tid2, int) and _tid2 == tid:
            _o2 = _chrono_office(f, cid, _a2)
    _last = _o2 or office
    # the 上皇 title begins on the accession day, so this clause follows the accession clause
    _joko = _chrono_joko_clause(f, cid, date) if _last == f._JAPAN_OFFICE_JOKO else ""
    tail = ""
    _re = _chrono_reign_end(f, cid)
    _red = _re.get("date") or ""
    if _red and _end and cl.date_key(_red) == cl.date_key(_end):
        # abdication: the abdication word and the heir (heir's name only)
        _w = f.reign_end_word(_re)
        _succ = _re.get("successor")
        _snm = _chrono_nm(f, _succ, _red) if isinstance(_succ, int) else ""
        _srel = _chrono_rel_word(f, cid, _succ) if isinstance(_succ, int) else ""
        tail = "，" + f.date(_red) + _w + (f"，传位于{_srel}{_snm}" if _snm else "")
    elif _real_loss and not (death and cl.date_key(death) == cl.date_key(_real_loss)):
        # died in office (loss date == death date): no tail, the death item already says it
        tail = "，随后于" + f.date(_real_loss) + ("失去天命" if is_h else "失去头衔")
    if _o2 and _o2 != office and _o2 != f._JAPAN_OFFICE_JOKO:
        # A title change during the reign (惣領制 plus the `shogun_flag` on the title =
        # 开府): the title slot holds only the last word, so the change is added inside
        # the row to keep the model from reading that last word as held from the start.
        tail = ("，开府，改称幕府将军" if _o2 == f._JAPAN_OFFICE_SHOGUN
                else f"，改称{_o2}") + tail
    bits = [x for x in (acq + _joko, span) if x]
    body = "；".join(bits) + tail
    head = f"{_last}{nm}" if _last else nm
    segs = [x for x in (dead_bits and "，".join(dead_bits), body) if x]
    if not segs:
        return "", False
    row = head + "".join(("，" if i == 0 else "；") + s for i, s in enumerate(segs))
    # "Has everything" means the row carries a title word and an accession clause / reign span — the
    # same two things the family row above reports. An unrecorded death leaves the row worth writing,
    # so it must not void the flag: doing so dropped the biographee's own row and left the chronicle's
    # closing section with no material at all.
    return row, bool(_last) and bool(bits)


def _chrono_group(items, max_n):
    """Split items as evenly as possible into at most `max_n` chunks (empty chunks are
    not returned)."""
    items = list(items or [])
    if not items:
        return []
    n = max(1, min(int(max_n), len(items)))
    base, extra = divmod(len(items), n)
    out, i = [], 0
    for k in range(n):
        m = base + (1 if k < extra else 0)
        if m:
            out.append(items[i:i + m])
        i += m
    return out


def _chrono_label(f, cid, date=None):
    """Name used in war rows: the name alone, since the row already opens with this side's
    title."""
    return f.name_with_regnal(cid, date) or f.name_or(cid, "") or ""


def _chrono_war_lines(f, tid):
    """War rows of this title: the year war was raised + the opponent + the decisive year and
    outcome, one sentence per row. Source: the cache memories `offensive_war` / `defensive_war`
    whose `war_title` is this title (`war_attacker` = the side that raised the war), with the
    outcome from `war_won` / `war_lost` against the same opponent."""
    tid = int(tid)
    wars, wins = [], []
    for _cid, _rec in (f.cache.get("characters") or {}).items():
        try:
            cid = int(_cid)
        except (TypeError, ValueError):
            continue
        for m in (_rec.get("memories") or []):
            ty = m.get("type")
            if ty not in ("offensive_war", "defensive_war", "war_won", "war_lost"):
                continue
            wt, atk = None, None
            for v in (m.get("vars") or []):
                if v.get("flag") == "war_title" and v.get("identity") is not None:
                    try:
                        wt = int(v.get("identity"))
                    except (TypeError, ValueError):
                        wt = None
                elif v.get("flag") == "war_attacker" and v.get("identity") is not None:
                    try:
                        atk = int(v.get("identity"))
                    except (TypeError, ValueError):
                        atk = None
            if wt != tid:
                continue
            d = str(m.get("creation_date") or "")
            parts = m.get("participants") or {}
            if ty in ("offensive_war", "defensive_war"):
                opp = parts.get("other_party")
                if not isinstance(opp, int):
                    opp = atk
                wars.append((d, cid, opp if isinstance(opp, int) else None, ty))
            else:
                opp = parts.get("loser") if ty == "war_won" else parts.get("winner")
                wins.append((d, cid, opp if isinstance(opp, int) else None, ty))
    out, seen = [], set()
    for (d, cid, opp, ty) in sorted(wars, key=lambda x: cl.date_key(x[0])):
        me = f.date(d) + _chrono_label(f, cid)             + ("兴兵" if ty == "offensive_war" else "应战")
        if isinstance(opp, int):
            me += ("讨" if ty == "offensive_war" else "拒")                 + (_chrono_label(f, opp) or "来犯之敌")
        for (wd, wcid, wopp, wty) in wins:
            if wcid != cid or cl.date_key(wd) < cl.date_key(d):
                continue
            if isinstance(opp, int) and isinstance(wopp, int) and opp != wopp:
                continue
            me += "；" + f.date(wd) + ("战胜" if wty == "war_won" else "败于")                 + (_chrono_label(f, wopp) if isinstance(wopp, int) else "对手")
            break
        # With no decisive result found, no "；胜负未见记载" is added: a clause with no
        # material only consumes the model's attention (the same rule as
        # `_pair_war_events`: write the war-raising clause alone).
        me += "。"
        if me in seen:
            continue
        seen.add(me)
        out.append(me)
        if len(out) >= _CHRONICLE_WAR_MAX:
            break
    return out


def _chrono_base_name(f, tid, date=None):
    """The title's base name, without the tier word: k_qingxu -> "青徐".

    The same form as `_base_name` inside `_realm_facts`, which is a closure, hence this
    module-level copy."""
    t = f._lt.get(str(tid)) or {}
    key = t.get("key") or ""
    if not key:
        return ""
    d = date or f.as_of or f.cache.get("last_date")
    nm = f._name_at_date(tid, d) or L.loc(f.table, key) or key
    nm = str(nm).strip()
    return nm if not re.search(r"[A-Za-z_]", nm) else ""


def _chrono_sub_lines(f, tid, pid=None):
    """Capital / territory rows of this reign: the capital comes from the already computed
    `protagonist.capital` (the same output as the profile, so the two cannot disagree),
    and the territory row lists the vassal titles hanging under this title. A row is
    omitted entirely when unavailable."""
    out = []
    capname = ""
    if pid is not None:
        capname = (getattr(f, "_protagonist_cache", None) or {}).get("capital") or ""
    if capname:
        out.append("治所：" + str(capname))
    holders = {}
    for h in (f.cache.get("realm_history") or []):
        for k, v in (h.get("holders") or {}).items():
            if v is not None:
                holders[str(k)] = v
    subs = []
    for k in holders:
        t = f._lt.get(str(k)) or {}
        if (t.get("de_facto_liege") or t.get("liege")) == tid:
            nm = _chrono_base_name(f, int(k))
            if nm and nm not in subs:
                subs.append(nm)
    if subs:
        out.append("本朝所辖：" + "、".join(subs[:12]))
    return out


def _chrono_accs(f, tid, as_of):
    """Acquisition sequence of this title: [(date, holder, type, end, vacant)].

    When the title history is empty (nomadic yurt etc.) it falls back to the per-snapshot
    records, with an empty reason."""
    evs = _title_hist_events(f, tid, end=as_of)
    if not evs:
        evs = [(d, h, None) for d, h in _realm_holder_seq(f, tid, end=as_of)]
    out, prev, vacant = [], None, False
    for i, (d, h, ty) in enumerate(evs):
        if h is None:
            continue
        if ty == "destroyed":
            prev, vacant = None, True
            continue
        if prev is None or h != prev:
            out.append((d, h, ty, evs[i + 1][0] if i + 1 < len(evs) else None, vacant))
        prev, vacant = h, False
    return out


def _chrono_prev_for(accs, idx):
    """The previous holder before that event in the acquisition sequence, which keeps the
    inheritance chain readable; None when there is none."""
    for j in range(idx - 1, -1, -1):
        h = accs[j][1]
        if isinstance(h, int):
            return h
    return None


def _chrono_holder_now(f, tid, pid, accs):
    """One line naming the title's holder at the close of this volume, with his office and house —
    e.g. 「本朝现任（1000年1月1日）：教宗洪审礼（洪氏）」.

    The chronicle's rows stop at the last accession the volume covers, so without this line nothing
    in the material says who sits on the seat afterwards, and a closing section that lost its rows
    had only that silence to go on. A final volume is cut at the biographee's death day and the seat
    usually passes that same day, so once the biographee is dead by `as_of` the next recorded holder
    is named instead of him."""
    if not accs:
        return ""
    as_of = f.as_of or f.cache.get("last_date") or ""
    when, cid = accs[-1][0], accs[-1][1]
    if isinstance(cid, int) and cid == pid and f._char_death_date(pid):
        nxt = next(((d, h) for d, h, _ty, _e, _v in _chrono_accs(f, tid, None)
                    if isinstance(h, int) and h != cid and d
                    and (not as_of or cl.date_key(d) >= cl.date_key(as_of))), None)
        if nxt:
            when, cid = nxt
    if not isinstance(cid, int):
        return ""
    nm = _chrono_nm(f, cid, when)
    if not nm:
        return ""
    off = _chrono_office(f, cid, when)
    house = ""
    try:
        house = f._house_label_at(cid, when)
    except Exception:
        house = ""
    who = f"{off}{nm}" if off else nm
    if house:
        who += f"（{house}）"
    if cid == pid:
        who += "，即传主"
    return "本朝现任（%s）：%s" % (f.date(when) if when else "本卷之末", who)


def _chrono_build(f, tid, pid, is_h, own, periods, tname):
    """《历代记》 part material: one person per row, plus parts and wars / branches. A title the
    biographee created and solely held becomes a family chronicle; with no titled father or mother (a
    custom character) it returns None. Otherwise the chronicle is organised by dynasty-name periods,
    one person per row."""
    accs = _chrono_accs(f, tid, f.as_of or f.cache.get("last_date"))
    if len(accs) == 1 and accs[0][1] == pid and (accs[0][2] or "") == "created":
        return _family_chronicle(f, pid, tid, is_h=is_h)
    if not periods:
        return None
    for k, p in enumerate(periods):
        p["end"] = periods[k + 1]["start"] if k + 1 < len(periods) else None
    claimed = set()
    for p in periods:
        for gi, (d, h, ty, end, vac) in enumerate(accs):
            if h not in p["ids"] or gi in claimed:
                continue
            # Attribution rule: the accession date falls before this period (a period's holder may have
            # acceded before the campaign window while the period starts at the campaign start), and he
            # was still in office before the next period began.
            claimed.add(gi)
            # when the next event destroys the title (holder = the loser), this tenure's
            # end date is the real loss date
            _dtor = bool(gi + 1 < len(accs) and accs[gi + 1][2] == "destroyed")
            # The row text and the "has everything" flag are stored one to one (empty rows keep their
            # slot), as are each row's accession date and person id, which the sectioner needs to
            # compute a section's date range and vassals (`biography._chrono_row_chunks`).
            _row, _detail = _chrono_ruler_line(
                f, tid, d, h, ty, _chrono_prev_for(accs, gi), end,
                vacant=vac, is_h=is_h, dtor=_dtor,
                prev_date=(accs[gi - 1][0] if gi > 0 else None))
            p["rows"].append(_row)
            p.setdefault("rows_detail", []).append(bool(_detail))
            # Each row's accession date and person id, one to one with `rows`, for the sectioner.
            p.setdefault("rows_dates", []).append(str(d))
            p.setdefault("rows_ids", []).append(int(h))
    if not any(p["rows"] for p in periods):
        return None
    cur = next((p for p in reversed(periods) if p.get("ids")), None)
    return {
        "name": tname,
        "family": False,
        "tid": int(tid),
        "is_h": bool(is_h),
        "current": cur,
        "periods": periods,
        "holder_now": _chrono_holder_now(f, tid, pid, accs),
        "wars": _chrono_war_lines(f, tid) if is_h else [],
        "subs": _chrono_sub_lines(f, tid, pid),
    }


def _family_chronicle(f, pid, tid, is_h=False):
    """Family chronicle: the title was created by the biographee and solely held by him, so the
    chronicle runs from the earliest ruling ancestor to him; None with no titled parent (a custom
    character). Entries are same-dynasty ancestors up the father / mother chain, each taking his
    earliest holding, oldest accession first and the biographee last (max
    `_CHRONICLE_ANCESTOR_MAX`)."""
    p_dyn = f._dynasty_of_cid(pid)
    seen, queue = set(), []
    fam0 = (_chrono_rec(f, pid).get("family") or {})
    for key in ("father", "mother"):
        for pcid in (fam0.get(key) or []):
            if isinstance(pcid, int) and pcid != pid and pcid not in seen:
                seen.add(pcid)
                queue.append(pcid)
    picked = []
    while queue:
        cid = queue.pop(0)
        if f._dynasty_of_cid(cid) == p_dyn:
            hold = f._holder_intervals.get(cid) or {}
            if hold:
                best = None
                for t, ivs in hold.items():
                    for iv in ivs:
                        if iv and iv[0] and (best is None
                                             or cl.date_key(iv[0]) < cl.date_key(best[0])):
                            best = (iv[0], int(t), iv[1] if len(iv) > 1 else None,
                                    iv[2] if len(iv) > 2 else "")
                if best:
                    picked.append((best[0], cid, best[1], best[2], best[3]))
        fam = (_chrono_rec(f, cid).get("family") or {})
        for key in ("father", "mother"):
            for pcid in (fam.get(key) or []):
                if isinstance(pcid, int) and pcid != cid and pcid not in seen:
                    seen.add(pcid)
                    queue.append(pcid)
    if not picked:
        return None
    picked.sort(key=lambda x: cl.date_key(x[0]))
    picked = picked[-_CHRONICLE_ANCESTOR_MAX:]
    rows, details = [], []
    for idx, (d, cid, atid, loss, _lt2) in enumerate(picked):
        _pv = f._gain_prev.get((cid, atid, d))
        if _pv is None and idx > 0:
            _pv = picked[idx - 1][1]
        line, _det = _chrono_ruler_line(
            f, atid, d, cid, f._gain_reason.get((cid, atid, d), ""),
            _pv, loss, is_h=is_h, family=True,
            nm=_chrono_nm(f, cid, d), prev_date=(picked[idx - 1][0] if idx else None))
        if line:
            rows.append(line)
            details.append(bool(_det))
    ivs = (f._hold_intervals(pid) or {}).get(tid) or []
    own_g = ivs[-1][0] if ivs else None
    own_l = ivs[-1][1] if ivs else None
    own_line, own_det = _chrono_ruler_line(f, tid, own_g, pid, "created",
                                           (picked[-1][1] if picked else None), own_l,
                                           is_h=is_h, family=True,
                                           nm=f.name(pid))
    if own_line:
        rows.append(own_line)
        details.append(bool(own_det))
    if not rows:
        return None
    name = (f.name(pid) or f.cache.get("player_name") or "") + "家"
    _fam_cur = {"name": "家族", "start": (picked[0][0] if picked else own_g),
                "end": own_l, "vacant": False,
                "ids": [p[1] for p in picked] + [pid], "rows": rows,
                "rows_detail": details,
                "rows_dates": [p[0] for p in picked] + [own_g],
                "rows_ids": [p[1] for p in picked] + [pid]}
    return {
        "name": name,
        "family": True,
        "tid": int(tid),
        "is_h": bool(is_h),
        "current": _fam_cur,
        "periods": [_fam_cur],
        "wars": _chrono_war_lines(f, tid) if is_h else [],
        "subs": _chrono_sub_lines(f, tid, pid),
    }


def _is_final_bio(f):
    """Whether this chapter is the final biography (《XX历代记》 triggers only there): the
    biographee's position has ended **and** the cut-off date is exactly that end date (`_bio_as_of`
    hands a final biography the end date; a decade biography gets the decade's end; a living one has
    none). End = `player_death` or a reign that ended without death (`reign_end`: tonsure, abdication
    and the like switch the played character; the abdication date wins when both exist)."""
    return _is_final_bio_spec({
        "decade": f.decade,
        "as_of": f.as_of,
        "player_death": f.cache.get("player_death"),
        "reign_end": f.cache.get("reign_end"),
    })


def _is_final_bio_spec(facts):
    """The facts-side version of `_is_final_bio`, the same criterion, used by
    `biography.build_articles` for cross-checking. The end date is `reign_end`
    (abdication) first, then `player_death` (death)."""
    facts = facts or {}
    if facts.get("decade"):
        return False
    end = ((facts.get("reign_end") or {}).get("date")
           or (facts.get("player_death") or {}).get("date") or "")
    if not end:
        return False
    as_of = facts.get("as_of")
    if not as_of:
        return True
    try:
        _a = (tuple(cl.date_key(str(as_of))) + (1, 1))[:3]
        _b = (tuple(cl.date_key(str(end))) + (1, 1))[:3]
        _d = (_a[0] - _b[0]) * 366 + (_a[1] - _b[1]) * 31 + (_a[2] - _b[2])
        return -7 <= _d <= 7
    except Exception:
        return str(as_of) == str(end)


def _top_title_history(f, group_lines=None):
    """The succession history of this reign, material for the part title 《XX历代记》: the holders of
    the protagonist's current top title since the campaign start. Returns (common name for the part
    title, [summary lines...], part material); ("", [], {}) when there is nothing to write.

    One line per dynasty as "{国号}{tier word}（{起}至{止}）" (preceded by "本朝：", followed by
    本朝疆域 / 主角本朝任期 lines), then its holders oldest to newest as "{名}（{即位日}{缘由}）"; a
    vacancy with the mandate destroyed but the dynasty name unchanged reads "群雄争霸". Reasons come
    from the save's `history.<date>.type` (see `_SUCC_WORD`; no type = regular inheritance)."""
    pid = f.cache.get("player_id")
    if pid is None:
        return "", [], {}
    # This part triggers only for a final biography: a living biography (not yet dead) and
    # every decade biography skip 《XX历代记》, the succession history being complete
    # already and not worth retelling once a decade.
    if not _is_final_bio(f):
        return "", [], {}
    as_of = f.as_of or f.cache.get("last_date")
    start = _campaign_start(f)
    tid, own = None, False
    _t, _tid = f._primary_title_at(pid, as_of=f.as_of)
    if _tid is not None and _t is not None:      # a real domain -> his own top title
        tid, own = _tid, True
    else:
        cut = f.as_of or (f.cache.get("reign_end") or {}).get("date") \
            or (f.cache.get("player_death") or {}).get("date") \
            or f.cache.get("last_date")
        if cut:
            _t2, _tid2 = f._primary_title_at(pid, held_through=cut)
            if _tid2 is not None and _t2 is not None:   # dead / abdicated: still holding at the end date
                tid, own = _tid2, True
        if tid is None:                              # estate only -> the top liege's court
            if any(f._is_estate_title(t) for t in (f._hold_intervals(pid) or {})):
                tid = _estate_court_tid(f, pid)
    if tid is None:                                  # adventurer camp only -> part skipped
        return "", [], {}
    t = f._lt.get(str(tid)) or {}
    key = t.get("key") or ""
    tnd = t.get("title_name_data") or {}
    _disp = f._name_at_date(tid, as_of) or f.title_base_name(tid) or ""
    tname = f.title(tid, as_of) or _disp
    if not tname:
        return "", [], {}
    # Common name for the part title: a title with a dynasty-rename history uses its own
    # common name (h_china -> 中华, covering 唐宋元…); others use the base name of that
    # day's display name (k_norway -> 挪威, not 挪威王国).
    common = L.loc(f.table, key) or _disp if f._has_reign_history(tid) else _disp
    if not common:
        common = tname
    lines = [("本朝：" if own else "所附之朝：") + tname]

    # ---- dynasty name segments (title_history_names): [name, start, end] ----
    segs = []
    names = tnd.get("title_history_names") or []
    for h in names:
        if not isinstance(h, dict) or not h.get("date") or not h.get("name"):
            continue
        d = h.get("date")
        if f.as_of and cl.date_key(d) > cl.date_key(f.as_of):
            break
        raw = str(h.get("name"))
        v = L.loc(f.table, raw) or ""
        if not v or re.search(r"[A-Za-z_]", v):
            v = "" if re.search(r"[A-Za-z_]", raw) else raw
        if not v:
            continue
        segs.append([v, d, None])
    for i in range(len(segs) - 1):
        segs[i][2] = segs[i + 1][1]
    # keep only the dynasty segments intersecting [campaign start, as_of]; ancient
    # segments predating the start (汉 / 晋 / 隋 …) drop out entirely
    if start:
        segs = [s for s in segs
                if not (s[2] and cl.date_key(s[2]) <= cl.date_key(start))]

    # Each dynasty on its own line, followed by its holders oldest to newest with accession reason.
    is_h = key.startswith("h_")
    _evs = _title_hist_events(f, tid, end=as_of)
    plain = False
    if not _evs:                    # no per-snapshot title history -> snapshot fallback, no reason
        _evs = [(d, h, None) for d, h in _realm_holder_seq(f, tid, end=as_of)]
        plain = True
    accs, losses = [], []           # accs[(date, holder, type, end, was vacant)]; losses[(date, holder)]
    _prev, _vacant = None, False
    for _i, (_d, _h, _ty) in enumerate(_evs):
        if _h is None:
            continue
        if _ty == "destroyed":      # destroyed: holder = loser (2983 of 2985 match the previous holder)
            if _prev is not None and _h == _prev:
                losses.append((_d, _h))
            _prev, _vacant = None, True
            continue
        if _prev is None or _h != _prev:
            accs.append((_d, _h, _ty,
                         _evs[_i + 1][0] if _i + 1 < len(_evs) else None, _vacant,
                         _vacant))
        _prev, _vacant = _h, False

    seg_rows = [[_nm, _s, _e, [], False]
                for _nm, _s, _e in (segs or [[_disp, None, None]])]
    # A dynasty rename is recorded 0-3 days after the holder changes, so an accession
    # falling within 7 days after a dynasty segment's start belongs to the **new** segment;
    # otherwise a founding ruler would be counted into the previous dynasty.
    for _gi, (_d, _h, _ty, _end, _vac, _was_vac) in enumerate(accs):
        if start and _end and cl.date_key(_end) <= cl.date_key(start):
            continue                # rulers who left office before the campaign start are not listed
        _dk, _pick, _best = _date_ord(_d), 0, None
        for _j, (_nm2, _s2, _e2, _hs2, _v2) in enumerate(seg_rows):
            if not _s2:
                continue
            _sk = _date_ord(_s2)
            if _sk <= _dk + 7 and (_best is None or _sk > _best):
                _best, _pick = _sk, _j
        seg_rows[_pick][3].append((_gi, _d, _h, _ty))
        if _was_vac:
            seg_rows[_pick][4] = True

    def _span(s, e):
        """Date range for a dynasty line: years, with months added when the change happens
        within one year."""
        y1, m1 = str(s).split(".")[0], str(s).split(".")[1]
        if e is None:
            return f"{y1}年至今"
        y2, m2 = str(e).split(".")[0], str(e).split(".")[1]
        if y1 == y2:
            return f"{y1}年{m1}月至{y1}年{m2}月"
        return f"{y1}年至{y2}年"

    # Dynasty name = dynasty segment name + tier suffix, the suffix taken from the display name at the
    # narrative end date (元皇朝 -> 皇朝; 挪威王国 -> 王国) rather than per segment, since for a
    # celestial empire `h_` the tier word appears only while the holder runs that government.
    _base_now = f._name_at_date(tid, as_of) or ""
    _full_now = f.title(tid, as_of) or ""
    _suf = _full_now[len(_base_now):] if (_base_now and _full_now.startswith(_base_now)) else ""

    periods = []
    for _i, (_nm, _s, _e, _hs, _vac0) in enumerate(seg_rows):
        _st = _hs[0][1] if _hs else _s
        if _st is None:
            continue
        if start and _date_ord(_st) < _date_ord(start):
            _st = start                    # a dynasty line starts at the campaign window
        _nx = (seg_rows[_i + 1][3][0][1] if (_i + 1 < len(seg_rows)
                                             and seg_rows[_i + 1][3])
               else (seg_rows[_i + 1][1] if _i + 1 < len(seg_rows) else None))
        if _nx is not None and start and _date_ord(_nx) < _date_ord(start):
            continue
        _hdr = ((_nm + _suf) if (_suf and _nm and not _nm.endswith(_suf)) else _nm) \
            if _nm else (_full_now or tname)
        if not _hs and is_h:
            _hdr = "群雄争霸"              # vacancy: mandate destroyed, dynasty name unchanged
        lines.append(_hdr + "（" + _span(_st, _nx) + "）")
        _items = []
        for (_gi, _d, _h, _ty) in _hs:
            _hn = f.name_or(_h, "") or ""
            if not _hn:
                continue
            if plain:
                _txt = f"{_hn}（{f.date(_d)}起在位"
            elif _ty == "created":
                # Rebuilding after a vacancy and founding a new mandate are two different
                # things; the code looks at whether the immediately preceding event was a
                # destroy event.
                _w = ("重建天命" if is_h else "重建头衔") if accs[_gi][4] \
                    else ("建立天命" if is_h else "自立建国")
                _txt = f"{_hn}（{f.date(_d)}{_w}"
            else:
                _w = _SUCC_WORD.get(_ty or "", "继位")
                _pn = (f.name_or(accs[_gi - 1][1], "") or "") \
                    if (_ty in _SUCC_FROM_PREV and _gi > 0) else ""
                _txt = f"{_hn}（{f.date(_d)}" + (f"从{_pn}处{_w}" if _pn else _w)
            for (_ld, _lh) in losses:
                if _lh == _h and _date_ord(_ld) >= _date_ord(_d):
                    _txt += "，随后于" + f.date(_ld) \
                        + ("失去天命" if is_h else "失去头衔")
                    break
            _items.append(_txt + "）")
        periods.append({"name": _hdr, "start": _st, "vacant": bool(_vac0),
                        "ids": [x[2] for x in _hs], "rows": []})
        if _items:
            lines.append("、".join(_items))
        elif is_h:
            _lo = [ld for ld, _lh in losses if _date_ord(ld) <= _date_ord(_st)]
            lines.append((f.date(max(_lo, key=_date_ord)) if _lo else "")
                         + "天命中绝，天下无主")
        else:
            lines.append("其间无主")
    gl = (group_lines or {}).get(tid)
    if gl:
        lines.append("本朝疆域：" + gl.split("：", 1)[-1])
    ivs = (f._hold_intervals(pid) or {}).get(tid) or []
    if own and ivs:
        _g, _l = ivs[-1][0], ivs[-1][1]
        if not _l:
            # An open interval means the melt still had him on the seat. A final volume is cut at his
            # death, so the tenure closes there; only a death after this volume's cutoff keeps 至今.
            _cand = f._char_death_date(pid) or (f.cache.get("reign_end") or {}).get("date") or ""
            if _cand and not (f.as_of and cl.date_key(_cand) > cl.date_key(f.as_of)):
                _l = _cand
        lines.append("主角本朝任期：" + f.date(_g)
                     + ("–" + f.date(_l) if _l else " 至今"))
    return common, lines, _chrono_build(f, tid, pid, is_h, own, periods, tname)


def _realm_facts(f):
    """Realm data: the player's liege chain + holder changes of empire/kingdom-tier titles."""
    out = {}
    # The player's liege chain (last snapshot). When as_of predates the last snapshot (a decade
    # biography) the current melt's chain is late-snapshot state, which cannot be rebuilt per period, so
    # it is omitted rather than written wrongly.
    pid = f.cache.get("player_id")
    if pid is not None and not (f.as_of and cl.date_key(f.as_of) < cl.date_key(
            f.cache.get("last_date") or f.as_of or "9999.9.9")):
        prov = f.character_location_province(pid)
        county_tid = f.county_at_province(prov)
        chain = f.liege_chain(county_tid) if county_tid else []
        if chain:
            parts = []
            for tid, hid in chain:
                hn = f.name_or(hid, "") if hid is not None else ""
                # title joined straight to its holder ("唐皇朝李漼"), no parenthetical
                # appositive
                parts.append(f"{f.title(tid)}{hn}" if hn else f.title(tid))
            # When the protagonist tops the chain, say he is independent, so the model does
            # not confuse his own polity with the other titles in the same table.
            top_hid = chain[-1][1]
            tail = "，自立，上无领主" if top_hid == pid else ""
            out["liege_chain"] = " → ".join(parts) + tail
    # Holder changes of high titles (h_/e_/k_): exact title-history dates with realm_history snapshots as
    # fallback, the title name following the tenure so renames show. Only "relevant" high titles are
    # collected (liege chain + titles once held by related characters); court offices (e_minister_*) stay out.
    if f.as_of:
        rh = [h for h in f.cache.get("realm_history") or []
              if cl.date_key(h.get("date")) <= cl.date_key(f.as_of)]
    else:
        rh = f.cache.get("realm_history") or []
    # History events are kept only from ~30 years before the first snapshot: this drops
    # ancient-history noise while keeping this reign's renames and usurpations.
    min_dk = min((cl.date_key(h.get("date")) for h in rh), default=None)
    hist_min_y = (min_dk[0] - 30) if min_dk else None

    # relevant character set: family / friends / foes / court office holders (a high title
    # is collected only when it was once theirs)
    related = _related_ids(f)
    for _cid, _rec in (f.cache.get("characters") or {}).items():
        for _m in _rec.get("memories") or []:
            if _m.get("type") in ("became_friends", "became_soulmates",
                                  "became_blood_brother", "became_rivals",
                                  "became_grudge", "became_nemesis"):
                for _v in (_m.get("participants") or {}).values():
                    if isinstance(_v, int) and _v == pid:
                        related.setdefault(int(_cid), 2)
                        break
    for h in f.cache.get("court_positions") or []:
        for p in h.get("positions") or []:
            if isinstance(p.get("employee"), int):
                related.setdefault(p["employee"], 2)

    # titles in the protagonist's liege chain, top liege included: the backbone of this reign
    chain_tids = set()
    try:
        prov = f.character_location_province(pid)
        county_tid = f.county_at_province(prov)
        if county_tid is not None:
            chain_tids.update(int(t) for t, _h in f.liege_chain(county_tid) or [])
    except Exception:
        pass

    # (1) the exact title-history sequence (primary source)
    hist_map = {}  # tid -> [(date, holder), ...]
    for tid, t in f._lt.items():
        if not isinstance(t, dict):
            continue
        key = t.get("key") or ""
        if not key.startswith(("h_", "e_", "k_")):
            continue
        if key.startswith("e_minister_"):  # court offices are listed separately
            continue
        hist = t.get("history") or {}
        if not isinstance(hist, dict) or not hist:
            continue
        seq = []
        for d, ev in sorted(hist.items(), key=lambda x: cl.date_key(x[0])):
            if f.as_of and cl.date_key(d) > cl.date_key(f.as_of):
                break
            if hist_min_y is not None:
                try:
                    if int(str(d).split(".")[0]) < hist_min_y:
                        continue
                except Exception:
                    pass
            holder = ev.get("holder") if isinstance(ev, dict) else ev
            if isinstance(holder, list):
                # several events on one day (destroyed + created etc.; duplicate keys
                # merge into a list)
                for _h2 in holder:
                    if isinstance(_h2, dict):
                        if _h2.get("holder") is not None:
                            seq.append((d, _h2["holder"]))
                    elif _h2 is not None:
                        seq.append((d, _h2))
            elif holder is not None:
                seq.append((d, holder))
        if seq:
            hist_map[int(tid)] = seq
    # (2) realm_history snapshots: fill in only the titles the title history does not
    # cover, removing double counting between the two sources
    for h in rh:
        for tid, holder in (h.get("holders") or {}).items():
            t = f._lt.get(str(tid)) or {}
            key = t.get("key") or ""
            if not key.startswith(("h_", "e_", "k_")):
                continue
            if key.startswith("e_minister_"):
                continue
            if holder is None or int(tid) in hist_map:
                continue
            hist_map.setdefault(int(tid), []).append((h.get("date"), holder))

    # (3) relevance filter: titles in the liege chain / titles once held by related characters
    keep_tids = set(chain_tids)
    for tid, seq in hist_map.items():
        if tid in keep_tids:
            continue
        if any(int(h) in related for _d, h in seq):
            keep_tids.add(tid)
    span_end = f.as_of or f.cache.get("last_date")
    changes = []
    # Liege annotation: high-title changes used to be one line each, all peers, so the model could not
    # tell that 青徐 was a vassal kingdom of 唐. Each title's nearest empire/hegemon liege now comes from
    # the melt's `de_facto_liege` (walking up `de_jure_liege` when it fails to move), annotated per line
    # and grouped into a "same court" row. The jure fallback must land on a title that **existed**, since
    # the save gives `de_jure_liege` a value even for never-created empty titles and emitting them would
    # put a phantom empire into the facts (`Facts._ever_held_title`).
    def _up_liege(tid):
        seen = set()
        cur = tid
        while cur is not None and cur not in seen:
            seen.add(cur)
            t = f._lt.get(str(cur)) or {}
            nxt = t.get("de_facto_liege")
            if not isinstance(nxt, int):
                cand = t.get("de_jure_liege")
                nxt = cand if (isinstance(cand, int)
                               and f._ever_held_title(cand)) else None
            if not isinstance(nxt, int):
                return cur if cur != tid else None
            cur = nxt
        return None

    liege_of = {}
    for tid in sorted(keep_tids):
        sup = _up_liege(tid)
        if sup is not None and sup != tid:
            # Self-check: a liege must be a title that existed. The de_facto chain should
            # only point at held titles; this catches save anomalies so a phantom polity
            # cannot leak into the facts by any path.
            if not f._ever_held_title(sup):
                _PHANTOM_LIEGE_LOG["lines"] += 1
                if len(_PHANTOM_LIEGE_LOG["samples"]) < 12:
                    _PHANTOM_LIEGE_LOG["samples"].append(
                        f"{f.cache.get('player_id')}: 头衔 {tid} 的法理宗主 "
                        f"{sup} ({(f._lt.get(str(sup)) or {}).get('key') or ''}) 从未创建")
                try:
                    llm.log(f"幽灵宗主: 头衔 {tid} 的法理宗主 {sup} "
                            f"({(f._lt.get(str(sup)) or {}).get('key') or ''}) "
                            f"history 空且无持有者 — 不写宗主标注", detail=True)
                except Exception:
                    pass
                continue
            liege_of[tid] = sup
    # grouping: liege -> the high titles under it (the tier word comes from the tier)
    vassal_groups = {}
    for tid, sup in liege_of.items():
        vassal_groups.setdefault(sup, []).append(tid)

    def _group_suffix(tid):
        """Liege annotation for this title: "，为唐皇朝封臣"; a title with no liege (a polity
        of its own) gets none. No parentheses -- it is a clause of the same sentence."""
        sup = liege_of.get(tid)
        if sup is None:
            return ""
        nm = _simple_name(sup)
        return f"，为{nm}封臣" if nm else ""

    def _simple_name(tid):
        """The title's court / dynastic common name, taken from the holder at `span_end`
        (h_china -> "唐皇朝"). Used for the liege annotation."""
        t = f._lt.get(str(tid)) or {}
        if not (t.get("key") or ""):
            return ""
        return f._title_name_at(tid, span_end)

    def _base_name(tid):
        """The title's base name, without the tier word: k_qingxu -> "青徐".

        The grouping row uses it so tier words that depend on the holder's independence (the
        same title reads 国 while an emperor also holds it and 路 when a subject is
        appointed) do not mix into one row."""
        t = f._lt.get(str(tid)) or {}
        key = t.get("key") or ""
        if not key:
            return ""
        nm = f._name_at_date(tid, span_end) or L.loc(f.table, key) or key
        return str(nm).strip()

    def _tier_tail(name):
        """The tier-word tail of a name (国 / 路 / 州府 / 皇朝 / 伯爵领 …), used to detect a
        tier-word change within one line.

        "国" is the tier word of an independent celestial kingdom (`_tier_word_at` looks up
        `kingdom_celestial_chinese_independent`) and is absent from GENERIC_TIER_ZH, so it is
        added here."""
        for w in sorted(f._rank_words | {"国"}, key=len, reverse=True):
            if w and name.endswith(w):
                return w
        return ""

    def _name_stem(name):
        """The base name with the tier-word tail removed (青徐国 -> 青徐)."""
        t = _tier_tail(name)
        return name[:len(name) - len(t)] if t else name

    for tid in sorted(keep_tids):
        seq = sorted(hist_map.get(tid) or [], key=lambda x: cl.date_key(x[0]))
        if not seq:
            continue
        # dedupe: one row per (date, holder), since the title history and the snapshots can
        # repeat the same day
        dedup = []
        seen_k = set()
        for d, holder in seq:
            k = (cl.date_key(d), holder)
            if k in seen_k:
                continue
            seen_k.add(k)
            dedup.append((d, holder))
        prev = None
        prev_nm = None
        prev_tail = ""
        bits = []
        for i, (d, holder) in enumerate(dedup):
            if holder == prev:
                continue
            hn = f.name_or(holder, "") if holder is not None else "无"
            end = dedup[i + 1][0] if i + 1 < len(dedup) else span_end
            nm = f._name_in_span(tid, d, end, cid=holder)
            tail = _tier_tail(nm) if nm else ""
            # 国 vs 路 depends on whether that tenure's holder is independent (青徐国 while an emperor
            # holds it, 青徐路 for an appointed subject) -- not a rename. Same base name with a
            # different tier word: keep the first alone, the liege annotation states the affiliation.
            if nm and tail and prev_tail and tail != prev_tail \
                    and _name_stem(nm) == _name_stem(prev_nm):
                nm = ""
            if nm and nm != prev_nm:
                bits.append(f"{nm}：{f.date(d)}：{hn}")
                prev_nm = nm
                prev_tail = tail
            else:
                bits.append(f"{f.date(d)}：{hn}")
            prev = holder
        if len(bits) > 1:
            changes.append("，".join(bits) + _group_suffix(tid))
    # Group the titles of one liege into a row, so "唐皇朝" and "青徐国" read as superior and
    # subordinate in one court rather than as two coexisting polities. The grouping rows are
    # also stored by liege tid for the territory row of 《XX历代记》.
    group_lines = {}
    for sup in sorted(vassal_groups):
        names = []
        for tid in vassal_groups[sup]:
            nm = _base_name(tid)
            if nm and nm not in names:
                names.append(nm)
        if len(names) < 2:
            continue
        snm = _base_name(sup) or _simple_name(sup)
        if not snm:
            continue
        _gln = f"{snm}朝廷所辖，同属一廷：" + "、".join(names)
        changes.append(_gln)
        group_lines[sup] = _gln
    # order: liege-chain titles first (by descending rank), the rest as they are
    def _sort_key(ln):
        nm = ln.split("：", 1)[0]
        for tid in chain_tids:
            if nm.startswith(f.title(tid)):
                return (0, -f._TT_RANK.get((f._lt.get(str(tid)) or {}).get("key", "")[:2], 0))
        return (1, 0)
    changes.sort(key=_sort_key)
    if changes:
        out["holder_changes"] = changes
    # court offices (the six ministries / censorate / bureau of military affairs: the holders
    # at as_of plus the office title)
    min_off = f._current_ministers(f.as_of)
    if min_off:
        out["ministers"] = min_off
    # Court offices granted to the protagonist (太师 etc.), used by the rise-and-fall section
    # of 朝局风云录; only offices the protagonist himself received (employee = protagonist),
    # kept apart from the retainer roster.
    col, coch = f.court_office_lines()
    if col:
        out["protagonist_offices"] = col
    if coch:
        out["protagonist_office_changes"] = coch
    # Secrets of the powerful: those of the liege chain (emperor / province / kingdom) and of
    # the current court office holders; 朝局风云录 records the top ruler's secrets.
    out["secrets"] = _realm_secret_lines(f)
    # Succession history of this reign: the dynasty-name evolution and successive holders of the
    # protagonist's current top title since the campaign start (《XX历代记》; an estate holder writes the
    # top liege's title history, an adventurer camp is skipped). `holder_changes` remains for other callers.
    _tt_common, _tt_lines, _tt_chronicle = _top_title_history(
        f, group_lines=group_lines)
    if _tt_lines:
        out["top_title_history"] = _tt_lines
        out["top_title_name"] = _tt_common
    if _tt_chronicle:
        out["dynasty_chronicle"] = _tt_chronicle
    return out


def _realm_secret_lines(f):
    """Secret sentences for the powerful: the liege-chain holders (the protagonist excluded)
    plus the current court office holders, capped at 6; [] when there are none. A holder
    carries his office title (唐皇帝李漼 / 御史大夫郭克勤), and the secret shares its sentence
    with its knowers."""
    pid = f.cache.get("player_id")
    owners = []
    try:
        prov = f.character_location_province(pid)
        county = f.county_at_province(prov)
        for _tid, hid in (f.liege_chain(county) if county else []):
            if isinstance(hid, int) and hid != pid:
                owners.append(hid)
    except Exception:
        pass
    for hid in f.minister_ids(f.as_of):
        if hid != pid and hid not in owners:
            owners.append(hid)
    out = []
    for oid in owners:
        for rec in f.secrets_owned_by(oid, f.as_of):
            s = f.secret_line(rec, owner_label=f.person_label(oid, date=f.as_of, style="brief"),
                              self_cid=pid, owner=oid)
            if not s:
                continue
            out.append(s)
            if len(out) >= 6:
                return out
    return out


# Villainy topic modules, computed directly by `_villain_chains` rather than mapped from
# memory types. The module names also feed the decade drama theme extraction (build_facts
# merges them into decade_modules).
VILLAIN_MODULES = ("谋害人命", "托卵承嗣", "奸夫谋夫", "共谋暗杀", "血亲之刃", "血脉登基")

# scheme participant agent type -> Chinese (the melt's schemes `agent_slots`; fallback when
# localization is missing)
_AGENT_ZH = {
    "agent_assassin": "刺客", "agent_lookout": "眼线", "agent_lookout_speed": "眼线",
    "agent_infiltrator": "内应", "agent_thug": "打手", "agent_muscle": "打手",
    "agent_footpad": "暴徒", "agent_thief": "窃贼", "agent_outcast": "亡命徒",
    "agent_sycophant": "谄媚者", "agent_intermediary": "中间人", "agent_amanuensis": "文书",
    "agent_bureaucrat": "僚属", "agent_diplomat": "说客", "agent_scout": "探子",
    "agent_alibi": "伪证者", "agent_poet": "文士", "agent_musician": "乐师",
    "agent_herald": "传令官", "agent_gabbler": "饶舌者", "agent_socialite": "交际花",
    "agent_political_socialite": "政界名流", "agent_shill": "托儿", "agent_courtesan": "名妓",
    "agent_eunuch": "阉人", "agent_bodyguard": "护卫", "agent_decoy": "诱饵",
    "agent_supplier": "供货人", "agent_cleric": "神职人员", "agent_cleric_success": "神职人员",
    "agent_theologian": "神学家", "agent_planner": "谋士", "agent_bailiff": "执达吏",
    "agent_scribe": "书吏", "agent_draughtsman": "画师", "agent_proponent": "拥趸",
}


_REL_LOC_TAG_RE = re.compile(
    r"\[(TARGT_CHARACTER|TCHARACTER|TARGET_CHARACTER_2|TARGET_CHARACTER|CHARACTER|PROVINCE)\."
    r"([A-Za-z_][^\]]*?)(?:\|[A-Za-z0-9_]+)?\]")
# Tags with no role prefix: the game calls these on the default scope (an activity type's name, a
# trait's name, a title looked up by key).
_REL_STANDALONE_TAG_RE = re.compile(
    r"\[(GetActivityType\('[A-Za-z0-9_]+'\)\.GetName"
    r"|GetTrait\('[A-Za-z0-9_]+'\)\.GetName\([^)]*\)"
    r"|GetTitleByKey\('[A-Za-z0-9_]+'\)\.GetName)(?:\|[A-Za-z0-9_]+)?\]")
# Lowercase concept refs inside reason templates ([house|E] 家族, [rivalry|E] 仇恨, [strong_hook|E] 强牵制);
# resolved through the localization table's game_concept_<key> entries.
_REL_CONCEPT_RE = re.compile(r"\[([a-z][a-z0-9_]*)(?:\|[A-Za-z0-9_]+)?\]")
# The game misspells the counterpart slot in a few templates (TARGT_CHARACTER in
# friend_token_reward_corresponding, TCHARACTER in two 1.20 reasons); both mean TARGET_CHARACTER.
_REL_ROLE_ALIAS = {"TARGT_CHARACTER": "TARGET_CHARACTER", "TCHARACTER": "TARGET_CHARACTER"}


def _province_label(f, province):
    """Province id -> place name (county title, else barony title); '' if unknown."""
    if province is None:
        return ""
    try:
        tid = f.county_at_province(province) or f.barony_at_province(province)
    except Exception:
        return ""
    if tid is None:
        return ""
    try:
        return f.title(tid) or ""
    except Exception:
        return ""


def _sub_relation_loc(f, s, owner, target, extra=None, province=None, names=None):
    """Relation-cause localization string -> clean Chinese sentence, placeholders filled.

    Tags: [CHARACTER.*] record owner, [TARGET_CHARACTER.*] counterpart,
    [TARGET_CHARACTER_2.*] third party (involved_character, e.g. a dungeon owner),
    [PROVINCE.*] event province — plus the game's own misspellings of the counterpart slot. `|U`
    is the English uppercase variant and is ignored in Chinese; Possessive takes the bare name (no
    Chinese inflection). `names` optionally supplies the (owner, target, third party) appellations
    for callers that need the `event_name` wording.

    Accessors are dispatched per role/place rather than through an enumerated replacement table,
    because that table misses `|U` and NoTooltip combinations and the trailing clearing regex then
    eats the subject/object. Values come from the same outlets the rest of the fact layer uses:
    `name_or`/`person_label` for names, `_house_of_cid` for houses, `faith` for a faith name,
    `_culture_language_id` for a culture's language, `_trait_name` for a trait, the localization
    table for concepts, activities and kin words. The kept-tag list lives in
    `localization._KEEP_DYN_RE` and the two must stay in step.

    A tag whose value cannot be produced (or a template that needs the third slot while `extra` is
    missing) drops the WHOLE sentence and returns '' — a hole in a sentence reads as if the game
    had said it, and a raw tag would leak a key into the prompt.
    """
    if names is not None:
        oname, tname, xname = (list(names) + ["", "", ""])[:3]
    else:
        oname = f.name_or(owner)
        tname = f.name_or(target)
        xname = f.name_or(extra) if isinstance(extra, int) else ""
    pname = _province_label(f, province) if province is not None else ""
    need = [False]
    _hcache = {}
    _ccache = {}

    def _cid(role):
        return {"CHARACTER": owner, "TARGET_CHARACTER": target,
                "TARGET_CHARACTER_2": extra}.get(role)

    def _appellation(role):
        """The role's appellation: the caller-supplied wording when it has one, else `name_or`."""
        if names is not None:
            return {"CHARACTER": oname, "TARGET_CHARACTER": tname,
                    "TARGET_CHARACTER_2": xname}.get(role) or ""
        cid = _cid(role)
        return f.name_or(cid) if isinstance(cid, int) else ""

    def _given_name(cid):
        """The character's given name (as opposed to the surname-carrying display name)."""
        if not isinstance(cid, int):
            return ""
        rec = (f.cache.get("characters") or {}).get(str(cid)) or {}
        v = rec.get("name_zh") or ""
        if not v:
            c = f._chars.get(str(cid)) or {}
            v = (cl.name_zh(c) if c else "") or ""
        return v

    def _hname(cid):
        """House name of a character ('' if none; memoized per id)."""
        if not isinstance(cid, int):
            return ""
        if cid in _hcache:
            return _hcache[cid]
        try:
            hid = f._house_of_cid(cid)
        except Exception:                                 # noqa: BLE001
            hid = None
        nm = (cl.house_name_zh(f.melt, hid) or "") if hid is not None else ""
        if not nm:
            did = cl.dynasty_id_of(f.melt, hid) if hid is not None else None
            nm = (cl.dynasty_name_zh(f.melt, did) or "") if did is not None else ""
        _hcache[cid] = nm
        return nm

    def _concept(key):
        """`game_concept_<key>` wording ([house|E] -> 家族), '' when the table lacks it."""
        if key in _ccache:
            return _ccache[key]
        v = L.loc(f.table, "game_concept_" + key) or ""
        if v.startswith(("$", "[")):
            v = ""
        _ccache[key] = v
        return v

    def _rep(m):
        role, acc = _REL_ROLE_ALIAS.get(m.group(1), m.group(1)), m.group(2)
        cid = _cid(role)
        if role == "PROVINCE":
            if acc.startswith("GetName"):
                return pname or "当地"
            need[0] = True
            return ""
        # The third slot has no value when the save gave no involved_character: emit no sentence
        # rather than attribute the deed to the placeholder name.
        if role == "TARGET_CHARACTER_2" and not isinstance(extra, int):
            need[0] = True
            return ""
        # names
        if acc.startswith(("GetShortUI", "GetUIName", "GetName", "GetPossessive")):
            return _appellation(role)
        if acc.startswith("GetTitledFirstName"):
            if not isinstance(cid, int):
                need[0] = True
                return ""
            return f.person_label(cid, date=f.as_of, style="brief") or f.name_or(cid)
        if acc.startswith("GetFirstName"):
            v = _given_name(cid)
            if not v:
                need[0] = True
            return v
        if acc.startswith(("GetDynastyHouseName", "GetHouse.GetName")):
            v = _hname(cid)
            if not v:
                need[0] = True
            return v
        # gender / kin words
        fem = bool(isinstance(cid, int) and f._is_female(cid))
        if acc.startswith("GetHerHis"):
            return "其"
        if acc.startswith(("GetHerHim", "GetSheHe")):
            return "她" if fem else "他"
        if acc.startswith("GetHerselfHimself"):
            return "她自己" if fem else "他自己"
        if acc.startswith("GetWomanMan"):
            return "女" if fem else "男"
        if acc.startswith("GetMotherFather"):
            return "母" if fem else "父"
        if acc.startswith("GetWifeHusband"):
            return "妻" if fem else "夫"
        if "GetDaughterSon" in acc:
            return "女儿" if fem else "儿子"
        if "child_favorite_toy" in acc:
            return "玩具"
        # faith / culture
        if acc.startswith("GetFaith.GetName"):
            try:
                v = f.faith(cid) or ""
            except Exception:                             # noqa: BLE001
                v = ""
            if not v:
                need[0] = True
            return v
        if acc.startswith("GetDeathReason"):
            # The third party's death reason (rival_killed_heir: "发誓要为<死法>的<某人>复仇")
            try:
                rec = (f.cache.get("characters") or {}).get(str(cid)) or {}
                rk = (rec.get("death") or {}).get("reason") \
                    or ((f._chars.get(str(cid)) or {}).get("dead_data") or {}).get("reason")
            except Exception:                             # noqa: BLE001
                rk = None
            v = _death_reason(f.table, rk) if rk else ""
            if not v:
                need[0] = True
            return v
        if acc.startswith("GetCulture.GetLanguage.GetName"):
            v = ""
            try:
                lg = f._culture_language_id(cid) if isinstance(cid, int) else None
                if lg:
                    v = L.loc(f.table, f"{lg}_name") or L.loc(f.table, lg) or ""
            except Exception:                             # noqa: BLE001
                v = ""
            if not v or v.startswith(("$", "[")):
                need[0] = True
                return ""
            return v
        if acc.startswith("GetCulture.GetCollectiveNoun"):
            # e.g. han -> 汉 (the game's <culture>_collective_noun keys)
            v = ""
            try:
                tpl = f.culture_template(cid) if isinstance(cid, int) else ""
                if tpl:
                    v = L.loc(f.table, f"{tpl}_collective_noun") or ""
            except Exception:                             # noqa: BLE001
                v = ""
            if not v or v.startswith(("$", "[")):
                need[0] = True
                return ""
            return v
        # activity / trait
        mm = re.match(r"GetActivityType\('([^']+)'\)\.GetName", acc)
        if mm:
            v = L.loc(f.table, mm.group(1)) or ""
            if not v or v.startswith(("$", "[")):
                need[0] = True
                return ""
            return v
        mm = re.match(r"GetTrait\('([^']+)'\)\.GetName", acc)
        if mm:
            v = _trait_name(f.table, mm.group(1)) or ""
            if not v:
                need[0] = True
            return v
        if acc.startswith("GetTitleByKey("):
            mm = re.match(r"GetTitleByKey\('([^']+)'\)", acc)
            v = ""
            if mm:
                tid = f.title_by_key(mm.group(1))
                if tid is not None:
                    v = f.title(tid) or ""
            if not v:
                need[0] = True
            return v
        # A tag this build cannot resolve must not appear (see localization._KEEP_DYN_RE); drop the
        # sentence rather than leave a hole where the game named someone.
        need[0] = True
        return ""

    def _srep(m):
        """Role-less tags (activity / trait / title-by-key); a missing value drops the sentence."""
        acc = m.group(1)
        mm = re.match(r"GetActivityType\('([^']+)'\)\.GetName", acc)
        if mm:
            v = L.loc(f.table, mm.group(1)) or ""
            if v and not v.startswith(("$", "[")):
                return v
        mm = re.match(r"GetTrait\('([^']+)'\)\.GetName", acc)
        if mm:
            v = _trait_name(f.table, mm.group(1)) or ""
            if v:
                return v
        mm = re.match(r"GetTitleByKey\('([^']+)'\)\.GetName", acc)
        if mm:
            tid = f.title_by_key(mm.group(1))
            v = (f.title(tid) or "") if tid is not None else ""
            if v:
                return v
        need[0] = True
        return ""

    def _crep(m):
        v = _concept(m.group(1))
        if not v:
            need[0] = True
        return v

    s = _REL_LOC_TAG_RE.sub(_rep, s)
    if need[0]:
        return ""
    s = _REL_STANDALONE_TAG_RE.sub(_srep, s)
    if need[0]:
        return ""
    s = _REL_CONCEPT_RE.sub(_crep, s)
    if need[0]:
        return ""
    # Named tags still unrecognized (Select_CString(...) and the stripped custom locs) are cleared
    s = re.sub(r"\[[^\]]*\]", "", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _player_murder_map(f):
    """Player's murders: {victim_id: murder date} from successful_murder memories unioned
    with death records whose killer is the player (shared by _villain_chains /
    relation_cause_lines). Memoized on the Facts instance: the villain pool asks it
    repeatedly per victim, and the full scan need not be redone."""
    memo = getattr(f, "_murder_map_memo", None)
    if memo is not None:
        return memo
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        f._murder_map_memo = {}
        return {}
    chars = cache.get("characters") or {}
    prec = chars.get(str(pid)) or {}
    murders = {}
    for m in prec.get("memories") or []:
        if m.get("type") == "successful_murder":
            v = (m.get("participants") or {}).get("victim")
            if isinstance(v, int) and v != pid:
                d = m.get("creation_date")
                if d:
                    murders.setdefault(v, d)
    for cid, rec in chars.items():
        if int(cid) == pid:
            continue
        d = (rec.get("death") or {}).get("date")
        if d and (rec.get("death") or {}).get("killer") == pid:
            murders.setdefault(int(cid), d)
    f._murder_map_memo = murders
    return murders


def relation_cause_lines(f, cid, rel_date):
    """Why the player and a character feuded, computed directly rather than from the
    generic "feud started on date X" line: ① kin of the character (father/mother/spouse/
    child/siblings) murdered by the player, death predating the feud; ② the character's
    spouse having an affair with the player; ③ a child the character raised actually being
    the player's blood. Returns e.g. ['其父…已于…被…谋杀', ...]. Friend relations (when a
    friendship began) are covered by the biography-side _relation_reasons."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None or cid == pid or not rel_date:
        return []
    rd = cl.date_key(rel_date)
    chars = cache.get("characters") or {}
    cfam = (chars.get(str(cid)) or {}).get("family") or {}
    murders = _player_murder_map(f)
    pname = f.name_or(pid)
    c_female = f._is_female(cid)
    out = []
    # ① kin murdered by the player (death before the feud)
    rel_keys = (("father", "其父"), ("mother", "其母"),
                ("primary_spouse", "其妻"), ("spouse", "其妻"),
                ("former_spouses", "其前妻"), ("child", "其子"),
                ("siblings", "其兄弟姊妹"))
    for key, label in rel_keys:
        for rid in cfam.get(key) or []:
            if not isinstance(rid, int):
                continue
            md = murders.get(rid)
            if not md or cl.date_key(md) >= rd:
                continue
            rname = f.name_or(rid)
            if not rname:
                continue
            if key == "child":
                label = "其女" if f._is_female(rid) else "其子"
            elif key in ("primary_spouse", "spouse"):
                label = "其夫" if c_female else "其妻"
            out.append(f"{label}{rname}已于{f.date(md)}"
                       + f.death_clause(rid, date=md))
            break
    # ② spouse having an affair with the player (affair started before the feud)
    lovers = set()
    prec = chars.get(str(pid)) or {}
    for m in prec.get("memories") or []:
        if m.get("type") in ("became_lovers", "had_sex"):
            for v in (m.get("participants") or {}).values():
                if isinstance(v, int) and v != pid:
                    d = m.get("creation_date")
                    if d and cl.date_key(d) < rd:
                        lovers.add(v)
    spouse_label = "其夫" if c_female else "其妻"
    found_spouse = False
    for key in ("primary_spouse", "spouse", "former_spouses"):
        if found_spouse:
            break
        for sid in cfam.get(key) or []:
            if sid in lovers:
                sname = f.name_or(sid)
                if sname:
                    out.append(f"{spouse_label}{sname}与{pname}私通")
                    found_spouse = True
                break
    # ③ child raised as theirs is the player's blood (born before the feud)
    for cid2 in cfam.get("child") or []:
        if not isinstance(cid2, int):
            continue
        fam2 = (chars.get(str(cid2)) or {}).get("family") or {}
        rf = (fam2.get("real_father") or [None])[0]
        if rf != pid:
            continue
        c2name = f.name_or(cid2)
        b = (chars.get(str(cid2)) or {}).get("birth")
        if c2name and b and cl.date_key(b) < rd:
            sex = "女" if f._is_female(cid2) else "子"
            out.append(f"其抚养之{c2name}实为{pname}之{sex}")
            break
    # ④ trigger entry of the two houses' same-day rupture. The game reason
    #    `rival_house_feud_start_of_feud` states only the result (the two characters
    #    became rivals), not why the feud began; the cause sits in the same-day house
    #    relation flow. Criterion: among that day's entries naming the two houses, the one
    #    that names the player but not the enemy -- the entry naming the enemy is the
    #    "became rivals" result itself and is excluded. Wording shares `_rerender_feud_event`
    #    with 《家族恩怨录》. Its two ends are game-baked short names, never re-rendered
    #    through `event_name`, so both the full name and the given name (before "·") are
    #    matched. If that entry is a feud-reason prison string, the causal clause is used
    #    instead, so the real imprisonment date is reported rather than the feud date.
    try:
        _cname = f.name_or(cid)
        _pforms = {x for x in (pname, (pname or "").split("·")[0]) if x}
        _clause = f.house_feud_reason_clause(f._house_of_cid(pid),
                                             f._house_of_cid(cid), rel_date)
        if _clause:
            out.append(_clause)
        else:
            for _txt in f.house_flow_on(f._house_of_cid(pid),
                                        f._house_of_cid(cid), rel_date):
                if _cname and _cname in _txt:
                    continue
                if any(x in _txt for x in _pforms):
                    out.append(f"{f.date(rel_date)}，{_txt}")
                    break
    except Exception:
        pass
    return out


# War wording: when the feud history adds a causal node, the same-day original war
# sentence is replaced by that node.
_WAR_KIND_WORDS = ("宣战", "开战", "应战", "战胜", "战败", "赢得战争")

# Imprisonment wording: the same-day original "囚禁了X" is replaced by the node that also
# carries the release circumstances.
_PRISON_KIND_WORDS = ("囚禁了", "囚禁")

# Execution wording: an original execution sentence duplicating a same-day, same-person
# imprisonment node is replaced by that node, whose wording covers both ends.
_EXEC_KIND_WORDS = ("处决了",)

# 《家族恩怨录》 and the villain biographies read the raw house_relations flow, where the
# same event appears in two sentence forms with reversed id order and the reason form
# carries the feud-escalation date instead of the event date:
#   * event form (desc, `house_relations_l_simp_chinese.yml:44-51`):
#     "[char]囚禁了[target_char]" / "[char]谋杀了[target_char]" ...
#     -> id order is (actor, victim), date is the event date;
#   * feud-reason form (feud head, `:78-95`):
#     "[house_feud_victim]被[house_feud_attacker]无理由囚禁" / "...被...谋杀" /
#     "...被...残忍地折磨" ... -> id order is (victim, actor), date is the escalation date.
#     Exception: the cuckold line (`:90`) is active voice with desc's id order, so it is
#     not listed below.
# Reading the flow strictly by id order reverses such lines, so reason-form prison entries
# enter no event and create no node -- 15 of 16 measured reason entries have a same-victim
# event-form counterpart in the same relation record. Villain feud causes are instead
# rewritten as causal sentences carrying the real date (`house_feud_reason_clause`).
_FEUD_HEAD_KINDS = (
    # (kind, reason-form keyword, event-form keyword, causal sentence pattern)
    ("prison", "囚禁", "囚禁了", "为{j}所囚"),
    ("murder", "谋杀", "谋杀了", "被{j}谋杀"),
    ("torture", "折磨", "折磨了", "为{j}所折磨"),
    ("castrate", "阉割", "阉割了", "被{j}阉割"),
    ("blind", "致盲", "致盲了", "被{j}致盲"),
)


def _feud_head_kind(raw):
    """Row of `_FEUD_HEAD_KINDS` if the flow entry is a passive feud-reason sentence, else
    None. A match needs the reason keyword, no event-form keyword, and "被". `raw` is
    `house_relations.database[*].history[*].change_reason` (the rendered sentence keeps
    "被" as well, so either form works)."""
    s = str(raw or "")
    if "被" not in s:
        return None
    for row in _FEUD_HEAD_KINDS:
        if row[1] in s and row[2] not in s:
            return row
    return None


def _is_feud_reason_prison(raw):
    """True if the flow entry is a passive feud-reason imprisonment sentence (id order =
    prisoner, actor). Prison is closed off separately: such entries enter no event and create
    no node, because the imprisonment already has an event-form entry."""
    row = _feud_head_kind(raw)
    return bool(row) and row[0] == "prison"

# These chains write "who is whose biological child" onto the sentence surface -- a private
# matter no annalist could know, so they feed only the private volumes (《家室列传》/《阴私录》).
_PRIVATE_CHAIN_MODULES = frozenset({"托卵承嗣", "血脉登基"})

CHAIN_PRIVATE = _PRIVATE_CHAIN_MODULES


def _villain_chains(f):
    """Villainous relation chains computed in code: [(module name, sentence, revealing)].

    Sources: cached family/death/memories plus melt titles/heir/schemes. Modules: 奸夫谋夫 (the
    player murdered a lover's spouse, remarriage included); 托卵承嗣 (legal father != real
    father); 共谋暗杀 (melt active murder schemes owned by the player -> agent_slots); 血亲之刃
    (the player murdered his own blood kin); 血脉登基 (a k_/e_/h_ first heir is really the
    player's bastard child, plus any murdered same-mother sibling). Entries are truncated at
    as_of. The third value marks revealing chains (`_PRIVATE_CHAIN_MODULES`), which state who is
    whose biological child and go only into private volumes."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    chars = cache.get("characters") or {}
    prec = chars.get(str(pid)) or {}
    pname = f.name_or(pid)
    ao = cl.date_key(f.as_of) if f.as_of else None

    def in_span(d):
        return ao is None or (d and cl.date_key(d) <= ao)

    def is_female(cid):
        return f._is_female(cid)

    # ---- player's lovers: cid -> earliest affair/lovers date ----
    lovers = {}
    for m in prec.get("memories") or []:
        if m.get("type") in ("became_lovers", "had_sex"):
            for v in (m.get("participants") or {}).values():
                if isinstance(v, int) and v != pid:
                    d = m.get("creation_date") or ""
                    if v not in lovers or (d and (not lovers[v] or d < lovers[v])):
                        lovers[v] = d
    # ---- player's murders: victim -> murder date (memories ∪ death records) ----
    murders = {}
    for m in prec.get("memories") or []:
        if m.get("type") == "successful_murder":
            v = (m.get("participants") or {}).get("victim")
            if isinstance(v, int) and v != pid:
                d = m.get("creation_date")
                if d:
                    murders.setdefault(v, d)
    for cid, rec in chars.items():
        if int(cid) == pid:
            continue
        d = (rec.get("death") or {}).get("date")
        if d and (rec.get("death") or {}).get("killer") == pid:
            murders.setdefault(int(cid), d)

    chains = []
    pfam = prec.get("family") or {}

    # ---- lover's spouse murdered (killing the spouse / the spouse's remarriage) ----
    for victim, vdate in sorted(murders.items(),
                                key=lambda kv: cl.date_key(kv[1])):
        if not in_span(vdate):
            continue
        vfam = (chars.get(str(victim)) or {}).get("family") or {}
        vname = f.name_or(victim)
        if not vname:
            continue
        for sid in list(dict.fromkeys(
                (vfam.get("primary_spouse") or []) + (vfam.get("spouse") or []))):
            if sid == pid or sid not in lovers:
                continue
            lname = f.name_or(sid)
            if not lname:
                continue
            # whether the widow(er) has married the player (marriage date from either side's
            # memories)
            mdate = ""
            for m in prec.get("memories") or []:
                if m.get("type") == "married" and \
                        (m.get("participants") or {}).get("spouse") == sid:
                    mdate = m.get("creation_date") or ""
                    break
            if not mdate:
                for m in (chars.get(str(sid)) or {}).get("memories") or []:
                    if m.get("type") == "married" and \
                            (m.get("participants") or {}).get("spouse") == pid:
                        mdate = m.get("creation_date") or ""
                        break
            sname = "其妻" if not is_female(victim) else "其夫"
            # uniform victim appellation (office/title + name, anchored to the death date)
            disp = f.person_label(victim, date=f.as_of, style="brief") or vname
            remarry = f"，并于{f.date(mdate)}嫁于{pname}" \
                if mdate and in_span(mdate) else ""
            # the victim's kin was slain earlier too -> append a note; the shared name prefix keeps
            # the kinship correct, so the model does not read the kin's name as the victim's elder
            kin_note = ""
            for kid in (vfam.get("child") or []):
                if not isinstance(kid, int) or kid not in murders:
                    continue
                kd = murders[kid]
                if cl.date_key(kd) >= cl.date_key(vdate):
                    continue
                kname = f.person_label(kid, date=f.as_of, style="brief") or f.name_or(kid)
                if kname:
                    ksex = "女" if is_female(kid) else "子"
                    # public volumes use the publicly known account; the undisclosed are not
                    # named
                    kin_note = (f"；其{ksex}{kname}已于{f.date(kd)}"
                                + f.death_clause(kid, date=kd))
                break
            # the victim's own fate likewise uses the public record wording
            _vcl = f.death_clause(victim, date=vdate)
            chains.append(("奸夫谋夫",
                f"{f.date(vdate)}，{disp}{_vcl}——"
                f"{sname}{lname}正是{pname}的情人{remarry}{kin_note}。", False))

    # ---- cuckoo child (legal father != real father, player involved) -- merged by
    # (legal father, real father, sex)
    cuckoo = {}   # (lf, rf, sex, direction) -> [child names]
    for cid, rec in chars.items():
        fam = rec.get("family") or {}
        rf = (fam.get("real_father") or [None])[0]
        lf = (fam.get("father") or [None])[0]
        if rf is None or lf is None or rf == lf:
            continue
        if not in_span(rec.get("birth")):
            continue
        if rf != pid and lf != pid:
            continue
        cname = f.name_or(int(cid))
        if not cname:
            continue
        sex = "女" if is_female(int(cid)) else "子"
        key = (lf, rf, sex)
        cuckoo.setdefault(key, []).append(cname)
    for (lf, rf, sex), items in cuckoo.items():
        lfname = f.name_or(lf)
        rfname = f.name_or(rf)
        if not items or not lfname or not rfname:
            continue
        # dramatic-event chains carry no birth-year parenthetical: the kinship label already
        # disambiguates, disambiguation staying in the assassin death row / timeline murder row
        joined = "、".join(items)
        if rf == pid:
            chains.append(("托卵承嗣",
                f"{lfname}抚养的{joined}，实为{pname}之{sex}。", True))
        else:
            chains.append(("托卵承嗣",
                f"{pname}抚养的{joined}，实为{rfname}之{sex}。", True))

    # ---- conspiracy (melt active schemes: murder plots the player leads) ----
    schemes = ((f.melt.get("schemes") or {}).get("active") or {})
    for _scid, sc in schemes.items():
        if not isinstance(sc, dict) or sc.get("type") != "murder":
            continue
        owner = sc.get("owner")
        tgt = sc.get("target")
        if isinstance(tgt, dict):
            tgt = tgt.get("target")
        sdate = sc.get("date") or ""
        if sdate and not in_span(sdate):
            continue
        agents = []
        for slot in (sc.get("agent_slots") or []):
            if not isinstance(slot, dict):
                continue
            c = slot.get("character")
            # 4294967295 (0xFFFFFFFF) is CK3's empty-slot placeholder, not a real character
            if isinstance(c, int) and 0 < c < 4294967295 and c != pid and c != owner:
                an = f.name_or(c)
                if an:
                    t = L.loc(f.table, slot.get("type") or "") or \
                        _AGENT_ZH.get(slot.get("type") or "") or "同谋"
                    agents.append((an, t))
        if owner == pid and isinstance(tgt, int) and tgt != pid:
            tname = f.name_or(tgt)
            if not tname:
                continue
            if agents:
                # the role word is prefixed and joined with the name ("同谋张三") rather than
                # appended as a parenthetical; same-role agents are grouped ("同谋张三、李四")
                by_role = {}
                order = []
                for an, at in agents[:3]:
                    if at not in by_role:
                        by_role[at] = []
                        order.append(at)
                    by_role[at].append(an)
                shown = [f"{at}{'、'.join(by_role[at])}" for at in order]
                tail = f"等{len(agents)}人" if len(agents) > 3 else ""
                chains.append(("共谋暗杀",
                    f"密谋刺杀{tname}者以{pname}为首，"
                    f"参与者{'、'.join(shown)}{tail}。", False))
            else:
                chains.append(("共谋暗杀",
                    f"{pname}正密谋刺杀{tname}。", False))
        elif isinstance(tgt, int) and tgt == pid and isinstance(owner, int) and owner != pid:
            oname = f.name_or(owner)
            if oname:
                chains.append(("共谋暗杀",
                    f"{oname}正密谋刺杀{pname}。", False))

    # ---- kin-slaying (murder of own blood kin) ----
    for victim, vdate in murders.items():
        if not in_span(vdate):
            continue
        rel = ""
        if victim in (pfam.get("child") or []):
            rel = f"自己的{'女' if is_female(victim) else '子'}"
        elif victim in (pfam.get("father") or []):
            rel = "自己的父亲"
        elif victim in (pfam.get("mother") or []):
            rel = "自己的母亲"
        elif victim in (pfam.get("primary_spouse") or []) + (pfam.get("spouse") or []):
            rel = "自己的妻室"
        elif victim in (pfam.get("siblings") or []):
            rel = "自己的兄弟姊妹"
        if rel:
            vname = f.name_or(victim)
            if vname:
                # public volumes use the publicly known account -- for an undisclosed killing
                # `death_clause` already omits the name (mysterious death / vanished ...)
                chains.append(("血亲之刃",
                    f"{rel}{vname}{f.death_clause(victim, date=vdate)}。", False))

    # ---- throne succession (first heir to a high title is the player's bastard child; a
    # murdered same-mother sibling is named as well) ----
    melt_date = (f.melt.get("date") or "")
    as_of_gap = bool(f.as_of) and cl.date_key(f.as_of) < cl.date_key(melt_date)
    for tid, t in f._lt.items():
        if not isinstance(t, dict):
            continue
        key = t.get("key") or ""
        if not key.startswith(("k_", "e_", "h_")):
            continue
        heir0 = (t.get("heir") or [None])[0]
        if not isinstance(heir0, int):
            continue
        hrec = chars.get(str(heir0)) or {}
        hfam = hrec.get("family") or {}
        rf = (hfam.get("real_father") or [None])[0]
        mother = (hfam.get("mother") or [None])[0]
        if not (rf == pid or (mother in lovers)):
            continue
        if not in_span(hrec.get("birth")):
            continue
        if as_of_gap:
            # decade biography with the melt later than as_of: the holder at as_of must match the
            # current holder, so later succession changes do not leak into an early decade
            hist = t.get("history") or {}
            holder_now = t.get("holder")
            holder_at = None
            aok = cl.date_key(f.as_of)
            for hd in sorted(hist, key=cl.date_key):
                if cl.date_key(hd) <= aok:
                    holder_at = hist[hd]
            if holder_at != holder_now:
                continue
        hname = f.name_or(heir0)
        if not hname:
            continue
        # no birth-date parenthetical here either (the kinship label disambiguates); a same-mother
        # sibling murdered by the player is noted with the birth-order word
        dead_sib = ""
        for s in (hfam.get("siblings") or []):
            srec = chars.get(str(s)) or {}
            if (srec.get("death") or {}).get("killer") == pid:
                sname = f.name_or(s)
                sdate = (srec.get("death") or {}).get("date")
                if sname:
                    sb = srec.get("birth")
                    older = True
                    if sb and hrec.get("birth"):
                        older = cl.date_key(sb) < cl.date_key(hrec.get("birth"))
                    sfemale = is_female(s)
                    sw = "长姐" if (older and sfemale) else \
                          "长兄" if older else ("妹" if sfemale else "弟")
                    dead_sib = (f"；其同母{sw}{sname}已于{f.date(sdate)}"
                                + f.death_clause(s, date=sdate))
                break
        sex = "女" if is_female(heir0) else "子"
        # for a vacant throne the succession sentence uses the throne word ("天皇第一继承人"),
        # not the game's mechanical string ("高御座府第一继承人"): the throne is not a place
        tname = f.throne_word(tid) or f.title(tid)
        if rf == pid:
            mname = f.name_or(mother) if mother in lovers else ""
            who = (f"{pname}与{mname}之{sex}" if mname
                   else f"{pname}之{sex}")
        else:
            who = f"{pname}情人之{sex}"
        chains.append(("血脉登基",
            f"{hname}为{tname}第一继承人，实为{who}{dead_sib}。", True))

    return chains


# Half-sibling union: the player's legitimate child married to (or lover of) the player's
# illegitimate child, or the two having children together. Those facts sat in three separate
# places, so the model could not see that a daughter had married her own illegitimate brother.
_KIN_MARRIAGE_KEYS = ("primary_spouse", "spouse", "former_spouses",
                      "concubine", "former_concubines", "ever_spouses")


def _kin_blood_links(f):
    """[(module name, sentence, revealing)] -- unions and children linking the player's children
    to their illegitimate half-siblings.

    All from cached `family` fields: S = the player's children (family.child); B = children whose
    real father or real mother is the player and who are not in S. Triggers: S and B are spouses
    (or S's spouse is B), or S and B share a child. The date is the earliest marriage/affair date
    on either side (none is written if none is found); truncated at as_of."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    chars = cache.get("characters") or {}
    prec = chars.get(str(pid)) or {}
    pfam = prec.get("family") or {}
    pname = f.name_or(pid)
    ao = cl.date_key(f.as_of) if f.as_of else None

    def in_span(d):
        return ao is None or not d or cl.date_key(d) <= ao

    def fam_of(cid):
        return (chars.get(str(cid)) or {}).get("family") or {}

    def is_female(cid):
        return f._is_female(cid)

    legal = {int(x) for x in (pfam.get("child") or []) if isinstance(x, int)}
    # the player's illegitimate children (real father/mother = player, not in the legal set)
    bastards = set()
    for cid, rec in chars.items():
        try:
            icid = int(cid)
        except (TypeError, ValueError):
            continue
        if icid == pid or icid in legal:
            continue
        cf = rec.get("family") or {}
        rf = (cf.get("real_father") or [None])[0]
        rm = (cf.get("real_mother") or [None])[0]
        if rf == pid or rm == pid:
            bastards.add(icid)
    if not legal or not bastards:
        return []
    out = []
    seen = set()
    for b in sorted(bastards):
        bfam = fam_of(b)
        # the spouse set and the lover set are kept apart: "结为夫妇" only for a real marriage,
        # everyone else "私通", otherwise a bastard child's lover is called a spouse
        bsp = {x for x in (bfam.get("primary_spouse") or [])
               + (bfam.get("spouse") or [])
               + (bfam.get("former_spouses") or []) if isinstance(x, int)}
        blov = {x for x in (bfam.get("lover") or []) if isinstance(x, int)}
        for m in (chars.get(str(b)) or {}).get("memories") or []:
            if str(m.get("type") or "") in ("became_lovers", "had_sex") \
                    or str(m.get("type") or "").startswith(_SEX_MEM_PREFIX):
                for v in (m.get("participants") or {}).values():
                    if isinstance(v, int) and v != b:
                        blov.add(v)
        bkids = {x for x in (bfam.get("child") or []) if isinstance(x, int)}
        for s in sorted(legal):
            if s == b:
                continue
            sfam = fam_of(s)
            ssp = {x for x in (sfam.get("primary_spouse") or [])
                   + (sfam.get("spouse") or [])
                   + (sfam.get("former_spouses") or []) if isinstance(x, int)}
            skids = {x for x in (sfam.get("child") or []) if isinstance(x, int)}
            pair = tuple(sorted((b, s)))
            married = (b in ssp) or (s in bsp)
            if not married and b not in blov and s not in blov:
                continue
            # relation start date: the marriage memory or an affair memory, whichever is
            # earliest
            date = ""
            for m in (chars.get(str(s)) or {}).get("memories") or []:
                parts = m.get("participants") or {}
                if b not in [v for v in parts.values() if isinstance(v, int)]:
                    continue
                if (m.get("type") or "") not in (
                        "married", "became_lovers", "had_sex") \
                        and not str(m.get("type") or "").startswith(_SEX_MEM_PREFIX):
                    continue
                d = str(m.get("creation_date") or "")
                if d and (not date or cl.date_key(d) < cl.date_key(date)):
                    date = d
            if not in_span(date):
                continue
            if pair in seen:
                continue
            seen.add(pair)
            sn = f.person_label(s, date=f.as_of, style="brief") or f.name_or(s)
            bn = f.person_label(b, date=f.as_of, style="brief") or f.name_or(b)
            if not sn or not bn:
                continue
            sw = "女" if is_female(s) else "子"
            bw = "女" if is_female(b) else "子"
            mother = (bfam.get("mother") or [None])[0]
            mn = ""
            if isinstance(mother, int) and mother != pid:
                mn = f.person_label(mother, date=f.as_of, style="brief") or ""
            whose = f"{pname}与{mn}之{bw}" if mn else f"{pname}之{bw}"
            date_txt = f"{f.date(date)}，" if date else ""
            rel = "结为夫妇" if married else "私通相恋"
            line = (f"{date_txt}{pname}之{sw}{sn}与{bn}{rel}；"
                    f"{bn}实为{whose}，与{sn}为同父异母兄妹。")
            if married and (bkids & skids):
                kid = sorted(bkids & skids)[0]
                kn = f.person_label(kid, date=f.as_of, style="brief") or f.name_or(kid)
                if kn:
                    line = line.rstrip("。") + f"，二人生有{kn}。"
            out.append(("同父异母联姻", line, True))
    return out


def _kill_family(f, cid):
    """The killed character's family dict, taken from the cache."""
    return ((f.cache.get("characters") or {}).get(str(cid)) or {}).get("family") or {}


def _kill_kin_ids(f, cid, key):
    """Ids in the killed character's family[key] (father/mother/siblings), as ints."""
    out = set()
    for x in (_kill_family(f, cid).get(key) or []):
        try:
            out.add(int(x))
        except (TypeError, ValueError):
            continue
    return out


def _kill_kin_note(f, members):
    """Kinship note for a merged group: "俱为<parent>之子女" or "同胞兄弟姐妹"."""
    def _common(key):
        sets = [_kill_kin_ids(f, m.get("id"), key) for m in members]
        sets = [s for s in sets if s]
        if not sets:
            return set()
        return set.intersection(*sets)

    for key in ("father", "mother"):
        ids = _common(key)
        if ids:
            pid = sorted(ids)[0]
            nm = f.kin_label(pid) or f.name_with_regnal(pid)
            if nm:
                return f"俱为{nm}之子女"
    return "同胞兄弟姐妹"


def _group_killed_by_kin(entries, f):
    """Merge blood kin who died on the same day into one biography entry.

    Kin test: shared father, shared mother, or one in the other's siblings. Each same-day group
    keeps only its first entry, carrying group=[other members...] plus kin_note; the members are
    not listed separately, so the 《刺客列传》 slice works per group and never splits siblings."""
    by_date = {}
    for e in entries:
        by_date.setdefault(e.get("death_date"), []).append(e)
    out = []
    for d, group in by_date.items():
        if len(group) < 2 or d == "9999.9.9":
            out.extend(group)
            continue
        n = len(group)
        parent = list(range(n))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        for i in range(n):
            for j in range(i + 1, n):
                a, b = group[i], group[j]
                kin = bool(_kill_kin_ids(f, a.get("id"), "father")
                           & _kill_kin_ids(f, b.get("id"), "father")) \
                    or bool(_kill_kin_ids(f, a.get("id"), "mother")
                            & _kill_kin_ids(f, b.get("id"), "mother")) \
                    or b.get("id") in _kill_kin_ids(f, a.get("id"), "siblings") \
                    or a.get("id") in _kill_kin_ids(f, b.get("id"), "siblings")
                if kin:
                    ra, rb = find(i), find(j)
                    if ra != rb:
                        parent[rb] = ra
        comps = {}
        for i in range(n):
            comps.setdefault(find(i), []).append(i)
        for _root, idxs in sorted(comps.items()):
            members = [group[i] for i in idxs]
            if len(members) < 2:
                out.extend(members)
                continue
            members.sort(key=lambda e: e.get("death_date") or "")
            head = members[0]
            head["group"] = members[1:]
            head["kin_note"] = _kill_kin_note(f, members)
            out.append(head)
    out.sort(key=lambda e: cl.date_key(e["death_date"]))
    return out


def _killed_by_player(f):
    """People killed by the player, merged and deduplicated from six sources:
    1) the player's cached kills (alive_data.kills ∪ dead_data.kills, accumulated over
       years); 2) player_death.kills; 3) the player's successful_murder memory victims;
    4) every cached death record whose killer is the player; 5) dead_data.killer in the
    newest melt, for victims absent from the cache; 6) people who died imprisoned by the
    player. Returns entry dicts sorted by death date."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    killed = set()
    # 1) cached kills (accumulated across years: alive_data.kills ∪ dead_data.kills)
    prec = (cache.get("characters") or {}).get(str(pid)) or {}
    for k in prec.get("kills") or []:
        killed.add(int(k))
    # 2) player_death.kills (already written into dead_data.kills when the death was found)
    dd = cache.get("player_death") or {}
    for k in dd.get("kills") or []:
        killed.add(int(k))
    # 3) successful_murder memory victims of the player
    for mem in prec.get("memories") or []:
        if mem.get("type") == "successful_murder":
            v = (mem.get("participants") or {}).get("victim")
            if isinstance(v, int):
                killed.add(v)
    # 4) every cached death record whose killer is the player
    for cid, rec in (cache.get("characters") or {}).items():
        if int(cid) == pid:
            continue
        d = rec.get("death") or {}
        if d.get("killer") == pid:
            killed.add(int(cid))
    # 5) reverse lookup in the newest melt (dead_data.killer == the player)
    for cid, c in f._chars.items():
        if not isinstance(c, dict) or int(cid) == pid:
            continue
        d = (c.get("dead_data") or {}).get("killer")
        if d is not None and int(d) == pid:
            killed.add(int(cid))
    # 6) people who died imprisoned by the player (jail deaths, which the game does not
    # necessarily attribute to the player as killer) -- only those imprisoned at least a
    # year at death (imprison_duration has a value), the same test the death clause uses
    for mem in prec.get("memories") or []:
        if mem.get("type") != "imprisoned_other":
            continue
        v = (mem.get("participants") or {}).get("imprisoned")
        if not isinstance(v, int) or v == pid:
            continue
        vrec = (f.cache.get("characters") or {}).get(str(v)) or {}
        vd = (vrec.get("death") or {}).get("date")
        if vd and f.imprison_duration(v, date=vd):
            killed.add(v)
    # per victim: profile + death sentence + recovered memory events (the pre-death
    # snapshot is already merged in by the cache)
    out = []
    for cid in killed:
        prof = (f.cache.get("characters") or {}).get(str(cid)) or {}
        # victim missing from the cache: build the death sentence from the newest melt's
        # dead_data
        # the killer's appellation shortens to "其" -- in 《刺客列传》 the killer is always
        # the player
        ds = _death_sentence(f, cid, killer_pronoun=True, insider=True)
        if not ds:
            mc = f._chars.get(str(cid)) or {}
            mdd = (mc or {}).get("dead_data") or {}
            if mdd and mdd.get("date"):
                clause = f.death_clause(cid, date=mdd.get("date"),
                                        reason=mdd.get("reason"),
                                        killer=mdd.get("killer"), imprison=True,
                                        insider=True)
                # same convention as the main path: shorten to "其" when the killer is the
                # player
                # appellation comes from the same source as death_clause (event_name)
                kk = mdd.get("killer")
                if kk is not None:
                    klabel = f.event_name(kk, date=f.as_of)
                    if klabel and klabel in clause:
                        clause = clause.replace(klabel, "其")
                ds = f"{f.name_or(cid)}死于{f.date(mdd.get('date'))}，{clause}。"
                # the melt fallback also appends the victim's location (barony; omitted if
                # none)
                if mdd.get("killer") == pid:
                    vp = f.victim_place(cid)
                    if vp:
                        ds = ds.rstrip("。") + f"，死于{vp}。"
        _ddate = (prof.get("death") or {}).get("date")
        entry = {
            "id": cid,
            # the dead's name carries a regnal number (computed from the primary title held
            # at the death date)
            "name": f.name_with_regnal(cid, date=(prof.get("death") or {}).get("date")),
            "birth": f.date(prof.get("birth")),
            "death": ds or "（死因不详）",
            "death_date": (prof.get("death") or {}).get("date") or "9999.9.9",
            # the victim's latest knowable barony before death ('' if none, the caller then
            # omits the note)
            "victim_place": f.victim_place(cid),
            # whether the killing was publicly known (killer_known flag or a death reason
            # that is public by itself); once the snapshot is on disk, `verify_fast` can
            # check the public account without the melt
            "killer_public": f.killer_is_public(cid),
            # uprising leader info (rose in province X / rallied N provinces / rebelled
            # against X) -- the real place held by the uprising title, filling the victim's
            # "no land" gap
            "uprising": f.uprising_info(cid),
            "uprising_line": f.uprising_line(cid),
            "house": _dynasty_display(prof.get("dynasty_name"),
                                      prof.get("house_name")),
            "house_branch": _house_branch(prof.get("dynasty_name"),
                                          prof.get("house_name")),
            # house appellation assembled by culture and name order
            "house_label": house_label(prof.get("dynasty_name"),
                                       prof.get("house_name"),
                                       f.name_order(cid), None),
            # the dead's office (including "XX家族乡绅" for house heads); with no landed title
            # fall back to a prince/princess title computed from the father's title at the
            # death date, so a titleless victim is not taken for a commoner; the office's
            # realm name is anchored to the death date rather than to as_of
            "office": f.official_title(
                cid, date=(prof.get("death") or {}).get("date"))
            or f.prince_title(cid, date=(prof.get("death") or {}).get("date")),
            "culture": f.culture(cid),
            "faith": f.faith(cid),
            "traits": "、".join(f.traits(cid)),
            "events": [],
            # memory types parallel to `events` entry by entry -- 《刺客列传》 filters its
            # romance lines by type, not by surface keywords: after the romance sentence
            # became the game's own cause line ("…相爱了"), keyword filtering matched
            # nothing and dropped the whole line
            "event_types": [],
            "role": "",   # relationship to the protagonist (child/friend/enemy...) is inferred by biography.py from memories
        }
        # uniform appellation: the dead's label (office/title + name) is assembled once here,
        # so biography._assassin_kill_lines and the opening roster no longer build it
        entry["label"] = (f.person_label(cid, date=_ddate, style="brief")
                          or entry["name"])
        for mem in prof.get("memories") or []:
            s = _mem_sentence(f, cid, mem)
            if not s:
                continue
            # a lovers memory is held by both parties (their participants point at each
            # other): when both are in this roster keep only one side (the smaller id), so the
            # same event does not produce two mirrored lines in 《刺客列传》. The timeline side
            # is handled by `_drop_mirror_pairs` (see `_MIRROR_TYPE_PAIRS`).
            if str(mem.get("type") or "") == "became_lovers":
                _oth = (mem.get("participants") or {}).get("new_relation")
                if isinstance(_oth, int) and _oth in killed and _oth < cid:
                    continue
            # fact date (title gains and losses use the title history event date)
            entry["events"].append(
                f"{f.date(f.mem_date(cid, mem))}，{s}")
            entry["event_types"].append(str(mem.get("type") or ""))
        _pairs = sorted(zip(entry["events"], entry["event_types"]))
        entry["events"] = [p[0] for p in _pairs]
        entry["event_types"] = [p[1] for p in _pairs]
        out.append(entry)
    out.sort(key=lambda e: cl.date_key(e["death_date"]))
    # With many victims, lowborn ones (no house, not family/friend/enemy) are dropped to
    # keep the model's attention. as_of truncation: a decade biography covers only people
    # who died no later than that point, and an unknown death date (9999.9.9) counts as not
    # later than as_of. Decade window: only deaths inside this decade, so an early death
    # does not reappear in a later decade.
    if f.as_of:
        ao = cl.date_key(f.as_of)
        out = [e for e in out
               if e["death_date"] == "9999.9.9" or cl.date_key(e["death_date"]) <= ao]
        if f.decade:
            lo = _decade_lower_bound(f)
            if lo:
                lok = cl.date_key(lo)
                out = [e for e in out
                       if e["death_date"] == "9999.9.9"
                       or cl.date_key(e["death_date"]) >= lok]
    if len(out) > KILL_LOWBORN_THRESHOLD:
        keep = _kill_keep_ids(cache, pid)
        out = [e for e in out if e["house"] or e["id"] in keep]
    # Merge kin who died on the same day; done after the window and lowborn filters, and the
    # members are no longer listed separately from here on (the slice works per group).
    return _group_killed_by_kin(out, f)


def _imperial_daughters_sisters(f, spouses):
    """Wives/concubines holding an imperial princess title, or a daughter or sister of a Chinese
    emperor: either she has held an h_/e_ imperial title, or her father or a sibling
    (family.father/siblings) held h_china or a Chinese-culture empire."""
    pid = f.cache.get("player_id")
    out = []
    # Chinese emperors: every holder of h_china (or a Chinese-culture empire) in realm_history
    china_emperors = set()
    for h in f.cache.get("realm_history") or []:
        for tid, holder in (h.get("holders") or {}).items():
            if holder is None:
                continue
            key = (f._lt.get(str(tid)) or {}).get("key") or ""
            if key == "h_china" or key in ("e_zhongyuan", "e_yongliang",
                                           "e_jingyang", "e_liangyi", "e_lingnan"):
                china_emperors.add(int(holder))
    for sid in spouses:
        rec = (f.cache.get("characters") or {}).get(str(sid)) or {}
        name = f.name_or(sid)
        if not name:
            continue
        reasons = []
        # 1) she herself holds a princess/queen title (imperial tier)
        is_emp, etitle = f.emperor_of(sid)
        if is_emp:
            reasons.append(f"自任{etitle}")
        # 2) her father or a brother is a Chinese emperor
        fam = rec.get("family") or {}
        rel = []
        for fid in (fam.get("father") or []):
            if int(fid) in china_emperors:
                rel.append(f"父{f.kin_label(fid)}")
        for bid in (fam.get("siblings") or []):
            if int(bid) in china_emperors:
                rel.append(f"兄{f.kin_label(bid)}")
        if rel:
            reasons.extend(rel)
        if reasons:
            out.append({"id": sid, "name": name, "reasons": reasons})
    return out


def _wandering_trail(f):
    """Player location history (cache.player_locations) rendered as Chinese trail lines."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    out = []
    hist = cache.get("player_locations") or []
    # as_of truncation: a decade biography lists only movement up to that point
    if f.as_of:
        hist = [loc for loc in hist
                if not loc.get("date") or cl.date_key(loc.get("date")) <= cl.date_key(f.as_of)]
    for i, loc in enumerate(hist):
        prov = loc.get("province")
        county = f.county_at_province(prov)
        if county is None:
            continue
        cname = f.title(county)
        holder = ""
        chain = f.liege_chain(county) if county else []
        if chain:
            h = chain[0][1]
            if h is not None:
                holder = f.name_or(h, "")
        bits = [f"{f.date(loc.get('date'))}驻{cname}"]
        if holder:
            bits.append(f"{holder}执掌")
        top = chain[-1] if chain else None
        if top and top[1] is not None:
            bits.append(f"最高领主{f.name_or(top[1])}")
        out.append("，".join(bits) + "。")
    return out


def _cn_date_key(s):
    """Leading Chinese date of a line ("867年1月1日任…") -> date_key; None if unparsable."""
    m = re.match(r"^(\d+)年(\d+)月(\d+)日", s or "")
    if not m:
        return None
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)))


def _protagonist_stations(f):
    """Adventurer trail: camp stages and stations during the landless-adventurer period only.

    Stations while settled or holding a family estate carry no meaning (least of all the travel
    landings in player_locations) and title stages already appear in the 【人物档案】 tenure
    lines, so only "驻X" lines and camp stage lines inside a camp-holding interval are kept.
    Returns [] when there is no camp period, suppressing the whole section; truncated at as_of."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    camps = f.camp_intervals(pid)
    if not camps:
        return []
    items = []  # (date_key, line text)
    # 1) camp stage lines (the game's camp-purpose wording, same source as held_titles)
    for tid, ivs in (f._hold_intervals(pid) or {}).items():
        if f.title_kind(tid) != "camp":
            continue
        for iv in ivs:
            g = iv[0] if iv else None
            if not g:
                continue
            if f.as_of and cl.date_key(g) > cl.date_key(f.as_of):
                continue
            end = (iv[1] if len(iv) > 1 else None) or f.as_of \
                or cache.get("last_date")
            # the holder line uses the camp's own name, without the "营地" tier word, matching
            # the tenure stage lines
            nm = f._name_at_date(tid, g) or f.title_base_name(tid) or ""
            w = f._camp_holder_word(pid, g)
            base = f"{nm}{w}" if nm and w else (f"{nm}之主" if nm else "")
            if base:
                items.append((cl.date_key(g),
                              f"{f.date(g)}任无地冒险者营地之{base}"))
    # 2) station trail: only locations inside a camp interval (travel landings never count)
    hist = cache.get("player_locations") or []
    if f.as_of:
        aok = cl.date_key(f.as_of)
        hist = [loc for loc in hist
                if not loc.get("date") or cl.date_key(loc["date"]) <= aok]
    seen = set()
    for loc in hist:
        if not loc.get("date") or not f.in_camp_period(loc["date"], pid):
            continue
        county = f.county_at_province(loc.get("province"))
        if county is None:
            continue
        cname = f.title(county)
        if not cname:
            continue
        key = (loc.get("date"), cname)
        if key in seen:
            continue
        seen.add(key)
        items.append((cl.date_key(loc["date"]), f"{f.date(loc['date'])}驻{cname}"))
    items.sort(key=lambda x: x[0])
    # dedupe by line text (a same-day camp stage and station line are both kept; only
    # identical lines are dropped)
    out = []
    seen_line = set()
    for dk, ln in items:
        if ln in seen_line:
            continue
        seen_line.add(ln)
        out.append(ln)
    return out[:40]


def _nomad_stations(f):
    """Nomad trail: where the great camp stood during the nomadic period.

    Yurt titles are `landless: true` and never enter the tenure list (`_primary_group` excludes
    them), so this is handled here: the camp founding line is the yurt title's (x_c_nomad_*)
    acquisition date plus the game display name (`nomad_title_name` = dynasty name +
    "游牧营地"), and the "驻X" lines are the yearly location inside the yurt-holding interval
    (this save's player only; travel landings never count). Returns [] when there is no yurt
    period, suppressing the whole section; truncated at as_of."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    camps = f.camp_intervals(pid, kind="nomad")
    if not camps:
        return []
    items = []
    for tid, ivs in (f._hold_intervals(pid) or {}).items():
        if f.title_kind(tid) != "nomad":
            continue
        for iv in ivs:
            g = iv[0] if iv else None
            if not g:
                continue
            if f.as_of and cl.date_key(g) > cl.date_key(f.as_of):
                continue
            nm = f._site_name(tid, cid=pid) or f.title_base_name(tid) or ""
            if nm:
                items.append((cl.date_key(g), f"{f.date(g)}立{nm}"))
    hist = cache.get("player_locations") or []
    if f.as_of:
        aok = cl.date_key(f.as_of)
        hist = [loc for loc in hist
                if not loc.get("date") or cl.date_key(loc["date"]) <= aok]
    seen = set()
    for loc in hist:
        if not loc.get("date") or not f.in_camp_period(loc["date"], pid, kind="nomad"):
            continue
        county = f.county_at_province(loc.get("province"))
        if county is None:
            continue
        # the "驻X" name uses the site name: a county he has held carries the same name as its
        # own tenure line (the dynamic name taken before acquisition), while a county merely
        # passed through takes that year's snapshot name -- a sticky name from the last
        # snapshot would misdate the line
        cname = f.title(county, date=loc.get("date"), site=True, site_cid=pid)
        if not cname:
            continue
        key = (loc.get("date"), cname)
        if key in seen:
            continue
        seen.add(key)
        items.append((cl.date_key(loc["date"]), f"{f.date(loc['date'])}驻{cname}"))
    items.sort(key=lambda x: x[0])
    out = []
    seen_line = set()
    for _dk, ln in items:
        if ln in seen_line:
            continue
        seen_line.add(ln)
        out.append(ln)
    return out[:40]


_PLAGUE_INTENSITY_ZH = {"minor": "轻疫", "major": "重疫", "apocalyptic": "毁灭之疫"}


def _plague_facts(f):
    """Plague colour: the save's epidemics with their game-generated dynamic names and spread.
    Only an epidemic touching the player's domain or county of residence is written, plus one
    the player or a family member caught; distant plagues are never written. Names come from the
    save's `name` field, falling back to the disease localization (trait_smallpox = 天花)."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return {}
    db = (f.melt.get("epidemics") or {}).get("database") or {}
    if not isinstance(db, dict) or not db:
        return {}
    rec = (cache.get("characters") or {}).get(str(pid)) or {}
    ld = rec.get("landed") or {}
    # provinces relevant to the player: each domain title's capital, the estate/yurt domicile,
    # and the current county
    mine = set()
    lt = f._lt
    for t in (ld.get("domain") or []):
        cap = (lt.get(str(t)) or {}).get("capital")
        if isinstance(cap, int):
            mine.add(cap)
    dom_prov = ((rec.get("landed") or {}).get("domicile_province")
                or ld.get("domicile_province"))
    if isinstance(dom_prov, int):
        mine.add(dom_prov)
    loc_prov = f.character_location_province(pid)
    if isinstance(loc_prov, int):
        mine.add(loc_prov)
    if not mine:
        return {}
    fam = rec.get("family") or {}
    kin = [pid]
    for k in ("primary_spouse", "spouse", "former_spouses", "concubine",
              "former_concubines", "child", "father", "mother", "siblings"):
        for x in fam.get(k) or []:
            if isinstance(x, int) and x not in kin:
                kin.append(x)
    lines = []
    for eid, e in db.items():
        if not isinstance(e, dict):
            continue
        typ = e.get("type") or ""
        # the comma in the game-rendered "title, name" plague name is stripped here too (this
        # function reads the melt directly and bypasses `_disease_dynamic_name`)
        name = _strip_title_comma(str(e.get("name") or ""))
        disease = _trait_name(f.table, typ) if typ else ""
        label = name or disease
        if not label:
            continue
        created = str(e.get("creation_date") or "")
        if f.as_of and created and cl.date_key(created) > cl.date_key(f.as_of):
            continue
        known = cache.get("epidemics") or {}
        hist = known.get(str(eid)) or {}
        if hist.get("lost_at") and f.as_of \
                and cl.date_key(hist["lost_at"]) <= cl.date_key(f.as_of):
            continue            # the epidemic has subsided
        where = disease if (disease and disease != name) else ""
        intensity = _PLAGUE_INTENSITY_ZH.get(str(e.get("intensity") or ""), "")
        # ① whether the player or a family member caught it (the disease trait shares the
        # epidemic's type name)
        hit_kin = []
        if typ:
            for cid in kin:
                if f._has_trait_at(cid, typ):
                    hit_kin.append(f.kin_label(cid) if cid != pid
                                   else (f.person_label(pid, date=f.as_of, style="brief")
                                         or f.name_or(pid)))
        # ② whether the player's domain or county is among its infections
        inf = {int(x) for x in (e.get("infections") or {}) if str(x).isdigit()}
        hit_prov = sorted(mine & inf)
        if not hit_kin and not hit_prov:
            continue
        head = f"{f.date(created)}，{label}"
        if where:
            # no parenthetical: "…，赤烈咳，属肺痨，轻疫"
            head += f"，属{where}"
        if intensity:
            head += f"，{intensity}"
        bits = [head]
        if hit_prov:
            ctid = f.county_at_province(hit_prov[0])
            cname = f.title(ctid) if ctid is not None else ""
            bits.append(f"疫及主角封地{cname}" if cname else "疫及主角所居之地")
            n = e.get("num_infected_provinces") or len(inf)
            if n:
                bits.append(f"蔓及{n}州")
        if hit_kin:
            bits.append("、".join(hit_kin) + "染此疫")
        lines.append("，".join(bits) + "。")
    if not lines:
        return {}
    return {"lines": lines[:4]}


def _court_luminaries(f):
    """Court luminaries: for an administrative-government player, the notable court figures
    among the player's relations who have political memories or high titles. Passers-by are
    dropped and the list is capped at 60 names so the prompt does not balloon."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    related = _related_ids(f)
    names = []
    seen = set()
    for cid, rec in (cache.get("characters") or {}).items():
        if len(names) >= 60:
            break
        if int(cid) == pid or int(cid) not in related:
            continue
        if not (rec.get("name_full") or rec.get("name_zh")):
            continue
        has_pol = any(m["type"] in POLITICAL_TYPES_KEYS
                      for m in rec.get("memories") or [])
        if has_pol or f.held_titles(int(cid)):
            nm = f.name_or(int(cid))
            if nm and nm not in seen:
                seen.add(nm)
                names.append(nm)
    return names


def _genealogy(f):
    """Genealogy lines for the appendix: the player plus parents, spouses, concubines, children
    and siblings. The spouse label follows the player's sex, and `spouse` has `primary_spouse`
    subtracted, since CK3 lists the same wife in both fields."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    rec = (cache.get("characters") or {}).get(str(pid)) or {}
    fam = rec.get("family") or {}
    # the marriage latch is merged into the genealogy, from the same source as
    # `_protagonist_facts`
    fam = f.merge_spouse_latch(fam, f.as_of)
    fem = f._is_female(pid)
    lines = []
    pname = f.name_or(pid)
    lines.append(f"一世 {pname}，{f.date(rec.get('birth'))}生")
    spouses = [x for x in (fam.get("primary_spouse") or [])]
    side = [x for x in (fam.get("spouse") or []) if x not in set(spouses)]
    rows = [("father", "父"), ("mother", "母")]
    if fem:
        rows += [("primary_spouse_key", "正夫"), ("side_spouse_key", "侧夫")]
    else:
        rows += [("primary_spouse_key", "正妻"), ("side_spouse_key", "侧室")]
    rows += [("concubine", "妾" if not fem else "男宠"),
             ("former_concubines", "前妾" if not fem else "前男宠"),
             ("child", "子女"), ("siblings", "兄弟姊妹"),
             ("former_spouses", "前夫" if fem else "前妻")]
    # each person appears on one line only: the save also lists current spouses in
    # former_spouses (same source as `_protagonist_facts`)
    _used_mar = set(spouses) | set(side)
    for key, label in rows:
        if key == "primary_spouse_key":
            ids = spouses
        elif key == "side_spouse_key":
            ids = side
        elif key in ("concubine", "former_concubines", "former_spouses"):
            ids = [x for x in (fam.get(key) or []) if x not in _used_mar]
            _used_mar.update(ids)
        else:
            ids = fam.get(key) or []
        if not ids:
            continue
        bits = []
        for x in ids:
            n = f.kin_label(x)
            if not n:
                continue
            # spouse rows also note a matrilineal marriage (uxorilocal) and which parent the
            # children belong to
            if key in ("primary_spouse_key", "side_spouse_key"):
                n += f.marriage_lineality_note(pid, x, before=f.as_of)
            bits.append(n)
        if bits:
            lines.append(f"　{label}：{'、'.join(bits)}")
    return lines


def _secrets_facts(f):
    """Secrets of the player, family and close servants: the secrets themselves, who knows them,
    leverage held, and secrets first recorded in this decade.

    Returns keys {held, held_murder, held_unrevealed, kinsmen, known, events, any}, or {} when
    nothing relevant exists (then no 《阴私录》 is generated). Several secrets of one holder share
    a line so the holder is named once, knowers join the same sentence, a first-seen year equal
    to the knowing year is written once, and leverage is grouped by whom it is held over."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return {}
    cut = f._secret_cut()
    mine = f.secrets_owned_by(pid, cut)
    held, murder = [], []
    for rec in mine:
        (murder if rec.get("type") in SECRET_MURDER_TYPES else held).append(rec)
    out = {}
    # the player's appellation matches the whole text: `event_name` gives the name only, while
    # the title is established once in 《传主档案》; `style="brief"` repeated the full title on
    # every line
    plabel = f.event_name(pid, f.as_of) or f.name_or(pid)
    if held:
        # the player's appellation matches the whole text (timeline and profile use event_name)
        lines = f.secret_lines(held, owner_label=plabel, self_cid=pid, owner=pid)
        revealed = any(f.secret_knowers(r, self_cid=pid) for r in held)
        if lines:
            out["held"] = lines
        if not revealed:
            out["held_unrevealed"] = True      # no one knows it yet
    if murder:
        out["held_murder"] = len(murder)
        names = []
        for rec in murder:
            t = rec.get("target")
            nm = f.person_label(t, date=f.as_of, style="brief") if isinstance(t, int) else ""
            if nm:
                names.append(nm)
        if names:
            out["held_murder_names"] = names[:6]
    # secrets of family and court retainers (kin plus court_positions employees)
    prec = (cache.get("characters") or {}).get(str(pid)) or {}
    fam = prec.get("family") or {}
    kin = []
    for key in ("primary_spouse", "spouse", "former_spouses", "concubine",
                "former_concubines", "child", "father", "mother", "siblings"):
        for x in fam.get(key) or []:
            if isinstance(x, int) and x != pid:
                kin.append(x)
    for h in cache.get("court_positions") or []:
        for p in h.get("positions") or []:
            e = p.get("employee")
            if isinstance(e, int) and e != pid:
                kin.append(e)
    kin_lines = []
    for kid in dict.fromkeys(kin):
        recs = f.secrets_owned_by(kid, cut)
        if recs:
            # several secrets of one family member share a single line
            kin_lines.extend(f.secret_lines(recs, owner_label=f.kin_label(kid),
                                            self_cid=pid, owner=kid))
    if kin_lines:
        out["kinsmen"] = kin_lines[:10]
    # leverage the player holds over others (grouped by the holder, the player named once)
    # Every item must carry its year: without `_first_seen_note` the leverage lines had no
    # date while neighbouring lines did, and the prompt asked for the year of record, leaving
    # the model to hedge. The year is supplied here instead.
    groups = {}
    for rec in f.secrets_known_by(pid, cut):
        o = rec.get("owner")
        if isinstance(o, int):
            groups.setdefault(o, []).append(rec)
    known = []
    for oid, recs in groups.items():
        owner = f.person_label(oid, date=f.as_of, style="brief")
        if not owner:
            continue
        topics = []
        for r in recs:
            t = f.secret_topic(r, self_cid=pid)
            if not t:
                continue
            note = f._first_seen_note(r)
            if note:
                # no parenthetical: the first-seen year follows the topic as its own clause
                t += f"，{note}"
            topics.append(t)
        if not topics:
            continue
        known.append(f"{plabel}握有{owner}的把柄：" + "；".join(topics) + "。")
    if known:
        out["known"] = known[:10]
    # secrets first seen inside this decade (the slice's time anchor); the final and living
    # biographies use the whole span
    lo = _decade_lower_bound(f)
    lok = cl.date_key(lo) if lo else None
    ck = cl.date_key(cut) if cut else None
    events = []
    for sid, rec in (cache.get("secrets_history") or {}).items():
        if not isinstance(rec, dict) or rec.get("first"):
            continue
        if rec.get("type") in SECRET_MURDER_TYPES:
            continue          # murder secrets are counted only; the narration is in 《刺客列传》
        fs = rec.get("first_seen")
        if not fs:
            continue
        dk = cl.date_key(fs)
        if ck is not None and dk > ck:
            continue
        if lok is not None and dk < lok:
            continue
        owner = rec.get("owner")
        if owner != pid and owner not in kin:
            continue
        # event lines use the same uniform appellation (player/family)
        olabel = plabel if owner == pid else f.kin_label(owner)
        s = f.secret_line(dict(rec, first=True), owner_label=olabel,
                          knowers=False, self_cid=pid, owner=owner)
        if s:
            # the event line's prefix already gives the date, so the sentence omits the year
            events.append(f"{f.date(fs)}，{s}")
    if events:
        out["events"] = sorted(set(events))[:12]
    # Hooks (the leverage dimension): those the player holds and those held over the player.
    # They are issued only with 《阴私录》 and never into 《本纪》, and are filtered by a whitelist
    # (see Facts._hook_kept).
    hl = f.hook_lines()
    if hl.get("held"):
        out["hooks_held"] = hl["held"]
    if hl.get("over"):
        out["hooks_over"] = hl["over"]
    # Enslavement (Carnalitas) is a block of its own: the relation never entered the cache, so
    # enslavement used to be read as a mere capture and release. It now comes straight from
    # cache["enslavements"], issued in two tiers, current and former, the former stating when
    # and why the person stopped being the player's slave.
    en = f.enslaved_lines()
    if en.get("lines"):
        out["enslaved"] = en["lines"]
    if en.get("former"):
        out["enslaved_former"] = en["former"]
    # Carnalitas event opinion (rape/enslavement/prostitution/former master-slave) carries its
    # own start_date, covering interactions that leave no memory, and corroborates the sexual
    # memories.
    cp = f.carnal_opinion_lines()
    if cp.get("lines"):
        out["carnal_opinions"] = cp["lines"]
    vl = f.carnal_victim_line()
    if vl:
        out["carnal_victim"] = [vl]
    # Sexual matters are used only inside 《列传·好友》 and 《列传·仇人》: their former
    # "强迫之事如下" fact block was withdrawn (`harm_lines` is now an empty implementation, so no
    # `harm` is issued here). Their carrier is the 【相关年表】 of those two pieces (the timeline
    # gate is in `_timeline`).
    hl = f.harm_lines()
    if hl:
        out["harm"] = hl
    # Venereal-disease transmission facts (the wording falls back to "染上" when there is no
    # source). The former outlet that could attach these to sexual matters is gone, leaving this
    # the only one.
    dl = f.std_lines()
    if dl:
        out["disease"] = dl
    out["any"] = bool(out.get("held") or out.get("kinsmen") or out.get("known")
                      or out.get("enslaved") or out.get("enslaved_former")
                      or out.get("carnal_opinions") or out.get("carnal_victim")
                      or out.get("harm") or out.get("disease") or f.hook_notable())
    return out


# ---------------------------------------------------------------------------
# Education memories the game records twice, a day or two apart
# ---------------------------------------------------------------------------
# `childhood_education_guardian` has one creation point in the game scripts,
# `wrap_up_education_effect` (`00_education_effects.txt:1933`, memory added at :1981-1986), but
# the 16th-birthday chain calls it twice: `coming_of_age.0001-.0005`'s `immediate` and
# `childhood_on_actions.txt:198`'s `delay = { days = 2 }` -> `childhood_education.0006`
# (`childhood_education_events.txt:249`). Both memories hang on the student with identical `vars`,
# differing only 0-2 days in `creation_date`, and the second entry's `guardian` is often
# re-parsed as the court tutor, so neither the cache's dedupe key (memory id, creation_date) nor
# `_timeline`'s (type, date, participants) catches it. Folding keeps the earlier entry, which
# holds the real guardian, only on an identical signature within 3 days.
_EDU_DUP_TYPES = ("childhood_education_guardian", "ward_education_completed")
_EDU_DUP_MAX_DAYS = 3          # measured gaps are 0/1/2 days; one day of slack


def _num_word(v):
    """Number -> clean decimal string: 12.0 -> '12', 12.5 -> '12.5'; '' if unconvertible.

    Vote counts (`nominations[].strength`) and papal-candidate prestige (fixed point times
    100000) are floats and would otherwise print with a trailing .0."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return ""
    if abs(f - round(f)) < 1e-6:
        return str(int(round(f)))
    return ("%g" % f)


def _day_ord(date):
    """CK3 date -> ordinal (year*360 + month*30 + day) for same-day and adjacent comparisons,
    shared by the education-memory dedupe and the war lookup (date tolerance ±2 days).
    None if the date is unusable."""
    y, m, d = cl.date_key(date)
    if y == 9999:
        return None
    return y * 360 + m * 30 + d


def _dedupe_education_memories(cache):
    """Fold an education recorded twice into one memory, in place.

    Criteria: ① same type (`_EDU_DUP_TYPES`); ② identical `vars` signature (the five items --
    place of education, court faith, culture and so on -- are item-by-item the same for one
    education); ③ day gap <= `_EDU_DUP_MAX_DAYS` (a same-day duplicate also keeps only the
    first one seen); ④ keep the earliest entry, which holds the real guardian. The comparison
    deliberately ignores `participants`, because the second entry's master is often the court
    tutor. Entries farther apart are two separate educations and both stay. Returns the number
    folded away, for logs and assertions."""
    dropped = 0
    for rec in (cache.get("characters") or {}).values():
        if not isinstance(rec, dict):
            continue
        mems = rec.get("memories")
        if not isinstance(mems, list) or not mems:
            continue

        def _sig(m):
            # The signature depends on which side holds the memory. Student side
            # (`childhood_education_guardian`): `vars` only (place, court faith, culture and so
            # on), never `participants`, because the second entry of one education is often
            # re-parsed to the court tutor and including it would miss every duplicate. Tutor side
            # (`ward_education_completed`): `participants` must be included, since its `ward` says
            # which student this is (one tutor may teach several in the same window with identical
            # `vars`); without it two students would be folded together.
            t = str(m.get("type") or "")
            parts = (json.dumps(m.get("participants") or {}, sort_keys=True)
                     if t == "ward_education_completed" else "")
            return (t, parts, json.dumps(m.get("vars") or [], sort_keys=True))

        best = {}
        for m in mems:
            if not isinstance(m, dict) or str(m.get("type") or "") not in _EDU_DUP_TYPES:
                continue
            sig = _sig(m)
            d = str(m.get("creation_date") or "")
            cur = best.get(sig)
            if cur is None or cl.date_key(d) < cl.date_key(cur):
                best[sig] = d
        if not best:
            continue
        out, kept_same_day = [], set()
        for m in mems:
            if isinstance(m, dict) and str(m.get("type") or "") in _EDU_DUP_TYPES:
                sig = _sig(m)
                d = str(m.get("creation_date") or "")
                base = best.get(sig)
                if base is not None:
                    o1, o2 = _day_ord(d), _day_ord(base)
                    if o1 is not None and o2 is not None and o1 == o2:
                        # degenerate same-day, same-signature pair: keep the first one seen
                        if sig in kept_same_day:
                            dropped += 1
                            continue
                        kept_same_day.add(sig)
                    elif o1 is not None and o2 is not None \
                            and 0 < o1 - o2 <= _EDU_DUP_MAX_DAYS:
                        dropped += 1
                        continue
            out.append(m)
        if len(out) != len(mems):
            rec["memories"] = out
    return dropped


def build_facts(cache, melt, names_path=None, as_of=None, decade=None,
                nickname_override=None, cfg=None, campaign=None):
    """Render the clean fact set (`melt` is a loaded dict).

    as_of: data cutoff -- offices, tenures, timeline and court state are truncated there.
    decade: decade index, restricting the timeline, overview, summary and 《刺客列传》 to
    (as_of-10y, as_of]; None means the whole span. nickname_override: {cid: nickname} era
    overrides for re-running one decade. cfg: config switches, read from config.json when
    omitted. campaign: {player_id: cache} for the whole campaign (kinship across protagonists)."""
    # fold the duplicated education memories before building Facts, so every reader (timeline,
    # per-person profile, biographies) benefits at once
    _edu_dup = _dedupe_education_memories(cache)
    if _edu_dup:
        llm.log(f"  [v95-4] 教育记忆隔日重复折掉 {_edu_dup} 条 "
                f"(childhood_education_guardian / ward_education_completed)")
    f = Facts(cache, melt, names_path, as_of=as_of, decade=decade,
              nickname_override=nickname_override, cfg=cfg, campaign=campaign)
    period = ""
    sources = cache.get("sources") or []
    if sources:
        period = f"{sources[0]} – {sources[-1]}"
    cpl, cpch = f.court_positions_lines()
    col, coch = f.court_office_lines()
    # Causes of death are rendered in Chinese (the outline must not leak the English key).
    # When as_of precedes the death date (a decade biography) the player counts as living, so
    # no death information leaks. Abdication (reign_end) takes precedence, and a death after
    # the abdication is never written here.
    re_end = cache.get("reign_end")
    if re_end and as_of \
            and cl.date_key(as_of) < cl.date_key(re_end.get("date") or "9999.9.9"):
        re_end = None
    pd = cache.get("player_death")
    if pd and re_end and cl.date_key(pd.get("date") or "0.0.0") \
            > cl.date_key(re_end.get("date") or "9999.9.9"):
        pd = None
    if pd and as_of and cl.date_key(as_of) < cl.date_key(pd.get("date") or "9999.9.9"):
        pd = None
    if pd:
        pd = dict(pd)
        pd["reason_zh"] = f.death_clause(
            cache.get("player_id"), date=pd.get("date"),
            reason=pd.get("reason"), killer=pd.get("killer"))
    if re_end:
        re_end = dict(re_end)
        re_end["reason_zh"] = f.reign_end_clause(cache.get("player_id"), re_end)
        re_end["word_zh"] = f.reign_end_word(re_end)
    # the 【家族】 line also takes the house's evolution as of this piece's cutoff, so the house
    # name in the shared prefix does not stay at its first-seen value after a rename
    _pid0 = cache.get("player_id")
    _pdn, _phn = f._house_names_at(_pid0, as_of) if _pid0 is not None else ("", "")
    # the 《历代记》 seat line and 《传主档案》 share one outlet, so the seat is not stated twice
    # in two ways
    f._protagonist_cache = _protagonist(f)
    # succession chain of each victim's seat: a top-level key used for verification and to
    # corroborate 《家室列传》's seat lines (`Facts.seat_note`); it is not rendered as a section
    # of its own
    _killed_list = _killed_by_player(f)
    _seat_succ = []
    for _k in _killed_list:
        try:
            _kid = int(_k.get("id"))
        except (TypeError, ValueError):
            continue
        for _row in f.seat_succession(_kid):
            _seat_succ.append(dict(_row, victim=_kid))
    facts = {
        # dynasty name (the surname under eastern name order) plus house/branch for flavour
        "house": _dynasty_display(_pdn or cache.get("dynasty_name"),
                                  _phn or cache.get("house_name")),
        "house_branch": _house_branch(_pdn or cache.get("dynasty_name"),
                                      _phn or cache.get("house_name")),
        # house appellation assembled by culture and name order (the shared-prefix 【家族】 line
        # and the title sentence share this source)
        "house_label": house_label(_pdn or cache.get("dynasty_name"),
                                   _phn or cache.get("house_name"),
                                   f.name_order(_pid0) if _pid0 is not None else None,
                                   ((f._culture_entry(_pid0, as_of) or {})
                                    .get("culture_template")
                                    if _pid0 is not None else None)),
        "player_name": cache.get("player_name"),
        "player_id": cache.get("player_id"),
        "period": period,
        "sources": sources,
        "protagonist": f._protagonist_cache,
        "timeline": _timeline(f),
        "characters": _character_profiles(f),
        # line text -> [[cid, appellation], ...]: a register of the names emitted inside event
        # and secret lines (the same object as f's, which later builders keep filling). The
        # section phase uses it to place kinship attributes at the exact position.
        "name_index": f.name_index,
        # basis for in-line attributes: the line's subject (who the sentence is about) and the
        # counterparty whose relation the sentence already states -- the same object as f's. The
        # section phase derives wording from the line's subject for third-party names, and
        # `verify_fast`'s [V63] recomputes it from the same data and keys as name_index.
        "line_owner": f.line_owner,
        "line_stated": f.line_stated,
        "realm": _realm_facts(f),
        "player_death": pd,
        # reign ended without death (tonsure, abdication, deposition) -- the player_death shape
        # with a rendered `reason_zh`; feeds `_is_final_bio_spec` and the 【传位】 line.
        "reign_end": re_end,
        "last_date": cache.get("last_date"),
        "as_of": as_of,
        "decade": decade,
        "bio_style": f.bio_style(),
        "killed": _killed_list,
        # for each victim, the chain of later holders of that seat (stopping at the first holder
        # not killed by the player; same-day successions are all included). See
        # `Facts.seat_succession`.
        "seat_succession": _seat_succ,
        # house-level purge summaries (shared by 《刺客列传》's opening and its chronicle)
        "family_purges": f.family_purge_summaries(cache.get("player_id")),
        "wandering": _wandering_trail(f),
        # secrets (player/family/close servants, knowers, leverage) -- the source of 《阴私录》
        "secrets": _secrets_facts(f),
        # plague colour (game dynamic names plus infection spread; only plagues touching the
        # player's domain or family)
        "plagues": _plague_facts(f),
        # chronology of the player's status and station changes (source of the shared-prefix
        # 【主角处境】)
        "protagonist_stations": _protagonist_stations(f),
        # the great camp's location over the nomadic period (source of the shared-prefix
        # 【游牧行踪】) -- yurts occupy no tenure slot, so "where the camp is" needs its own
        # block, shaped like 【冒险者行踪】
        "nomad_stations": _nomad_stations(f),
        "luminaries": _court_luminaries(f),
        "genealogy": _genealogy(f),
        # court/camp offices plus the house motto
        "court_positions": cpl,
        "court_position_changes": cpch,
        # court offices granted to the player (feeds the rise-and-fall section of 《朝局风云录》)
        "court_office": col,
        "court_office_changes": coch,
        "house_motto": f.motto(),
        # data source of 《家族恩怨录》 and 《宝物志》
        "house_feuds": f.house_feuds(),
        "family_artifacts": f.family_artifacts(),
        # protagonist chain (predecessor/successor) -- an outlet beyond the shared prefix and the
        # protagonist profile, letting biography state in 《本纪》's opening how the succession
        # connects
        "succession": f.succession_lines(),
        # ---- material for 《礼仪志》 / 《教会志》 (CK3 1.20 religion system) ----
        # Everything is rendered into Chinese fact sentences on the Facts side; empty when there
        # is no material, in which case biography omits the whole piece or block.
        "rite": f.rite_name(cache.get("player_id"), as_of),
        "rite_profile": f.rite_profile_lines(cache.get("player_id"), as_of),
        "rite_history": f.rite_history_lines(cache.get("player_id"), as_of),
        # Rite-level tenets are not itemized: they are a static pool that only loosely overlaps
        # the protagonist's own faith and is not his to decide. `forbidden_tenets` is likewise
        # gone, because secrets carry no doctrine key, leaving doctrine names and years
        # unreliable.
        "personal_tenets": f.personal_tenet_lines(cache.get("player_id"), as_of),
        "holy_orders": f.holy_order_lines(cache.get("player_id"), as_of),
        # changes to this rite's core tenets themselves (latched and diffed snapshot by
        # snapshot; the key is deliberately distinct from the removed `rite_tenets` allow/forbid
        # list)
        "rite_tenet_changes": f.rite_tenet_changes(cache.get("player_id"), as_of),
        # the college of cardinals and papal elections -- material for 《礼仪志》's third
        # section. Non-empty only in the current state and when this piece's protagonist has a
        # vassal in the college (an empty list means the section is omitted entirely).
        "papal_election": f.papal_election_lines(cache.get("player_id"), as_of),
        # the Facts instance (biography needs its methods, e.g. to render relation causes)
        "_facts": f,
    }
    # the decade's dramatic themes (top 5, ties for 5th all kept) -- used for module slicing and
    # the outline's preview
    facts["decade_modules"] = decade_module_top(facts.get("timeline") or [],
                                                facts.get("protagonist") or {})
    # Villainous relation chains (computed in code), their sentences merged into the player's
    # 【戏剧性事件】 and split in two tiers: `dramatic_facts` holds non-revealing chains
    # (assassination, kin-slaying, lover's spouse murdered) that public records may show, while
    # `dramatic_facts_private` holds revealing ones (托卵承嗣/血脉登基) issued only to
    # 《家室列传》/《阴私录》 -- public pieces never see the real father.
    vc = _villain_chains(f)
    # half-sibling union links (the player's children x the player's illegitimate children) --
    # private records only
    vc = list(vc) + _kin_blood_links(f)
    facts["villain_chains"] = vc
    if vc:
        dfa = facts["protagonist"].setdefault("dramatic_facts", [])
        dfp = facts["protagonist"].setdefault("dramatic_facts_private", [])
        for _m, s, _priv in vc:
            bucket = dfp if _priv else dfa
            if s not in bucket:
                bucket.append(s)
        dm = facts.get("decade_modules") or []
        for _m, _s, _priv in vc:
            if not any(x[0] == _m for x in dm):
                dm.append((_m, 3))
        # after merging the special modules, cut back to the top 5
        facts["decade_modules"] = _cut_module_top(dm, top_n=5)
    stats = getattr(f, "_timeline_stats", None) or {}
    if stats:
        # top 6 labels by count, descending, for the 【概览】 block ("本十年结怨9次…").
        # Only positive counts are taken: a zero entry such as "囚禁他人0次" is a program
        # placeholder (`stats["囚禁他人"]` is set to 0 unconditionally) and must not surface.
        top = [(k, v) for k, v in sorted(stats.items(), key=lambda kv: -kv[1])
               if v > 0][:6]
        facts["decade_stats"] = [f"{k}{v}次" for k, v in top]
    # consort-clan biographies (princess titles or daughters/sisters of a Chinese emperor only)
    pid = cache.get("player_id")
    if pid is not None:
        rec = (cache.get("characters") or {}).get(str(pid)) or {}
        # merge the marriage latch into the spouse set first, from the same source as
        # `_protagonist_facts`
        fam = f.merge_spouse_latch(rec.get("family") or {}, f.as_of)
        rec["family"] = fam
        spouse_ids = list(dict.fromkeys(
            (fam.get("primary_spouse") or []) + (fam.get("spouse") or [])
            + (fam.get("former_spouses") or [])))
        # the consort-clan sets and the affair thread share the in-window spouse set
        spouse_ids = f.spouses_in_window(spouse_ids)
        facts["imperial_spouses"] = _imperial_daughters_sisters(f, spouse_ids)
        # consort affair thread (per lover: identity plus the affair -> lovers -> soulmate arc)
        facts["consort_affairs"] = f.consort_affairs(pid, spouses=spouse_ids)
        # forced concubinage (the save's only concubinage record with an exact date)
        facts["forced_concubines"] = f.forced_concubine_lines()
        # a concubine's previous marriage is dissolved (the former spouse keeps only
        # `forced_spouse_concubine_marriage_opinion`)
        facts["concubine_divorces"] = f.concubine_divorce_lines()
    else:
        facts["imperial_spouses"] = []
        facts["consort_affairs"] = []
        facts["forced_concubines"] = []
        facts["concubine_divorces"] = []
    # 《家室列传》's chronicle is issued group by group -- "spouse one, with the children she bore,
    # then spouse two, with ..." -- one request per group (cap in JIASHI_GROUP_MAX)
    facts["household_groups"] = household_groups(f, facts)
    return facts


# ---------------------------------------------------------------------------
# 《家室列传》 household grouping -- one group = one spouse plus the children she bore
# ---------------------------------------------------------------------------
# The chronicle is one piece per spouse, not a single long essay, and the number of sections is
# always JIASHI_MID_MAX = 5 (6 pieces counting the opening), divided by material weight between
# the spouse pool and the children pool. Children with deeds get sections of their own
# (《诸子行迹》) while deedless infants stay with their birth mother: hanging every child under the
# mother buries appointments and marriages inside her condolence flow. Sending all 26 family
# members at once fed `jiashi_mid` about 11,895 characters for a 1200-1800 character body, i.e.
# 60-90 per person, leaving the model able only to list names; groups of 2-5 match material to
# space.
JIASHI_MID_MAX = 5
JIASHI_GROUP_MAX = JIASHI_MID_MAX      # old name kept for docs and scripts


def _jiashi_member_weight(facts, cid):
    """Material weight of a household member: event count plus weighted deeds, where a deed is
    titles/tenures (3), a marriage (2), children (2) or a seat note (3). Used to divide the
    chronicle slots between the spouse pool and the children pool."""
    p = (facts.get("characters") or {}).get(str(cid)) or {}
    n = len(p.get("events") or [])
    if p.get("titles_held"):
        n += 3
    if p.get("spouses"):
        n += 2
    if p.get("children"):
        n += 2
    if p.get("seat_note"):
        n += 3
    return n


def _jiashi_notable(facts, cid):
    """Whether this child holds land (a domain or title) -- only landed children get their own
    section. The test is `titles_held` (the tenure lines `_character_profiles` renders from the
    title history, family estate titles included), the same field `_jiashi_member_weight` counts
    as +3; a child known only through marriage, children or a seat note joins the last
    children's section instead (《其余子女》)."""
    p = (facts.get("characters") or {}).get(str(cid)) or {}
    return bool(p.get("titles_held"))


def _balance_segments(seq, weights, k):
    """Split a sequence into k segments, order preserved, minimizing the largest segment's weight
    sum (dynamic programming). Used for spouse sections: the "spouse one ... spouse N" order
    stays fixed while each section's material is balanced as evenly as possible."""
    seq, weights = list(seq), list(weights)
    n = len(seq)
    if k <= 1 or n <= k:
        return [[x] for x in seq][:n] if n <= k else [seq]
    # pref[i] = sum of the weights of the first i items
    pref = [0]
    for w in weights:
        pref.append(pref[-1] + w)
    INF = float("inf")
    # dp[i][j] = smallest possible largest-segment sum when the first i items are cut into j
    # segments
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    cut = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for j in range(1, k + 1):
        for i in range(1, n + 1):
            for p in range(j - 1, i):
                if dp[p][j - 1] == INF:
                    continue
                seg = pref[i] - pref[p]
                v = max(dp[p][j - 1], seg)
                if v < dp[i][j]:
                    dp[i][j] = v
                    cut[i][j] = p
    segs, i, j = [], n, k
    while j > 0:
        p = cut[i][j]
        segs.append(seq[p:i])
        i, j = p, j - 1
    segs.reverse()
    return [s for s in segs if s]


def household_groups(f, facts):
    """Household groups -> [{"label", "ids", "children", "kind": "spouse"|"child"|"sib",
    "mates": [...], "n_mates": n}, ...].

    One group is a spouse plus the children she bore, or a landed child on their own. The
    chronicle gets `JIASHI_MID_MAX` sections, split by material weight between the spouse pool
    and the children pool (n_kid = round(5*K/(K+S)), each non-empty pool at least 1, n_kid <= 4).
    Landed children (see `_jiashi_notable`) take a section each in descending weight and the
    rest join the trailing "其余子女" section; unlanded children follow their birth mother, and
    one whose mother is off the roster joins the trailing section too. Spouses are cut into
    n_wife segments in first-seen order before as_of, balanced and order-preserving, after being
    trimmed to those still married inside this piece's window (`f.spouses_in_window`). Siblings
    get one section. Each member id appears once; empty groups are not produced."""
    cache = f.cache
    pid = cache.get("player_id")
    if pid is None:
        return []
    rec = (cache.get("characters") or {}).get(str(pid)) or {}
    fam = f.merge_spouse_latch(rec.get("family") or {}, f.as_of)
    chars = cache.get("characters") or {}

    def _ids(key):
        return [int(x) for x in (fam.get(key) or [])
                if isinstance(x, int) or str(x).isdigit()]

    # spouse order: primary wife/husband -> other current spouses -> former spouses ->
    # concubines -> former concubines (deduplicated, order kept)
    spouses = []
    for key in ("primary_spouse", "spouse", "former_spouses",
                "concubine", "former_concubines"):
        for x in _ids(key):
            if x not in spouses:
                spouses.append(x)
    # keep only members that are sent to the model (those with too little data are dropped, the
    # same gate as `_character_profiles`)
    spouses = [x for x in spouses if str(x) in chars]
    # window trim: keep only spouses still married inside this piece's window (a final biography
    # spans a lifetime and never trims)
    spouses = f.spouses_in_window(spouses)

    # children and siblings
    kids = [x for x in _ids("child") if str(x) in chars]
    sibs = [x for x in _ids("siblings") if str(x) in chars]

    # child -> birth mother (cached family.mother; the paternal side is consulted when absent)
    kid_mother = {}
    for c in kids:
        cf = (chars.get(str(c)) or {}).get("family") or {}
        m = [int(x) for x in (cf.get("mother") or [])
             if isinstance(x, int) or str(x).isdigit()]
        kid_mother[c] = m[0] if m else None

    wt = lambda c: _jiashi_member_weight(facts, c)          # noqa: E731
    notable = sorted((c for c in kids if _jiashi_notable(facts, c)),
                     key=lambda c: (-wt(c), str(c)))
    # slot allocation between the spouse pool and the children pool
    slots = JIASHI_MID_MAX
    S = sum(wt(s) for s in spouses)
    K = sum(wt(c) for c in kids)
    if not kids:
        n_kid = 0
    elif not spouses:
        n_kid = slots
    else:
        share = (float(K) / (K + S)) if (K + S) else 0.0
        n_kid = max(1, min(int(round(slots * share)), slots - 1))
    n_wife = slots - n_kid if spouses else 0
    rest_sibs = [s for s in sibs if str(s) in chars and s not in kids]
    if rest_sibs and n_wife > 0:
        n_wife -= 1                     # reserve one section for "同胞手足"
        n_kid = slots - n_wife

    used, out = set(), []
    # ① spouse sections (n_wife segments, material balanced, order preserved), each taking the
    # deedless children of its own spouses along
    plain = [c for c in kids if c not in set(notable)]
    if n_wife > 0 and spouses:
        segs = _balance_segments(spouses, [wt(s) for s in spouses], n_wife)
        for si, seg in enumerate(segs):
            mem = [m for m in seg if m not in used]
            if not mem:
                continue
            kids_here = [c for c in plain
                         if kid_mother.get(c) in mem and c not in used]
            members = mem + kids_here
            used.update(members)
            names = [((facts["characters"].get(str(m)) or {}).get("name")
                      or f"配偶{m}") for m in mem]
            if len(names) == 1:
                label = names[0]
            elif si == len(segs) - 1 and len(segs) > 1:
                label = "其余妻室"
            else:
                label = f"{names[0]}等{len(names)}房"
            out.append({"label": label, "ids": members,
                        "names": names + [((facts["characters"].get(str(c)) or {})
                                           .get("name") or str(c))
                                          for c in kids_here],
                        "children": kids_here, "mates": mem,
                        "n_mates": len(mem), "kind": "spouse"})
    # ② children's sections (《诸子行迹》): landed children each get one in descending weight,
    # the rest fold into the last section
    kid_pool = [c for c in (notable + sorted(plain, key=lambda c: (-wt(c), str(c))))
                if c not in used]
    if n_kid > 0 and kid_pool:
        if n_kid == 1:
            chunks = [kid_pool]
        else:
            head = kid_pool[: n_kid - 1]
            tail = kid_pool[n_kid - 1:]
            chunks = [[c] for c in head] + ([tail] if tail else [])
        for chunk in chunks:
            mem = [c for c in chunk if c not in used]
            if not mem:
                continue
            used.update(mem)
            prof = facts["characters"].get(str(mem[0])) or {}
            if len(mem) == 1:
                label = prof.get("name") or f"子女{mem[0]}"
            else:
                label = "其余子女"
            out.append({"label": label, "ids": mem, "children": mem,
                        "names": [((facts["characters"].get(str(c)) or {})
                                   .get("name") or str(c)) for c in mem],
                        "mates": [], "n_mates": 0, "kind": "child"})
    # ③ siblings
    rest_sibs = [s for s in rest_sibs if s not in used]
    if rest_sibs:
        if len(out) >= slots:           # slots full -> fold into the last section
            out[-1]["ids"] = list(out[-1]["ids"]) + rest_sibs
            out[-1]["label"] = out[-1]["label"] + "与同胞"
        else:
            used.update(rest_sibs)
            out.append({"label": "同胞手足", "ids": rest_sibs, "children": [],
                        "mates": [], "n_mates": 0, "kind": "sib"})
    # fallback: anyone still unplaced (extreme data) folds into the last section
    left = [c for c in (kids + rest_sibs) if c not in used]
    if left:
        if out:
            out[-1]["ids"] = list(out[-1]["ids"]) + left
        else:
            out.append({"label": "其余门庭", "ids": left, "children": left,
                        "mates": [], "n_mates": 0, "kind": "child"})
    return out



def facts_to_text(facts, keys=None):
    """Join the fact set into plain text for the model (for debugging and logs)."""
    lines = []
    p = facts["protagonist"]
    # house name plus branch in natural language, no equals sign and no parenthetical:
    # 藤原氏 + 北家 joins as 藤原北家
    fam = p.get("house") or ""
    if fam and p.get("house_branch"):
        b = p["house_branch"]
        fam = f"{fam[:-1]}{b}" if fam.endswith("氏") else f"{fam}，{b}"
    lines.append(f"主角：{p.get('name')}，{fam}")
    for k in ("birth", "culture", "faith", "traits", "government"):
        if p.get(k):
            lines.append(f"{k}：{p[k]}")
    return "\n".join(lines)


